S._Surfaces = {}
S._MarkSurface = function(obj)
    if obj then table.insert(S._Surfaces, obj) end
    return obj
end

S._EachSurface = function(fn)
    local list = S._Surfaces or {}
    for i = #list, 1, -1 do
        local obj = list[i]
        if obj and obj.Parent then
            pcall(fn, obj)
        else
            table.remove(list, i)
        end
    end
end

