S.getRole = function(...) return getRole(...) end
function S:Destroy()
    if self.Destroyed then return end
    self.Destroyed = true
    self.AIChatEnabled = false
    pcall(function()
        LP.DevCameraOcclusionMode = _origCameraOcclusion
        LP.CameraMaxZoomDistance = _origMaxZoom
    end)
    pcall(function() if self._RestoreAvatarMods then self._RestoreAvatarMods() end end)
    pcall(function() if self._RestoreShaderState then self._RestoreShaderState() end end)
    pcall(function() if self._RestoreMovementState then self._RestoreMovementState() end end)
    pcall(function()
        for part, t in pairs(self.OriginalTransparencies) do if part and part.Parent then part.Transparency = t end end
    end)
    if self.VoidPlatform then pcall(function() self.VoidPlatform:Destroy() end); self.VoidPlatform = nil end
    if ncPlat then pcall(function() ncPlat:Destroy() end); ncPlat = nil end
    for _, c in ipairs(self.Connections) do pcall(function() c:Disconnect() end) end
    table.clear(self.Connections)
    for _, thread in ipairs(self.Tasks) do pcall(task.cancel, thread) end
    table.clear(self.Tasks)
    for i = #self.Cleanups, 1, -1 do pcall(self.Cleanups[i]) end
    table.clear(self.Cleanups)
    for key, sound in pairs(SndCache) do
        pcall(function() sound:Stop(); sound:Destroy() end)
        SndCache[key] = nil
    end
    if self.Gui then pcall(function() self.Gui:Destroy() end) end
    if _G.MM2_Visuals_Script == self then _G.MM2_Visuals_Script = nil end
end
local function tc(conn) table.insert(S.Connections, conn); return conn end
local function cleanup(fn) table.insert(S.Cleanups, fn); return fn end
local function tt(fn, ...)
    local args = table.pack(...)
    local thread
    thread = task.defer(function()
        local ok, err = xpcall(function()
            fn(table.unpack(args, 1, args.n))
        end, debug.traceback)
        for i = #S.Tasks, 1, -1 do
            if S.Tasks[i] == thread then
                table.remove(S.Tasks, i)
                break
            end
        end
        if not ok and not S.Destroyed then
            warn("[INERTIA Task] " .. tostring(err))
        end
    end)
    table.insert(S.Tasks, thread)
    return thread
end
S._RememberHumanoid = function(humanoid)
    if not humanoid or S._MovementOriginals[humanoid] then return end
    local original = {
        WalkSpeed = humanoid.WalkSpeed,
        JumpPower = humanoid.JumpPower,
        UseJumpPower = humanoid.UseJumpPower,
        PlatformStand = humanoid.PlatformStand,
        AutoRotate = humanoid.AutoRotate,
        StateEnabled = {},
    }
    for _, stateType in ipairs(S._MovementStates) do
        local ok, enabled = pcall(humanoid.GetStateEnabled, humanoid, stateType)
        if ok then original.StateEnabled[stateType] = enabled end
    end
    S._MovementOriginals[humanoid] = original
end
S._SetOwnedAnchored = function(part, value)
    if not part or not part:IsA("BasePart") then return end
    if S._AnchoredOriginals[part] == nil then S._AnchoredOriginals[part] = part.Anchored end
    part.Anchored = value
end
S._RestoreOwnedAnchored = function(part)
    if not part or not part:IsA("BasePart") then return end
    local original = S._AnchoredOriginals[part]
    if original ~= nil then
        part.Anchored = original
        S._AnchoredOriginals[part] = nil
    end
end
S._RestoreMovementState = function()
    S.Fly, S.NoClip, S.FastAutofarm, S.FakeLag = false, false, false, false
    S.PixelSurf, S.Spinbot, S.AntiRagdoll = false, false, false

    if S._ncTouched then
        for part, wasCollidable in pairs(S._ncTouched) do
            if part and part.Parent then pcall(function() part.CanCollide = wasCollidable end) end
        end
        S._ncTouched, S._ncParts, S._ncChar = nil, {}, nil
    end
    for humanoid, original in pairs(S._MovementOriginals) do
        if humanoid and humanoid.Parent then
            pcall(function()
                humanoid.WalkSpeed = original.WalkSpeed
                humanoid.JumpPower = original.JumpPower
                humanoid.UseJumpPower = original.UseJumpPower
                humanoid.PlatformStand = original.PlatformStand
                humanoid.AutoRotate = original.AutoRotate
                for stateType, enabled in pairs(original.StateEnabled) do
                    humanoid:SetStateEnabled(stateType, enabled)
                end
            end)
        end
        S._MovementOriginals[humanoid] = nil
    end
    for part, original in pairs(S._AnchoredOriginals) do
        if part and part.Parent then pcall(function() part.Anchored = original end) end
        S._AnchoredOriginals[part] = nil
    end

    local character = LP.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if root then
        for _, name in ipairs({ "FlyBV", "FlyBG" }) do
            local mover = root:FindFirstChild(name)
            if mover then pcall(function() mover:Destroy() end) end
        end
    end
end

local function isWhitelisted(p) return p ~= nil and S.Whitelist and S.Whitelist[p.Name] == true end
local function snd(id, pitch, vol)
    pitch = tonumber(pitch) or 1
    vol = tonumber(vol) or 0.3
    tt(function() pcall(function()
        if S.Destroyed then return end
        if type(id) ~= "string" or id == "" then return end
        local k = id .. "|" .. tostring(pitch)
        local s = SndCache[k]
        if not s or not s.Parent then
            s = Instance.new("Sound"); s.SoundId = id; s.Parent = SoundService; SndCache[k] = s
        end
        s.PlaybackSpeed = pitch; s.Volume = vol
        pcall(function() ContentProvider:PreloadAsync({s}) end)
        if S.Destroyed or not s.Parent then return end
        if s.IsPlaying then s:Stop() end
        s.TimePosition = 0
        pcall(function() s:Play() end)
    end) end)
end
S._PlaySoundSafe = function(s)
    if not s or not s:IsA("Sound") or s.SoundId == "" then return end

    pcall(function() s:SetAttribute("InertiaOwned", true) end)
    local function startPlayback()
        if S.Destroyed or not s.Parent then return end
        if s.IsPlaying then s:Stop() end
        s.TimePosition = 0
        pcall(function() s:Play() end)
    end
    tt(function()
        pcall(function() ContentProvider:PreloadAsync({ s }) end)
        startPlayback()
    end)
end

