    card.Size = UDim2.fromScale(1, 1)
    card.ZIndex = 902
    Corner(card, 12)
    local tst = Stroke(card, T.Bd2, 1, 0.14); pcall(function() tst:SetAttribute("ThemeColorRole_Color", "Bd2") end)

    local cardGradient = Instance.new("UIGradient")
