S._ThemeRoles = {
    "BG", "Sidebar", "Card", "Elev", "Hover", "ActiveBg", "Accent", "AccentSoft",
    "Tx", "Tx2", "Tx3", "Tx4", "Bd", "Bd2", "TgOn", "TgOff", "KnobOn", "KnobOff", "Glow",
}
local function _buildEmbeddedThemeEditor()
    local roleHost = Instance.new("Frame")
    roleHost.Name = "ThemeEditor"
    roleHost.Parent = mScroll
    roleHost.LayoutOrder = 8.6
    roleHost.BackgroundTransparency = 1
    roleHost.Size = UDim2.new(1, 0, 0, 0)
    roleHost.AutomaticSize = Enum.AutomaticSize.Y
    roleHost.Visible = false
    local roleLayout = Instance.new("UIListLayout")
    roleLayout.Parent = roleHost
    roleLayout.SortOrder = Enum.SortOrder.LayoutOrder
    roleLayout.Padding = UDim.new(0, 4)

    local selected = "Card"
    local swatch = Instance.new("Frame")
    swatch.Name = "Swatch"
    swatch.Parent = roleHost
    swatch.LayoutOrder = 0
    swatch.Size = UDim2.new(1, 0, 0, 24)
    swatch.BorderSizePixel = 0
    swatch.BackgroundColor3 = T[selected] or Color3.new(1, 1, 1)
    Corner(swatch, 6)
    Stroke(swatch, T.Bd, 1, 0.4)

    local rS, gS, bS, refreshGrid, selectRole
    local function currentColor()
        return (Themes.Custom and Themes.Custom[selected]) or T[selected] or Color3.new(1, 1, 1)
    end
    local function pushColor()
        local c = Color3.fromRGB(
            math.clamp(tonumber(S._ThemeR) or 0, 0, 255),
            math.clamp(tonumber(S._ThemeG) or 0, 0, 255),
            math.clamp(tonumber(S._ThemeB) or 0, 0, 255))
        Themes.Custom = Themes.Custom or {}
        Themes.Custom[selected] = c
        swatch.BackgroundColor3 = c
        S.SelectedTheme = "Custom"
        if applyTheme then pcall(applyTheme, "Custom") end
        if refreshGrid then refreshGrid() end
        pcall(function() if S.SaveConfig then S.SaveConfig("_autoload") end end)
    end
    local function loadRole()
        local c = currentColor()
        S._ThemeR, S._ThemeG = math.round(c.R * 255), math.round(c.G * 255)
        S._ThemeB = math.round(c.B * 255)
        swatch.BackgroundColor3 = c
        if rS then rS.set(S._ThemeR); gS.set(S._ThemeG); bS.set(S._ThemeB) end
        if refreshGrid then refreshGrid() end
    end

    local roleGrid = Instance.new("Frame")
    roleGrid.Name = "RoleGrid"
    roleGrid.Parent = roleHost
    roleGrid.LayoutOrder = 0.5
    roleGrid.BackgroundTransparency = 1
    roleGrid.Size = UDim2.new(1, 0, 0, 0)
    roleGrid.AutomaticSize = Enum.AutomaticSize.Y
    do
        local rgl = Instance.new("UIGridLayout")
        rgl.CellSize = UDim2.fromOffset(52, 32)
        rgl.CellPadding = UDim2.fromOffset(4, 4)
        rgl.SortOrder = Enum.SortOrder.LayoutOrder
        rgl.Parent = roleGrid
    end
    local roleSwatches = {}
    refreshGrid = function()
        for _, role in ipairs(S._ThemeRoles) do
            local sw = roleSwatches[role]
            if sw then
                local c = (Themes.Custom and Themes.Custom[role]) or T[role] or Color3.new(1, 1, 1)
                sw.btn.BackgroundColor3 = c

                local lum = 0.299 * c.R + 0.587 * c.G + 0.114 * c.B
                sw.btn.TextColor3 = lum > 0.55 and Color3.fromRGB(20, 20, 20) or Color3.fromRGB(235, 235, 235)
                sw.stroke.Transparency = (role == selected) and 0 or 1
            end
        end
    end
    selectRole = function(role)
        selected = role
        loadRole()
    end
    for i, role in ipairs(S._ThemeRoles) do
        local b = Instance.new("TextButton")
        b.Name = role
        b.LayoutOrder = i
        b.AutoButtonColor = false
        b.Text = role
        b.Font = F
        b.TextSize = 9
        b.TextTruncate = Enum.TextTruncate.AtEnd
        b.BackgroundColor3 = T[role] or Color3.new(1, 1, 1)
        b.BorderSizePixel = 0
        b.ZIndex = roleHost.ZIndex + 1
        b.Parent = roleGrid
        Corner(b, 5)
        local bs = Stroke(b, T.Accent, 2, 1)
        roleSwatches[role] = { btn = b, stroke = bs }
        b.MouseButton1Click:Connect(function() SFX.Click(); selectRole(role) end)
    end
    refreshGrid()

    S._mkCycle(roleHost, "Role", S._ThemeRoles, selected, function(v)
        selectRole(v)
    end, 1)
    rS = mkSlider(roleHost, "Red", 0, 255, 0, function(v) S._ThemeR = v; pushColor() end, 2, true)
    gS = mkSlider(roleHost, "Green", 0, 255, 0, function(v) S._ThemeG = v; pushColor() end, 3, true)
    bS = mkSlider(roleHost, "Blue", 0, 255, 0, function(v) S._ThemeB = v; pushColor() end, 4, true)
    loadRole()

    S._mkAction(roleHost, "Reset This Role", function()
        Themes.Custom[selected] = Themes.Default[selected]
        if applyTheme then pcall(applyTheme, "Custom") end
        loadRole()
        Notify("Theme", "Reset " .. selected, 2)
    end, 5)
    S._mkAction(roleHost, "Reset Whole Theme", function()
        Themes.Custom = table.clone(Themes.Default)
        if applyTheme then pcall(applyTheme, "Custom") end
        loadRole()
        Notify("Theme", "Custom theme cleared", 2)
    end, 6)

    local function openEmbeddedThemeEditor()
        roleHost.Visible = not roleHost.Visible
        editCustomBtn.Text = roleHost.Visible and "Hide Custom Theme Editor" or "Edit Custom Theme..."
        if roleHost.Visible then loadRole() end
    end
    return openEmbeddedThemeEditor
end

S._BuildThemeWindow = function()
    if MOBILE then return end
    local win, selected, refreshSwatches, loadRole, activeTab
    local swatchRows, tabBtns = {}, {}
    local rSet, gSet, bSet, hexBox, roleHint

    local TABS = {
        { name = "Window",  roles = { "BG", "Bd", "Bd2", "Glow" } },
        { name = "Sidebar", roles = { "Sidebar", "ActiveBg", "Hover" } },
        { name = "Cards",   roles = { "Card", "Elev", "Accent", "AccentSoft", "TgOn", "TgOff", "KnobOn", "KnobOff" } },
        { name = "Text",    roles = { "Tx", "Tx2", "Tx3", "Tx4" } },
        { name = "HUD",     roles = { "Card", "Elev", "Accent", "Tx", "Tx2", "Bd2" } },
    }

    local FONTS = {
        Gotham     = { Enum.Font.Gotham, Enum.Font.GothamMedium, Enum.Font.GothamBold },
        SourceSans = { Enum.Font.SourceSans, Enum.Font.SourceSansSemibold, Enum.Font.SourceSansBold },
        Arial      = { Enum.Font.Arial, Enum.Font.Arial, Enum.Font.ArialBold },
        Nunito     = { Enum.Font.Nunito, Enum.Font.Nunito, Enum.Font.Nunito },
        Ubuntu     = { Enum.Font.Ubuntu, Enum.Font.Ubuntu, Enum.Font.Ubuntu },
        Code       = { Enum.Font.Code, Enum.Font.Code, Enum.Font.Code },
    }
    local FONT_NAMES = { "Gotham", "SourceSans", "Arial", "Nunito", "Ubuntu", "Code" }
    local ROLE_HINTS = {
        BG = "Main window canvas", Bd = "Primary borders", Bd2 = "Soft separators", Glow = "Window glow",
        Sidebar = "Navigation surface", ActiveBg = "Selected navigation", Hover = "Hover feedback",
        Card = "Section cards", Elev = "Raised controls", Accent = "Primary accent", AccentSoft = "Soft accent fill",
        TgOn = "Enabled toggles", TgOff = "Disabled toggles", KnobOn = "Enabled knob", KnobOff = "Disabled knob",
        Tx = "Primary text", Tx2 = "Secondary text", Tx3 = "Muted text", Tx4 = "Quiet text",
    }

    local function colOf(role)
        return (Themes.Custom and Themes.Custom[role]) or T[role] or Color3.new(1, 1, 1)
    end

    local function applyFont(name)
        local fam = FONTS[name]
        if not fam or not SG then return end
        S.UIFont = name
        for _, o in ipairs(SG:GetDescendants()) do
            if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then

                local tier = o:GetAttribute("InertiaFontTier")
                if not tier then
                    local f = o.Font
                    tier = (f == FB or f == Enum.Font.SourceSansBold or f == Enum.Font.ArialBold) and 3
                        or (f == FM or f == Enum.Font.SourceSansSemibold) and 2
                        or 1
                    pcall(function() o:SetAttribute("InertiaFontTier", tier) end)
                end
                pcall(function() o.Font = fam[tier] or fam[1] end)
            end
        end
    end
    S._ApplyUIFont = applyFont

    local function mkBar(parent, label, order, onChange)
        local row = Instance.new("Frame")
        row.Parent = parent
        row.LayoutOrder = order
        row.Size = UDim2.new(1, 0, 0, 30)
        row.BackgroundTransparency = 1

        local cap = Instance.new("TextLabel")
        cap.Parent = row
        cap.BackgroundTransparency = 1
        cap.Size = UDim2.new(0, 22, 1, 0)
        cap.Font = FM
        cap.TextSize = 12
        cap.Text = label
        cap.TextColor3 = T.Tx3
        pcall(function() cap:SetAttribute("ThemeColorRole_TextColor3", "Tx3") end)

        local track = Instance.new("TextButton")
        track.Parent = row
        track.AutoButtonColor = false
        track.Text = ""
        track.AnchorPoint = Vector2.new(0, 0.5)
        track.Position = UDim2.new(0, 26, 0.5, 0)
        track.Size = UDim2.new(1, -74, 0, 6)
        track.BackgroundColor3 = T.Elev
        pcall(function() track:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
        track.BorderSizePixel = 0
        Corner(track, 3)

        local fill = Instance.new("Frame")
        fill.Parent = track
        fill.Size = UDim2.fromScale(0, 1)
        fill.BackgroundColor3 = T.Accent
        pcall(function() fill:SetAttribute("ThemeColorRole_BackgroundColor3", "Accent") end)
        fill.BorderSizePixel = 0
        Corner(fill, 3)

        local val = Instance.new("TextLabel")
        val.Parent = row
        val.BackgroundTransparency = 1
        val.AnchorPoint = Vector2.new(1, 0)
        val.Position = UDim2.new(1, 0, 0, 0)
        val.Size = UDim2.new(0, 42, 1, 0)
        val.Font = FM
        val.TextSize = 12
        val.TextXAlignment = Enum.TextXAlignment.Right
        val.TextColor3 = T.Tx2
        pcall(function() val:SetAttribute("ThemeColorRole_TextColor3", "Tx2") end)

        local dragging = false
        local activeInput = nil
        local function set(v, fire)
            v = math.clamp(math.floor(v + 0.5), 0, 255)
            fill.Size = UDim2.fromScale(v / 255, 1)
            val.Text = tostring(v)
            if fire then onChange(v) end
        end
        local function fromX(x)
            local a = track.AbsolutePosition.X
            local w = math.max(track.AbsoluteSize.X, 1)
            set(math.clamp((x - a) / w, 0, 1) * 255, true)
        end
        track.InputBegan:Connect(function(i)
            if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                activeInput = i
                fromX(i.Position.X)
            end
        end)
        track.InputEnded:Connect(function(i)
            if i == activeInput then dragging = false; activeInput = nil end
        end)
        tc(UIS.InputChanged:Connect(function(i)
            local isMouseMove = activeInput and activeInput.UserInputType == Enum.UserInputType.MouseButton1
                and i.UserInputType == Enum.UserInputType.MouseMovement
            if dragging and (i == activeInput or isMouseMove) then
                fromX(i.Position.X)
            end
        end))
        tc(UIS.InputEnded:Connect(function(i)
            if i == activeInput or (activeInput and activeInput.UserInputType == Enum.UserInputType.MouseButton1
                and i.UserInputType == Enum.UserInputType.MouseButton1) then
                dragging = false
                activeInput = nil
            end
        end))
        return { set = function(v) set(v, false) end }
    end

    local function pushColor()
        local c = Color3.fromRGB(
            math.clamp(tonumber(S._ThemeR) or 0, 0, 255),
            math.clamp(tonumber(S._ThemeG) or 0, 0, 255),
            math.clamp(tonumber(S._ThemeB) or 0, 0, 255))
        Themes.Custom = Themes.Custom or {}
        Themes.Custom[selected] = c
        S.SelectedTheme = "Custom"
        pcall(applyTheme, "Custom")
        if refreshSwatches then refreshSwatches() end
        if hexBox and not hexBox:IsFocused() then
            hexBox.Text = string.format("#%02X%02X%02X", math.round(c.R * 255), math.round(c.G * 255), math.round(c.B * 255))
        end
        pcall(function() if S.SaveConfig then S.SaveConfig("_autoload") end end)
    end

    local function build()
        win = Instance.new("Frame")
        win.Name = "InertiaThemeWindow"
        win.Parent = SG
        win.AnchorPoint = Vector2.new(0.5, 0.5)
        win.Position = UDim2.fromScale(0.5, 0.5)
        win.Size = UDim2.fromOffset(840, 520)
        win.BackgroundColor3 = T.BG
        pcall(function() win:SetAttribute("ThemeColorRole_BackgroundColor3", "BG") end)
        win.BorderSizePixel = 0
        win.ZIndex = 4000
        win.Visible = false
        Corner(win, 12)
        Stroke(win, T.Bd2, 1, 0.2)
        local windowScale = Instance.new("UIScale")
        windowScale.Parent = win
        local viewportConnection = nil
        local function fitWindowToViewport()
            local camera = workspace.CurrentCamera
            local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
            local fit = math.min((viewport.X - 24) / 840, (viewport.Y - 24) / 520)
            windowScale.Scale = math.clamp(fit, 0.2, 1)
            if S._ClampHUDFrame then pcall(S._ClampHUDFrame, win) end
        end
        local function bindThemeViewport()
            if viewportConnection then viewportConnection:Disconnect(); viewportConnection = nil end
            local camera = workspace.CurrentCamera
            if camera then viewportConnection = camera:GetPropertyChangedSignal("ViewportSize"):Connect(fitWindowToViewport) end
            fitWindowToViewport()
        end
        tc(workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(bindThemeViewport))
        cleanup(function() if viewportConnection then viewportConnection:Disconnect(); viewportConnection = nil end end)
        bindThemeViewport()

        local bar = Instance.new("TextButton")
        bar.Parent = win
        bar.AutoButtonColor = false
        bar.Text = ""
        bar.Size = UDim2.new(1, 0, 0, 38)
        bar.BackgroundColor3 = T.Sidebar
        pcall(function() bar:SetAttribute("ThemeColorRole_BackgroundColor3", "Sidebar") end)
        bar.BorderSizePixel = 0
        bar.ZIndex = 4001
        Corner(bar, 12)

        local title = Instance.new("TextLabel")
        title.Parent = bar
        title.BackgroundTransparency = 1
        title.Position = UDim2.new(0, 14, 0, 0)
        title.Size = UDim2.new(0, 180, 1, 0)
        title.Font = FB
        title.TextSize = 14
        title.TextXAlignment = Enum.TextXAlignment.Left
        title.Text = "Theme Editor"
        title.TextColor3 = T.Tx
        title.ZIndex = 4002
        pcall(function() title:SetAttribute("ThemeColorRole_TextColor3", "Tx") end)

        local subtitle = Instance.new("TextLabel")
        subtitle.Parent = bar
        subtitle.BackgroundTransparency = 1
        subtitle.Position = UDim2.new(0, 148, 0, 0)
        subtitle.Size = UDim2.new(1, -210, 1, 0)
        subtitle.Font = FM
        subtitle.TextSize = 10
        subtitle.TextXAlignment = Enum.TextXAlignment.Left
        subtitle.Text = "LIVE PALETTE  /  AUTO-SAVED"
        subtitle.TextColor3 = T.Tx4
        subtitle.ZIndex = 4002
        pcall(function() subtitle:SetAttribute("ThemeColorRole_TextColor3", "Tx4") end)

        local close = Instance.new("TextButton")
        close.Parent = bar
        close.AnchorPoint = Vector2.new(1, 0.5)
        close.Position = UDim2.new(1, -10, 0.5, 0)
        close.Size = UDim2.fromOffset(24, 24)
        close.BackgroundColor3 = T.Elev
        pcall(function() close:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
        close.BorderSizePixel = 0
        close.AutoButtonColor = false
        close.Font = FM
        close.TextSize = 14
        close.Text = "x"
        close.TextColor3 = T.Tx2
        close.ZIndex = 4002
        pcall(function() close:SetAttribute("ThemeColorRole_TextColor3", "Tx2") end)
        Corner(close, 6)
        tc(close.MouseButton1Click:Connect(function()
            SFX.Click()
            win.Visible = false
            if S._SettingsWasVisible then
                pcall(function() S._SettingsModal.Visible = true end)
            end
            S._SettingsWasVisible = nil
        end))

        do
            local dragging, activeInput, startCenter, startInput = false, nil, nil, nil
            tc(bar.InputBegan:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
                    if activeInput then return end
                    dragging = true
                    activeInput = i
                    startInput = Vector2.new(i.Position.X, i.Position.Y)
                    startCenter = win.AbsolutePosition + win.AbsoluteSize / 2
                end
            end))
            tc(UIS.InputChanged:Connect(function(i)
                local mouseMove = activeInput and activeInput.UserInputType == Enum.UserInputType.MouseButton1
                    and i.UserInputType == Enum.UserInputType.MouseMovement
                if dragging and (i == activeInput or mouseMove) then
                    local inputPoint = Vector2.new(i.Position.X, i.Position.Y)
                    local d = inputPoint - startInput
                    local vp = workspace.CurrentCamera and workspace.CurrentCamera.ViewportSize or Vector2.new(1280, 720)
                    local half = win.AbsoluteSize / 2
                    local center = startCenter + d
                    local function fitAxis(value, radius, extent)
                        if radius * 2 >= extent then return extent / 2 end
                        return math.clamp(value, radius, extent - radius)
                    end
                    center = Vector2.new(fitAxis(center.X, half.X, vp.X), fitAxis(center.Y, half.Y, vp.Y))
                    win.Position = UDim2.fromOffset(center.X, center.Y)
                end
            end))
            tc(UIS.InputEnded:Connect(function(i)
                if i == activeInput or (activeInput and activeInput.UserInputType == Enum.UserInputType.MouseButton1
                    and i.UserInputType == Enum.UserInputType.MouseButton1) then
                    dragging = false
                    activeInput = nil
                end
            end))
        end

        local tabCol = Instance.new("Frame")
        tabCol.Parent = win
        tabCol.Position = UDim2.new(0, 10, 0, 48)
        tabCol.Size = UDim2.new(0, 124, 1, -58)
        tabCol.BackgroundTransparency = 1
        tabCol.ZIndex = 4001
        local tl = Instance.new("UIListLayout")
        tl.Parent = tabCol
        tl.Padding = UDim.new(0, 5)
        tl.SortOrder = Enum.SortOrder.LayoutOrder

        local mid = Instance.new("Frame")
        mid.Parent = win
        mid.Position = UDim2.new(0, 142, 0, 48)
        mid.Size = UDim2.new(0, 250, 1, -58)
        mid.BackgroundColor3 = T.Card
        pcall(function() mid:SetAttribute("ThemeColorRole_BackgroundColor3", "Card") end)
        mid.BorderSizePixel = 0
        mid.ZIndex = 4001
        Corner(mid, 8)
        Stroke(mid, T.Bd, 1, 0.4)
        Pad(mid, 10, 10, 10, 10)
        local ml = Instance.new("UIListLayout")
        ml.Parent = mid
        ml.Padding = UDim.new(0, 5)
        ml.SortOrder = Enum.SortOrder.LayoutOrder

        local roleList = Instance.new("ScrollingFrame")
        roleList.Parent = mid
        roleList.LayoutOrder = 1
        roleList.Size = UDim2.new(1, 0, 0, 210)
        roleList.BackgroundTransparency = 1
        roleList.BorderSizePixel = 0
        roleList.ScrollBarThickness = 3
        roleList.AutomaticCanvasSize = Enum.AutomaticSize.Y
        roleList.CanvasSize = UDim2.new()
        roleList.ZIndex = 4002

        Pad(roleList, 2, 2, 3, 3)
        local rl = Instance.new("UIListLayout")
        rl.Parent = roleList
        rl.Padding = UDim.new(0, 4)
        rl.SortOrder = Enum.SortOrder.LayoutOrder

        roleHint = Instance.new("TextLabel")
        roleHint.Parent = mid
        roleHint.LayoutOrder = 2
        roleHint.Size = UDim2.new(1, 0, 0, 18)
        roleHint.BackgroundTransparency = 1
        roleHint.Font = FM
        roleHint.TextSize = 10
        roleHint.TextXAlignment = Enum.TextXAlignment.Left
        roleHint.TextColor3 = T.Tx4
        roleHint.ZIndex = 4002
        pcall(function() roleHint:SetAttribute("ThemeColorRole_TextColor3", "Tx4") end)

        rSet = mkBar(mid, "R", 3, function(v) S._ThemeR = v; pushColor() end)
        gSet = mkBar(mid, "G", 4, function(v) S._ThemeG = v; pushColor() end)
        bSet = mkBar(mid, "B", 5, function(v) S._ThemeB = v; pushColor() end)

        local function mkFlatBtn(parent, text, order, fn)
            local b = Instance.new("TextButton")
            b.Parent = parent
            b.LayoutOrder = order
            b.Size = UDim2.new(1, 0, 0, 26)
            b.BackgroundColor3 = T.Elev
            pcall(function() b:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
            b.BorderSizePixel = 0
            b.AutoButtonColor = false
            b.Font = FM
            b.TextSize = 12
            b.Text = text
            b.TextColor3 = T.Tx2
            b.ZIndex = 4002
            pcall(function() b:SetAttribute("ThemeColorRole_TextColor3", "Tx2") end)
            Corner(b, 6)
            b.MouseButton1Click:Connect(function() SFX.Click(); fn(b) end)
            return b
        end

        local fontIdx = 1
        for i, n in ipairs(FONT_NAMES) do if n == S.UIFont then fontIdx = i end end
        local fontBtn
        hexBox = Instance.new("TextBox")
        hexBox.Parent = mid
        hexBox.LayoutOrder = 6
        hexBox.Size = UDim2.new(1, 0, 0, 26)
        hexBox.BackgroundColor3 = T.Elev
        hexBox.BorderSizePixel = 0
        hexBox.ClearTextOnFocus = false
        hexBox.Font = FM
        hexBox.TextSize = 12
        hexBox.PlaceholderText = "#RRGGBB"
        hexBox.TextColor3 = T.Tx2
        hexBox.PlaceholderColor3 = T.Tx4
        hexBox.ZIndex = 4002
        Corner(hexBox, 6)
        pcall(function()
            hexBox:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev")
            hexBox:SetAttribute("ThemeColorRole_TextColor3", "Tx2")
        end)
        hexBox.FocusLost:Connect(function()
            local raw = hexBox.Text:gsub("#", ""):gsub("%s", "")
            if raw:match("^[%x][%x][%x][%x][%x][%x]$") then
                S._ThemeR = tonumber(raw:sub(1, 2), 16)
                S._ThemeG = tonumber(raw:sub(3, 4), 16)
                S._ThemeB = tonumber(raw:sub(5, 6), 16)
                rSet.set(S._ThemeR); gSet.set(S._ThemeG); bSet.set(S._ThemeB)
                pushColor()
            else
                loadRole()
            end
        end)

        fontBtn = mkFlatBtn(mid, "Font: " .. FONT_NAMES[fontIdx], 7, function()
            fontIdx = fontIdx % #FONT_NAMES + 1
            fontBtn.Text = "Font: " .. FONT_NAMES[fontIdx]
            applyFont(FONT_NAMES[fontIdx])
            pcall(function() if S.SaveConfig then S.SaveConfig("_autoload") end end)
        end)
        S._RefreshThemeEditor = function()
            fontIdx = table.find(FONT_NAMES, S.UIFont) or 1
            if fontBtn and fontBtn.Parent then fontBtn.Text = "Font: " .. FONT_NAMES[fontIdx] end
            if loadRole then pcall(loadRole) end
        end
        mkFlatBtn(mid, "Reset This Role", 8, function()
            Themes.Custom[selected] = Themes.Default[selected]
            pcall(applyTheme, "Custom")
            loadRole()
        end)
        mkFlatBtn(mid, "Reset Whole Theme", 9, function()
            Themes.Custom = table.clone(Themes.Default)
            S.SelectedTheme = "Default"
            pcall(applyTheme, "Default")
            loadRole()
            pcall(function() if S.SaveConfig then S.SaveConfig("_autoload") end end)
            Notify("Theme", "Back to the stock theme", 2)
        end)

        local prev = Instance.new("Frame")
        prev.Parent = win
        prev.Position = UDim2.new(0, 400, 0, 48)
        prev.Size = UDim2.new(1, -410, 1, -58)
        prev.BackgroundColor3 = T.BG
        pcall(function() prev:SetAttribute("ThemeColorRole_BackgroundColor3", "BG") end)
        prev.BorderSizePixel = 0
        prev.ClipsDescendants = true
        prev.ZIndex = 4001
        Corner(prev, 8)
        Stroke(prev, T.Bd2, 1, 0.3)

        local function box(parent, pos, size, role, z, corner)
            local f = Instance.new("Frame")
            f.Parent = parent
            f.Position = pos
            f.Size = size
            f.BackgroundColor3 = T[role]
            pcall(function() f:SetAttribute("ThemeColorRole_BackgroundColor3", role) end)
            f.BorderSizePixel = 0
            f.ZIndex = z
            Corner(f, corner or 6)
            return f
        end
        local function text(parent, pos, size, str, role, size2, font)
            local l = Instance.new("TextLabel")
            l.Parent = parent
            l.Position = pos
            l.Size = size
            l.BackgroundTransparency = 1
            l.Font = font or FM
            l.TextSize = size2 or 12
            l.TextXAlignment = Enum.TextXAlignment.Left
            l.Text = str
            l.TextColor3 = T[role]
            l.ZIndex = 4004
            pcall(function() l:SetAttribute("ThemeColorRole_TextColor3", role) end)
            return l
        end

        local side = box(prev, UDim2.new(0, 10, 0, 10), UDim2.new(0, 74, 1, -20), "Sidebar", 4002, 8)
        box(side, UDim2.new(0, 6, 0, 10), UDim2.new(1, -12, 0, 22), "ActiveBg", 4003, 5)
        text(side, UDim2.new(0, 12, 0, 10), UDim2.new(1, -16, 0, 22), "Combat", "Tx", 11)
        box(side, UDim2.new(0, 6, 0, 36), UDim2.new(1, -12, 0, 22), "Hover", 4003, 5)
        text(side, UDim2.new(0, 12, 0, 36), UDim2.new(1, -16, 0, 22), "Visuals", "Tx3", 11)
        text(side, UDim2.new(0, 12, 0, 62), UDim2.new(1, -16, 0, 22), "Player", "Tx4", 11)

        local card = box(prev, UDim2.new(0, 94, 0, 10), UDim2.new(1, -104, 0, 132), "Card", 4002, 8)
        Stroke(card, T.Bd, 1, 0.4)
        text(card, UDim2.new(0, 10, 0, 6), UDim2.new(1, -20, 0, 18), "Visual Preview", "Tx", 12, FB)
        text(card, UDim2.new(0, 10, 0, 30), UDim2.new(1, -70, 0, 18), "Shaders", "Tx2", 12)
        local tgOn = box(card, UDim2.new(1, -48, 0, 32), UDim2.fromOffset(34, 16), "TgOn", 4003, 8)
        box(tgOn, UDim2.new(1, -15, 0.5, -6), UDim2.fromOffset(12, 12), "KnobOn", 4004, 6)
        text(card, UDim2.new(0, 10, 0, 54), UDim2.new(1, -70, 0, 18), "Atmosphere", "Tx2", 12)
        local tgOff = box(card, UDim2.new(1, -48, 0, 56), UDim2.fromOffset(34, 16), "TgOff", 4003, 8)
        box(tgOff, UDim2.new(0, 3, 0.5, -6), UDim2.fromOffset(12, 12), "KnobOff", 4004, 6)
        text(card, UDim2.new(0, 10, 0, 78), UDim2.new(1, -20, 0, 18), "Bloom Intensity", "Tx3", 12)
        local tr = box(card, UDim2.new(0, 10, 0, 102), UDim2.new(1, -20, 0, 6), "Elev", 4003, 3)
        box(tr, UDim2.new(0, 0, 0, 0), UDim2.fromScale(0.55, 1), "Accent", 4004, 3)

        local hud = box(prev, UDim2.new(0, 94, 0, 152), UDim2.new(1, -104, 0, 40), "Elev", 4002, 8)
        Stroke(hud, T.Bd2, 1, 0.4)
        box(hud, UDim2.new(0, 10, 0.5, -4), UDim2.fromOffset(8, 8), "Accent", 4003, 4)
        text(hud, UDim2.new(0, 26, 0, 0), UDim2.new(1, -36, 1, 0), "MURDERER   38ms   240fps", "Tx2", 11)

        local swatchBig = box(prev, UDim2.new(0, 94, 0, 202), UDim2.new(1, -104, 0, 34), "Accent", 4002, 8)
        local swatchTxt = text(swatchBig, UDim2.new(0, 10, 0, 0), UDim2.new(1, -20, 1, 0), "Accent", "BG", 12, FB)
        swatchTxt.ZIndex = 4005

        local rolePreview = box(prev, UDim2.new(0, 94, 0, 246), UDim2.new(1, -104, 1, -256), "Card", 4002, 8)
        local rolePreviewStroke = Stroke(rolePreview, T.Bd2, 1, 0.38)
        pcall(function() rolePreviewStroke:SetAttribute("ThemeColorRole_Color", "Bd2") end)
        text(rolePreview, UDim2.new(0, 10, 0, 5), UDim2.new(1, -20, 0, 18), "ELEMENT PREVIEW", "Tx4", 10, FB)
        local rolePreviewCanvas = Instance.new("Frame")
        rolePreviewCanvas.Name = "Canvas"
        rolePreviewCanvas.Parent = rolePreview
        rolePreviewCanvas.Position = UDim2.new(0, 10, 0, 27)
        rolePreviewCanvas.Size = UDim2.new(1, -20, 1, -37)
        rolePreviewCanvas.BackgroundTransparency = 1
        rolePreviewCanvas.ClipsDescendants = true
        rolePreviewCanvas.ZIndex = 4003

        local function previewStroke(target, role, thickness, transparency)
            local stroke = Stroke(target, colOf(role), thickness or 1, transparency or 0)
            pcall(function() stroke:SetAttribute("ThemeColorRole_Color", role) end)
            return stroke
        end
        local function renderRolePreview(role)
            for _, child in ipairs(rolePreviewCanvas:GetChildren()) do child:Destroy() end
            local function pbox(pos, size, colorRole, corner)
                return box(rolePreviewCanvas, pos, size, colorRole, 4004, corner or 7)
            end
            local function plabel(pos, size, value, colorRole, textSize, font)
                return text(rolePreviewCanvas, pos, size, value, colorRole, textSize or 11, font or FM)
            end
            if role == "BG" then
                local canvas = pbox(UDim2.fromOffset(0, 0), UDim2.fromScale(1, 1), "BG", 7)
                local sample = box(canvas, UDim2.new(0, 12, 0, 14), UDim2.new(1, -24, 1, -28), "Card", 4005, 7)
                previewStroke(sample, "Bd", 1, 0.25)
                text(sample, UDim2.new(0, 10, 0, 6), UDim2.new(1, -20, 0, 20), "Main window canvas", "Tx", 12, FB)
            elseif role == "Sidebar" then
                local rail = pbox(UDim2.new(0, 0, 0, 0), UDim2.new(0.42, 0, 1, 0), "Sidebar", 7)
                box(rail, UDim2.new(0, 8, 0, 14), UDim2.new(1, -16, 0, 26), "ActiveBg", 4005, 6)
                text(rail, UDim2.new(0, 16, 0, 14), UDim2.new(1, -24, 0, 26), "Visuals", "Tx", 11, FM)
                plabel(UDim2.new(0.48, 8, 0, 12), UDim2.new(0.52, -8, 0, 42), "Navigation surface", "Tx2", 12, FB)
            elseif role == "Card" then
                local cardPreview = pbox(UDim2.new(0, 0, 0, 4), UDim2.new(1, 0, 1, -8), "Card", 8)
                previewStroke(cardPreview, "Bd", 1, 0.2)
                text(cardPreview, UDim2.new(0, 12, 0, 8), UDim2.new(1, -24, 0, 20), "Section card", "Tx", 12, FB)
                box(cardPreview, UDim2.new(0, 12, 0, 38), UDim2.new(1, -24, 0, 28), "Elev", 4005, 6)
            elseif role == "Elev" then
                local control = pbox(UDim2.new(0, 8, 0.5, -22), UDim2.new(1, -16, 0, 44), "Elev", 8)
                previewStroke(control, "Bd2", 1, 0.35)
                text(control, UDim2.new(0, 12, 0, 0), UDim2.new(1, -24, 1, 0), "Raised input / button", "Tx2", 12, FM)
            elseif role == "Hover" or role == "ActiveBg" then
                pbox(UDim2.new(0, 8, 0, 10), UDim2.new(1, -16, 0, 30), role, 7)
                plabel(UDim2.new(0, 20, 0, 10), UDim2.new(1, -40, 0, 30), role == "Hover" and "Hovered row" or "Selected row", "Tx", 12, FB)
                pbox(UDim2.new(0, 8, 0, 50), UDim2.new(1, -16, 0, 26), "Elev", 7)
                plabel(UDim2.new(0, 20, 0, 50), UDim2.new(1, -40, 0, 26), "Resting row", "Tx3", 11, FM)
            elseif role == "Accent" or role == "AccentSoft" then
                local accentButton = pbox(UDim2.new(0, 8, 0, 12), UDim2.new(0.56, -12, 0, 34), role, 8)
                text(accentButton, UDim2.new(0, 10, 0, 0), UDim2.new(1, -20, 1, 0), role, role == "Accent" and "BG" or "Tx", 12, FB)
                local badge = pbox(UDim2.new(0.62, 0, 0, 16), UDim2.new(0.38, -8, 0, 26), role, 13)
                text(badge, UDim2.new(0, 8, 0, 0), UDim2.new(1, -16, 1, 0), "BADGE", role == "Accent" and "BG" or "Tx", 10, FB)
            elseif role == "TgOn" or role == "TgOff" or role == "KnobOn" or role == "KnobOff" then
                local enabled = role == "TgOn" or role == "KnobOn"
                local trackRole = enabled and "TgOn" or "TgOff"
                local knobRole = enabled and "KnobOn" or "KnobOff"
                if role == "TgOn" or role == "TgOff" then trackRole = role else knobRole = role end
                plabel(UDim2.new(0, 8, 0, 8), UDim2.new(0.6, 0, 0, 24), enabled and "Enabled state" or "Disabled state", "Tx2", 12, FB)
                local track = pbox(UDim2.new(1, -66, 0, 8), UDim2.fromOffset(58, 28), trackRole, 14)
                box(track, enabled and UDim2.new(1, -25, 0.5, -10) or UDim2.new(0, 5, 0.5, -10), UDim2.fromOffset(20, 20), knobRole, 4005, 10)
                local second = pbox(UDim2.new(1, -66, 0, 50), UDim2.fromOffset(58, 28), enabled and "TgOff" or "TgOn", 14)
                box(second, enabled and UDim2.new(0, 5, 0.5, -10) or UDim2.new(1, -25, 0.5, -10), UDim2.fromOffset(20, 20), enabled and "KnobOff" or "KnobOn", 4005, 10)
            elseif role == "Tx" or role == "Tx2" or role == "Tx3" or role == "Tx4" then
                local roles = { "Tx", "Tx2", "Tx3", "Tx4" }
                for index, textRole in ipairs(roles) do
                    plabel(UDim2.new(0, 8, 0, (index - 1) * 24), UDim2.new(1, -16, 0, 22),
                        (textRole == role and "> " or "  ") .. textRole .. " text hierarchy", textRole, textRole == role and 13 or 11,
                        textRole == role and FB or FM)
                end
            elseif role == "Bd" or role == "Bd2" then
                local outer = pbox(UDim2.new(0, 8, 0, 8), UDim2.new(1, -16, 1, -16), "Card", 9)
                previewStroke(outer, role, 2, 0)
                local inner = box(outer, UDim2.new(0, 12, 0, 32), UDim2.new(1, -24, 1, -44), "Elev", 4005, 7)
                previewStroke(inner, role == "Bd" and "Bd2" or "Bd", 1, 0.25)
                text(outer, UDim2.new(0, 12, 0, 6), UDim2.new(1, -24, 0, 20), role .. " border", "Tx2", 12, FB)
            elseif role == "Glow" then
                for index = 1, 3 do
                    local glow = pbox(UDim2.new(0, 12 - index * 2, 0, 14 - index * 2), UDim2.new(1, -24 + index * 4, 1, -28 + index * 4), "Card", 9)
                    glow.BackgroundTransparency = index < 3 and 1 or 0
                    previewStroke(glow, "Glow", index, 0.55 + index * 0.1)
                end
                plabel(UDim2.new(0, 20, 0.5, -12), UDim2.new(1, -40, 0, 24), "Window glow", "Tx", 12, FB)
            else
                local sample = pbox(UDim2.new(0, 8, 0, 8), UDim2.new(1, -16, 1, -16), role, 8)
                text(sample, UDim2.new(0, 12, 0, 0), UDim2.new(1, -24, 1, 0), role, "Tx", 12, FB)
            end
        end

        local function rebuildRoles()
            for _, c in ipairs(roleList:GetChildren()) do
                if not c:IsA("UIListLayout") then c:Destroy() end
            end
            table.clear(swatchRows)
            for i, role in ipairs(activeTab.roles) do
                local b = Instance.new("TextButton")
                b.Parent = roleList
                b.LayoutOrder = i
                b.Size = UDim2.new(1, -4, 0, 28)
                b.BackgroundColor3 = T.Elev
                pcall(function() b:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
                b.BorderSizePixel = 0
                b.AutoButtonColor = false
                b.Font = FM
                b.TextSize = 12
                b.Text = ""
                b.ZIndex = 4003
                Corner(b, 7)

                local selectionBorder = Instance.new("Frame")
                selectionBorder.Name = "SelectionBorder"
                selectionBorder.Parent = b
                selectionBorder.Position = UDim2.fromOffset(2, 2)
                selectionBorder.Size = UDim2.new(1, -4, 1, -4)
                selectionBorder.BackgroundTransparency = 1
                selectionBorder.BorderSizePixel = 0
                selectionBorder.ZIndex = 4005
                Corner(selectionBorder, 5)
                local st = Stroke(selectionBorder, T.Accent, 1.25, 1)
                pcall(function() st:SetAttribute("ThemeColorRole_Color", "Accent") end)

                local chip = Instance.new("Frame")
                chip.Parent = b
                chip.Position = UDim2.new(0, 6, 0.5, -9)
                chip.Size = UDim2.fromOffset(18, 18)
                chip.BorderSizePixel = 0
                chip.BackgroundColor3 = colOf(role)
                chip.ZIndex = 4004
                Corner(chip, 5)

                Stroke(chip, T.Bd2, 1, 0.35)

                local nm = Instance.new("TextLabel")
                nm.Parent = b
                nm.BackgroundTransparency = 1
                nm.Position = UDim2.new(0, 32, 0, 0)
                nm.Size = UDim2.new(1, -96, 1, 0)
                nm.Font = FM
                nm.TextSize = 12
                nm.TextXAlignment = Enum.TextXAlignment.Left
                nm.Text = role
                nm.TextColor3 = T.Tx2
                nm.ZIndex = 4004
                pcall(function() nm:SetAttribute("ThemeColorRole_TextColor3", "Tx2") end)

                local hex = Instance.new("TextLabel")
                hex.Parent = b
                hex.BackgroundTransparency = 1
                hex.AnchorPoint = Vector2.new(1, 0)
                hex.Position = UDim2.new(1, -8, 0, 0)
                hex.Size = UDim2.new(0, 58, 1, 0)
                hex.Font = FM
                hex.TextSize = 11
                hex.TextXAlignment = Enum.TextXAlignment.Right
                hex.TextColor3 = T.Tx4
                hex.ZIndex = 4004
                pcall(function() hex:SetAttribute("ThemeColorRole_TextColor3", "Tx4") end)

                swatchRows[#swatchRows + 1] = { role = role, chip = chip, stroke = st, btn = b, hex = hex, name = nm }
                b.MouseButton1Click:Connect(function()
                    SFX.Click()
                    selected = role
                    loadRole()
                end)
            end
            refreshSwatches()
        end

        refreshSwatches = function()
            for _, r in ipairs(swatchRows) do
                local c = colOf(r.role)
                r.chip.BackgroundColor3 = c
                r.hex.Text = string.format("%02X%02X%02X",
                    math.round(c.R * 255), math.round(c.G * 255), math.round(c.B * 255))
                local on = r.role == selected
                r.stroke.Transparency = on and 0 or 1

                r.btn.BackgroundColor3 = on and T.ActiveBg or T.Elev
                pcall(function() r.btn:SetAttribute("ThemeColorRole_BackgroundColor3", on and "ActiveBg" or "Elev") end)
                r.name.TextColor3 = on and T.Tx or T.Tx2
                pcall(function() r.name:SetAttribute("ThemeColorRole_TextColor3", on and "Tx" or "Tx2") end)
            end
            if swatchTxt then swatchTxt.Text = selected or "Accent" end
            if swatchBig then
                swatchBig.BackgroundColor3 = colOf(selected or "Accent")
                pcall(function() swatchBig:SetAttribute("ThemeColorRole_BackgroundColor3", selected or "Accent") end)
            end
        end

        loadRole = function()
            local c = colOf(selected)
            S._ThemeR, S._ThemeG = math.round(c.R * 255), math.round(c.G * 255)
            S._ThemeB = math.round(c.B * 255)
            rSet.set(S._ThemeR); gSet.set(S._ThemeG); bSet.set(S._ThemeB)
            if hexBox then
                hexBox.Text = string.format("#%02X%02X%02X", S._ThemeR, S._ThemeG, S._ThemeB)
            end
            if roleHint then roleHint.Text = ROLE_HINTS[selected] or "Live color role" end
            refreshSwatches()
            renderRolePreview(selected)
        end

        local function pickTab(tab)
            activeTab = tab
            for _, tb in ipairs(tabBtns) do
                local on = tb.tab == tab
                tb.btn.BackgroundColor3 = on and T.ActiveBg or T.Elev
                pcall(function() tb.btn:SetAttribute("ThemeColorRole_BackgroundColor3", on and "ActiveBg" or "Elev") end)
                tb.btn.TextColor3 = on and T.Tx or T.Tx3
                pcall(function() tb.btn:SetAttribute("ThemeColorRole_TextColor3", on and "Tx" or "Tx3") end)
            end
            selected = tab.roles[1]
            rebuildRoles()
            loadRole()
        end

        for i, tab in ipairs(TABS) do
            local b = Instance.new("TextButton")
            b.Parent = tabCol
            b.LayoutOrder = i
            b.Size = UDim2.new(1, 0, 0, 30)
            b.BackgroundColor3 = T.Elev
            b.BorderSizePixel = 0
            b.AutoButtonColor = false
            b.Font = FM
            b.TextSize = 12
            b.Text = tab.name
            b.TextColor3 = T.Tx3
            b.ZIndex = 4002
            Corner(b, 6)
            tabBtns[#tabBtns + 1] = { btn = b, tab = tab }
            b.MouseButton1Click:Connect(function() SFX.Click(); pickTab(tab) end)
        end
        pickTab(TABS[1])
    end

    S._OpenThemeEditor = function()
        if not win then
            local ok, err = pcall(build)
            if not ok then
                warn("[Inertia] theme window: " .. tostring(err))
                return
            end
        end
        win.Visible = not win.Visible
        if win.Visible then
            if S._SettingsModal and S._SettingsModal.Visible then
                S._SettingsWasVisible = true
                S._SettingsModal.Visible = false
            else
                S._SettingsWasVisible = false
            end
            loadRole()
        else
            if S._SettingsWasVisible then
                pcall(function() S._SettingsModal.Visible = true end)
            end
            S._SettingsWasVisible = nil
        end
    end
end

mkModalLabel("UI Wallpaper", 11)
local wallBtn = Instance.new("TextButton")
wallBtn.Parent = mScroll; wallBtn.LayoutOrder = 12; wallBtn.Size = UDim2.new(1, 0, 0, 28)
wallBtn.BackgroundColor3 = T.Elev; pcall(function() wallBtn:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
wallBtn.BorderSizePixel = 0; wallBtn.Font = F; wallBtn.TextSize = 13
wallBtn.TextColor3 = T.White; pcall(function() wallBtn:SetAttribute("ThemeColorRole_TextColor3", "White") end)
wallBtn.Text = S.UIWallpaper or "None"; wallBtn.ZIndex = 1001; Corner(wallBtn, 6); Stroke(wallBtn, T.Bd, 1, 0.4)

local wallOptions = {"None"}
local urls = {}
local wallRequest = 0
local opSlider
local function applyWall()
    local v = S.UIWallpaper or "None"
    local url = urls[v] or ""
    local main = SG:FindFirstChild("Main", true)
    local settingsPanel = SG:FindFirstChild("InertiaSettings", true)

    local transparency = math.clamp(tonumber(S.UIWallpaperOpacity) or 0.2, 0, 1)
    local hidden = v == "None" or url == ""
    if main then main.Image = url; main.ImageTransparency = hidden and 1 or transparency end
    if settingsPanel then settingsPanel.Image = url; settingsPanel.ImageTransparency = hidden and 1 or transparency end
end

S._BuildWallpaperPicker = function(items, fetch)
    local byName = {}
    for _, bg in ipairs(items) do
        byName[bg.Name] = bg
        table.insert(wallOptions, bg.Name)
    end

    local previews = {}
    for i = 2, #wallOptions do
        local bg = items[i - 1]
        previews[i] = function() return fetch(bg.Path, "backgrounds") end
    end

    tc(wallBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        local idx = 1
        for i, v in ipairs(wallOptions) do
            if v == (S.UIWallpaper or "None") then idx = i; break end
        end
        S._OpenOptionPicker("UI Wallpaper", wallOptions, idx, function(pick)
            wallRequest = wallRequest + 1
            local requestId = wallRequest
            local name = wallOptions[pick]
            wallBtn.Text = name
            if name == "None" then
                S.UIWallpaper = "None"
                applyWall()
                pcall(function() if S._RequestAutoSave then S._RequestAutoSave() end end)
            else
                local bg = items[pick - 1]
                tt(function()
                    if not urls[name] and bg then
                        local id = fetch(bg.Path, "backgrounds")
                        if S.Destroyed or requestId ~= wallRequest then return end
                        if id == "" then
                            Notify("Wallpaper", "Could not download " .. name, 3)
                            wallBtn.Text = S.UIWallpaper or "None"
                            applyWall()
                            return
                        end
                        urls[name] = id
                    end
                    if S.Destroyed or requestId ~= wallRequest then return end
                    S.UIWallpaper = name
                    applyWall()
                    pcall(function() if S._RequestAutoSave then S._RequestAutoSave() end end)
                end)
            end
        end, { previews = previews })
    end))

    S._RefreshWallpaper = function()
        wallRequest = wallRequest + 1
        local requestId = wallRequest
        local name = tostring(S.UIWallpaper or "None")
        local bg = byName[name]
        if opSlider and opSlider.Parent and not opSlider:IsFocused() then
            opSlider.Text = tostring(math.floor(math.clamp(tonumber(S.UIWallpaperOpacity) or 0.2, 0, 1) * 100))
        end

        if name == "None" then
            wallBtn.Text = "None"
            applyWall()
            return
        end
        if not bg then
            S.UIWallpaper = "None"
            wallBtn.Text = "None"
            applyWall()
            return
        end

        wallBtn.Text = name
        tt(function()
            if not urls[name] then
                local id = fetch(bg.Path, "backgrounds")
                if S.Destroyed or requestId ~= wallRequest then return end
                if id == "" then
                    S.UIWallpaper = "None"
                    wallBtn.Text = "None"
                    applyWall()
                    return
                end
                urls[name] = id
            end
            if S.Destroyed or requestId ~= wallRequest then return end
            applyWall()
        end)
    end
end

