    for i, entry in ipairs(S.NotifySounds) do names[i] = entry.name end
    S._RefreshNotifySoundSetting = function()
        S.NotifySoundIndex = math.clamp(math.floor(tonumber(S.NotifySoundIndex) or 1), 1, #names)
        if notifyBtn.Parent then notifyBtn.Text = names[S.NotifySoundIndex] end
    end
    S._RefreshNotifySoundSetting()
    tc(notifyBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        S._OpenOptionPicker("Notification Sound", names, S.NotifySoundIndex or 1, function(pick)
            S.NotifySoundIndex = math.clamp(math.floor(tonumber(pick) or 1), 1, #names)
            S._RefreshNotifySoundSetting()

            SFX.Pop()
            pcall(function() if S._RequestAutoSave then S._RequestAutoSave() end end)
        end, { keepOpen = true })
    end))
end
