mScroll.Active = true

do
    local dr, di, ds, sp, so
    mHdr.Active = true
    tc(mHdr.InputBegan:Connect(function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            if di then return end
            dr = true
            di = i
            ds = i.Position
            sp = SettingsModal.Position
            so = SettingsModal.AbsolutePosition
        end
    end))
    tc(UIS.InputChanged:Connect(function(i)
        local mouseDrag = di and di.UserInputType == Enum.UserInputType.MouseButton1 and i.UserInputType == Enum.UserInputType.MouseMovement
        if dr and (i == di or mouseDrag) then
            local d = i.Position - ds
            local camera = workspace.CurrentCamera
            local host = so and camera and camera.ViewportSize
            if host and host.X > 0 and host.Y > 0 then
                local size = SettingsModal.AbsoluteSize
                local function fit(v, extent, span)
                    if span >= extent then return (extent - span) / 2 end
                    return math.clamp(v, 0, extent - span)
                end
                local x = fit(so.X + d.X, host.X, size.X)
                local y = fit(so.Y + d.Y, host.Y, size.Y)
                SettingsModal.Position = UDim2.new(
                    sp.X.Scale,
                    sp.X.Offset + x - so.X,
                    sp.Y.Scale,
                    sp.Y.Offset + y - so.Y
                )
            else
                SettingsModal.Position = UDim2.new(sp.X.Scale, sp.X.Offset + d.X, sp.Y.Scale, sp.Y.Offset + d.Y)
            end
        end
    end))
    tc(UIS.InputEnded:Connect(function(i)
        if i == di and (i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch) then
            dr = false
            di = nil
        end
    end))
end

