    local function selectCursor(pick, persist, reportFailure)
        pick = math.clamp(math.floor(tonumber(pick) or 1), 1, math.max(#cursorEntries, 1))
        S._CursorAssetRequest = (S._CursorAssetRequest or 0) + 1
        local requestId = S._CursorAssetRequest
        local entry = cursorEntries[pick]
        S.CrosshairStyle = "Custom"
        S.CrosshairIndex = pick
        S.CrosshairAssetId = ""
        S.CrosshairPreset = entry and entry.Style or nil
        if S._RefreshCustomCursor then pcall(S._RefreshCustomCursor) end

        if entry and entry.Kind == "Asset" then
            tt(function()
                local fetchedId = fetchCustomAsset(entry.Path, "cursors")
                if S.Destroyed or requestId ~= S._CursorAssetRequest then return end
                if fetchedId ~= "" then
                    S.CrosshairAssetId = fetchedId
                else
                    S.CrosshairAssetId = CustomCrosshairs[1] or ""
                    if reportFailure then
                        Notify("Cursor", "Could not download " .. cursorNames[pick] .. "; using fallback", 3)
                    end
                end
                if S._RefreshCustomCursor then pcall(S._RefreshCustomCursor) end
                if persist and S._RequestAutoSave then pcall(S._RequestAutoSave) end
            end)
        elseif persist and S._RequestAutoSave then
            pcall(S._RequestAutoSave)
        end
    end
    S._ReloadSelectedCursor = function()
        selectCursor(S.CrosshairIndex or 1, false, false)
    end
