        skyNames[skyLibBase + i] = entry.Name
        skyPreviews[skyLibBase + i] = "rbxassetid://" .. tostring(entry.Preview or entry.Ft)
    end
    S._ClearCustomSkybox = function()
        local lighting = game:GetService("Lighting")
        for _, name in ipairs({ "CustomSkyboxUI", "CustomSkyboxAtmo" }) do
            local instance = lighting:FindFirstChild(name)
            if instance then pcall(function() instance:Destroy() end) end
        end
    end
    cleanup(function()
        S._CursorAssetRequest = (S._CursorAssetRequest or 0) + 1
        S._SkyboxRequest = (S._SkyboxRequest or 0) + 1
        if S._ClearCustomSkybox then S._ClearCustomSkybox() end
        S._ReloadSelectedCursor = nil
        S._ApplySelectedSkybox = nil
        S._ClearCustomSkybox = nil
    end)
    local function applySkyboxPick(pick, persist, report)
        pick = math.clamp(math.floor(tonumber(pick) or 1), 1, #skyNames)
        S._SkyboxRequest = (S._SkyboxRequest or 0) + 1
        local requestId = S._SkyboxRequest
        local lighting = game:GetService("Lighting")
        local function commit(index)
            S.SkyboxPickerIndex = pick
            S.SkyboxIndex = index
            if persist and S._RequestAutoSave then pcall(S._RequestAutoSave) end
        end
        local function getSky()
            local sky = lighting:FindFirstChild("CustomSkyboxUI")
            if not sky then
                sky = Instance.new("Sky")
                sky.Name = "CustomSkyboxUI"
                sky.Parent = lighting
            end
            return sky
        end
        local function clearAtmosphere()
            local oldAtmo = lighting:FindFirstChild("CustomSkyboxAtmo")
            if oldAtmo then oldAtmo:Destroy() end
        end

        if pick <= 1 then
            S._ClearCustomSkybox()
            commit(0)
            return
        end
        if pick == 2 then
            clearAtmosphere()
            local sky = getSky()
            sky.CelestialBodiesShown = true
            for face, suffix in pairs({ SkyboxBk = "bk", SkyboxDn = "dn", SkyboxFt = "ft",
                                        SkyboxLf = "lf", SkyboxRt = "rt", SkyboxUp = "up" }) do
                sky[face] = "rbxasset://textures/sky/sky512_" .. suffix .. ".tex"
            end
            commit(1)
            return
        end

        local libEntry = SKY_LIB[pick - skyLibBase]
        if libEntry then
            clearAtmosphere()
            local sky = getSky()
            sky.CelestialBodiesShown = false
            sky.SkyboxBk = "rbxassetid://" .. libEntry.Bk
            sky.SkyboxDn = "rbxassetid://" .. libEntry.Dn
            sky.SkyboxFt = "rbxassetid://" .. libEntry.Ft
            sky.SkyboxLf = "rbxassetid://" .. libEntry.Lf
            sky.SkyboxRt = "rbxassetid://" .. libEntry.Rt
            sky.SkyboxUp = "rbxassetid://" .. libEntry.Up
            commit(pick - 1)
            if report then Notify("Skybox", libEntry.Name .. " applied", 2) end
            return
        end

        local selectedSky = skyPaths[pick - 2]
        if not selectedSky or not selectedSky.Files then return end
        tt(function()
            local folder = selectedSky.Set == "Troll" and "skyboxes_troll" or "skyboxes"
            local bk = fetchCustomAsset(selectedSky.Files.Bk, folder)
            local dn = fetchCustomAsset(selectedSky.Files.Dn, folder)
            local ft = fetchCustomAsset(selectedSky.Files.Ft, folder)
            local lf = fetchCustomAsset(selectedSky.Files.Lf, folder)
            local rt = fetchCustomAsset(selectedSky.Files.Rt, folder)
            local up = fetchCustomAsset(selectedSky.Files.Up, folder)
            if S.Destroyed or requestId ~= S._SkyboxRequest then return end
            if bk == "" or dn == "" or ft == "" or lf == "" or rt == "" or up == "" then
                if report then Notify("Skybox", "Some sky faces failed to load", 3) end
                return
            end

            local skyboxObj = getSky()
            local atmo = lighting:FindFirstChild("CustomSkyboxAtmo")
            if not atmo then
                atmo = Instance.new("Atmosphere")
                atmo.Name = "CustomSkyboxAtmo"
                atmo.Density = 0.2
                atmo.Offset = 0.25
                atmo.Color = Color3.fromRGB(199, 199, 199)
                atmo.Decay = Color3.fromRGB(106, 112, 125)
                atmo.Glare = 0
                atmo.Haze = 0
                atmo.Parent = lighting
            end
            skyboxObj.CelestialBodiesShown = false
            skyboxObj.SkyboxBk = bk
            skyboxObj.SkyboxDn = dn
            skyboxObj.SkyboxFt = ft
            skyboxObj.SkyboxLf = lf
            skyboxObj.SkyboxRt = rt
            skyboxObj.SkyboxUp = up
            commit(pick - 2)
            if report then Notify("Skybox", selectedSky.Name .. " applied", 2) end
        end)
    end
    S._ApplySelectedSkybox = function()
        applySkyboxPick(S.SkyboxPickerIndex or ((S.SkyboxIndex or 0) + 1), false, false)
    end
    mkAction(secCustoms, "Choose Skybox", function()
        local currentSky = math.clamp(tonumber(S.SkyboxPickerIndex) or ((S.SkyboxIndex or 0) + 1), 1, #skyNames)
        S._OpenOptionPicker("Skybox (Normal + Troll)", skyNames, currentSky, function(pick)
            applySkyboxPick(pick, true, true)
        end, { previews = skyPreviews })
    end, 3)

    local GUN_LIB = {
        { "Gun Shot Classic", 213603013 },
        { "Gun Shot Clean", 2811598570 },
        { "9mm Gunshot", 4070504199 },
        { "Pistol Fire", 6569844325 },
        { "Gunshot SFX", 6656835390 },
