    local gunSoundOptions = {"Game Default", "Use Equipped Skin Sound"}
    for _, entry in ipairs(GUN_LIB) do
        table.insert(gunSoundOptions, entry[1])
    end
    for i = 1, #gunPaths do
        table.insert(gunSoundOptions, "Custom " .. i)
    end
    local function libSoundId(name)
        for _, entry in ipairs(GUN_LIB) do
            if entry[1] == name then return "rbxassetid://" .. entry[2] end
        end
        return nil
    end

    local function getEquippedSkinGunSound()
        local character = LP.Character
        if not character then return nil end

        local fallback = nil
        for _, descendant in ipairs(character:GetDescendants()) do
            if descendant:IsA("Sound") and descendant.SoundId ~= "" then
                local tool = descendant:FindFirstAncestorWhichIsA("Tool")
                if tool and tool.Name:lower():find("gun", 1, true) then
                    local candidateId = S._GetOriginalGunSoundId and S._GetOriginalGunSoundId(descendant)
                        or descendant.SoundId
                    local n = descendant.Name:lower()
                    if n:find("fire", 1, true) or n:find("shoot", 1, true) or n:find("shot", 1, true)
                        or n:find("bang", 1, true) or n:find("blast", 1, true) then
                        return candidateId
                    end
                    fallback = fallback or candidateId
                end
            end
        end
        return fallback
    end

    local gunSoundRequest = 0
    local function auditionSoundId(id)
        if not id or id == "" then return end
        local s = Instance.new("Sound")
        s.SoundId = id
        s.Volume = 1.5
        s.Parent = SoundService
        S._PlaySoundSafe(s)
        game:GetService("Debris"):AddItem(s, 5)
    end
    local function auditionGunSound(index)
        local path = gunPaths[index]
        if not path then return end
        local id = fetchCustomAsset(path, "gun_sounds_v2")
        if id == "" then
            Notify("Gun Sound", "Could not download Custom " .. index, 3)
            return
        end
        local s = Instance.new("Sound")
        s.SoundId = id
        s.Volume = 1.5
        s.Parent = SoundService
        S._PlaySoundSafe(s)
        game:GetService("Debris"):AddItem(s, 5)
    end
    local function saveGunChoice()
        if S._RequestAutoSave then pcall(S._RequestAutoSave) end
    end
    S._ReloadSelectedGunSound = function()
        gunSoundRequest = gunSoundRequest + 1
        local requestId = gunSoundRequest
        local choice = tostring(S.GunSoundChoice or "Game Default")
        if not table.find(gunSoundOptions, choice) then choice = "Game Default" end
        S.GunSoundChoice = choice

        if choice == "Game Default" then
            S.CustomGunSoundId = ""
        elseif choice == "Use Equipped Skin Sound" then
            S.CustomGunSoundId = getEquippedSkinGunSound() or ""
        else
            local libraryId = libSoundId(choice)
            if libraryId then
                S.CustomGunSoundId = libraryId
            else
                local customIndex = tonumber(choice:match("^Custom (%d+)$"))
                local path = customIndex and gunPaths[customIndex]
                if not path then
                    S.GunSoundChoice, S.CustomGunSoundId = "Game Default", ""
                else
                    S.CustomGunSoundId = ""
                    tt(function()
                        local fetchedId = fetchCustomAsset(path, "gun_sounds_v2")
                        if S.Destroyed or requestId ~= gunSoundRequest then return end
                        if fetchedId == "" then
                            S.GunSoundChoice, S.CustomGunSoundId = "Game Default", ""
                        else
                            S.CustomGunSoundId = fetchedId
                        end
                        if S._RefreshGunSounds then pcall(S._RefreshGunSounds) end
                    end)
                end
            end
        end
        if S._RefreshGunSounds then pcall(S._RefreshGunSounds) end
    end
    cleanup(function()
        gunSoundRequest = gunSoundRequest + 1
        S._ReloadSelectedGunSound = nil
    end)

    mkAction(secCustoms, "Choose Gun Sound", function()
        local current = 1
        for i, name in ipairs(gunSoundOptions) do
            if name == (S.GunSoundChoice or "Game Default") then current = i; break end
        end
        S._OpenOptionPicker("Gun Sound", gunSoundOptions, current, function(pick)
            gunSoundRequest = gunSoundRequest + 1
            local requestId = gunSoundRequest
            local v = gunSoundOptions[pick]
            local previousChoice = S.GunSoundChoice or "Game Default"
            local previousId = S.CustomGunSoundId
            S.GunSoundChoice = v

            if v == "Game Default" then
                S.CustomGunSoundId = ""
                if S._RefreshGunSounds then pcall(S._RefreshGunSounds) end
                saveGunChoice()
                return
            end
            if v == "Use Equipped Skin Sound" then
                local soundId = getEquippedSkinGunSound()
                if soundId then
                    S.CustomGunSoundId = soundId
                    if S._RefreshGunSounds then pcall(S._RefreshGunSounds) end
                    saveGunChoice()
                else
                    S.GunSoundChoice, S.CustomGunSoundId = previousChoice, previousId
                    Notify("Gun Sound", "Equip a gun skin first, then choose this option again.", 3)
                end
                return
            end

            local libId = libSoundId(v)
            if libId then
                S.CustomGunSoundId = libId
                if S._RefreshGunSounds then pcall(S._RefreshGunSounds) end
                Notify("Gun Sound", v .. " selected", 2)
                saveGunChoice()
                return
            end
            local index = tonumber(v:match("^Custom (%d+)$"))
            local path = index and gunPaths[index]
            if not path then
                S.GunSoundChoice, S.CustomGunSoundId = previousChoice, previousId
                return
            end
            tt(function()
                local fetchedId = fetchCustomAsset(path, "gun_sounds_v2")
                if S.Destroyed or requestId ~= gunSoundRequest then return end
                if fetchedId ~= "" then
                    S.CustomGunSoundId = fetchedId
                    if S._RefreshGunSounds then pcall(S._RefreshGunSounds) end
                    Notify("Gun Sound", v .. " selected", 2)
                    saveGunChoice()
                else
                    S.GunSoundChoice, S.CustomGunSoundId = previousChoice, previousId
                    Notify("Gun Sound", "Could not load " .. v .. "; previous sound restored.", 3)
                end
            end)
        end, {
            keepOpen = true,
            action = { label = "PLAY", fn = function(pick)
                local name = tostring(gunSoundOptions[pick])
                local libId = libSoundId(name)
                if libId then auditionSoundId(libId); return end
                local index = tonumber(name:match("^Custom (%d+)$"))
                if index then auditionGunSound(index) end
            end },
        })
    end, 4)
    end

