        if not ok then
            Notify("Knife Effect", "Local effect rebuild failed", 3)
        elseif not applied and (tonumber(S._KnifeEffectTargetCount) or 0) > 0 then
            Notify("Knife Effect", "No renderable effect source was found", 3)
