    do
        local function localPlayerHasKnife()
            for _, container in ipairs({ LP.Character, LP:FindFirstChildOfClass("Backpack") }) do
                if container then
                    for _, child in ipairs(container:GetChildren()) do
                        if child:IsA("Tool") and child.Name:lower():find("knife", 1, true) then return true end
                    end
                end
            end
            return false
        end
        local function watch(p)
            if p == LP then return end
            local function hook(char)
                local hum = char:WaitForChild("Humanoid", 5)
                if not hum then return end
                tc(hum.Died:Connect(function()
                    if getRole(LP) ~= "Murderer" and not localPlayerHasKnife() then return end
                    local myChar = LP.Character
                    local myHrp = myChar and myChar:FindFirstChild("HumanoidRootPart")
                    local theirHrp = char:FindFirstChild("HumanoidRootPart")
                    if myHrp and theirHrp
                        and (myHrp.Position - theirHrp.Position).Magnitude <= 60 then
                        playKillSound(S.KillSoundMurderer)
                    end
                end))
            end
            if p.Character then hook(p.Character) end
            tc(p.CharacterAdded:Connect(hook))
        end
        for _, p in ipairs(Players:GetPlayers()) do watch(p) end
        tc(Players.PlayerAdded:Connect(watch))
    end

