        local VFX_DATA = game:GetService("HttpService"):JSONDecode(VFX_TEMPLATE_JSON)
        local STYLE_NAMES = { "Angel Aura", "Dracula", "Frozen Bloom", "Magic Aura" }
        local BODY_MAP = {
