        }
        local ENUM_MAP = {
            EmissionDirection = Enum.NormalId,
            Orientation = Enum.ParticleOrientation,
            Shape = Enum.ParticleEmitterShape,
            ShapeInOut = Enum.ParticleEmitterShapeInOut,
            ShapeStyle = Enum.ParticleEmitterShapeStyle,
            FlipbookLayout = Enum.ParticleFlipbookLayout,
            FlipbookMode = Enum.ParticleFlipbookMode,
            TextureMode = Enum.TextureMode,
        }
        local fx = { objects = {}, serial = 0, floorConn = nil }

        local function styleOf(name)
            name = tostring(name or "")
            if VFX_DATA.styles[name] then return name end
            if name:find("Demon") or name:find("Fire") or name:find("Red") or name:find("Bat") then return "Dracula" end
            if name:find("Ice") or name:find("Frozen") or name:find("Blue") then return "Frozen Bloom" end
            if name:find("Shadow") or name:find("Void") or name:find("Magic") or name:find("Purple") then return "Magic Aura" end
            return "Angel Aura"
        end

        local function clean()
            fx.serial = fx.serial + 1
            if fx.floorConn then pcall(function() fx.floorConn:Disconnect() end); fx.floorConn = nil end
            for _, object in ipairs(fx.objects) do
                if object then
                    pcall(function()
                        if object:IsA("ParticleEmitter") then object.Enabled = false; object:Clear() end
                        object:Destroy()
                    end)
                end
            end
            table.clear(fx.objects)
            local character = LP.Character
            if character then
                for _, object in ipairs(character:GetDescendants()) do
                    if object:GetAttribute("InertiaExactVFX") == true then pcall(function() object:Destroy() end) end
                end
            end
        end

        local function keep(object)
            object:SetAttribute("InertiaExactVFX", true)
            fx.objects[#fx.objects + 1] = object
            return object
        end

        local function resolveBody(character, sourceName)
            for _, candidate in ipairs(BODY_MAP[sourceName] or { sourceName, "HumanoidRootPart" }) do
                local part = character:FindFirstChild(candidate)
                if part and part:IsA("BasePart") then return part end
            end
            return nil
        end

        local function numberSequence(points, multiplier)
            local keypoints = table.create(#points)
            for index, point in ipairs(points) do
                keypoints[index] = NumberSequenceKeypoint.new(point[1], math.max(0, point[2] * multiplier), math.max(0, (point[3] or 0) * multiplier))
            end
            return NumberSequence.new(keypoints)
        end

        local function colorSequence(points)
            local keypoints = table.create(#points)
            for index, point in ipairs(points) do
                keypoints[index] = ColorSequenceKeypoint.new(point[1], Color3.new(point[2], point[3], point[4]))
            end
            return ColorSequence.new(keypoints)
        end

        local function decodeProperty(property, encoded, scale)
            if type(encoded) ~= "table" or encoded.t == nil then return encoded end
            local kind, value = encoded.t, encoded.v
            if kind == "cf" then
                return CFrame.new(value[1] * scale, value[2] * scale, value[3] * scale,
                    value[4], value[5], value[6], value[7], value[8], value[9], value[10], value[11], value[12])
            elseif kind == "ns" then
                local multiplier = (property == "Size") and scale or 1
                return numberSequence(value, multiplier)
            elseif kind == "cs" then
                return colorSequence(value)
            elseif kind == "range" then
                local multiplier = (property == "Speed") and scale or 1
                return NumberRange.new(value[1] * multiplier, value[2] * multiplier)
            elseif kind == "color" then
                return Color3.new(value[1], value[2], value[3])
            elseif kind == "v3" then
                local multiplier = (property == "Acceleration") and scale or 1
                return Vector3.new(value[1] * multiplier, value[2] * multiplier, value[3] * multiplier)
            elseif kind == "v2" then
                return Vector2.new(value[1], value[2])
            elseif kind == "enum" then
                local enumType = ENUM_MAP[property]
                return enumType and enumType[value] or nil
            elseif kind == "ref" then
                return nil, value
            end
            return nil
        end

        local function applyProperties(object, properties, scale, density, glow, lightsEnabled, pending)
            for property, encoded in pairs(properties or {}) do
                local value, reference = decodeProperty(property, encoded, scale)
                if reference then
                    pending[#pending + 1] = { object = object, property = property, reference = reference }
                elseif value ~= nil then
                    if property == "Rate" and object:IsA("ParticleEmitter") then
                        value = math.clamp(value * density, 0, MOBILE and 100 or 400)
                    elseif property == "Brightness" then
                        value = value * glow
                    elseif property == "LightEmission" then
                        value = math.clamp(value * glow, 0, 1)
                    elseif property == "Range" and object:IsA("Light") then
                        value = value * scale
                    elseif (property == "Width0" or property == "Width1" or property == "CurveSize0" or property == "CurveSize1") and object:IsA("Beam") then
                        value = value * scale
                    elseif property == "Enabled" and object:IsA("Light") then
                        value = value and lightsEnabled
                    end
                    pcall(function() object[property] = value end)
                end
            end
        end

        local function preload(style)
            local assets, seen = {}, {}
            for _, node in ipairs(style.nodes) do
                local texture = node.x and node.x.Texture
                if type(texture) == "string" and texture ~= "" and not seen[texture] then
                    seen[texture] = true
                    assets[#assets + 1] = texture
                end
            end
            if #assets > 0 then
                tt(function()
                    if not S.Destroyed then pcall(function() ContentProvider:PreloadAsync(assets) end) end
                end)
            end
        end

        local function rebuild()
            clean()
            if not S.VFXWings then return end
            local character = LP.Character
            if not character then return end
            local style = VFX_DATA.styles[styleOf(S.VFXWingStyle)]
            if not style then return end
            local scale = math.clamp(tonumber(S.VFXWingScale) or 100, 40, 180) / 100
            local density = math.clamp(tonumber(S.VFXTemplateDensity) or 100, 10, 150) / 100
            local glow = math.clamp(tonumber(S.VFXTemplateGlow) or 100, 0, 150) / 100
            local includeFloor = S.VFXFootAura ~= false
            local lightsEnabled = S.VFXTemplateLights ~= false
            local created, pending = {}, {}
            local serial = fx.serial
            local floorRig

            if includeFloor then
                local root = character:FindFirstChild("HumanoidRootPart")
                if root then
                    floorRig = Instance.new("Part")
                    floorRig.Name = "InertiaVFX_FloorRig"
                    floorRig.Size = Vector3.new(0.2, 0.2, 0.2)
                    floorRig.Transparency = 1
                    floorRig.Anchored = true
                    floorRig.CanCollide = false
                    floorRig.CanQuery = false
                    floorRig.CanTouch = false
                    floorRig.CastShadow = false
                    floorRig.Parent = workspace
                    keep(floorRig)

                    local floorParams = RaycastParams.new()
                    floorParams.FilterType = Enum.RaycastFilterType.Exclude
                    floorParams.FilterDescendantsInstances = { character, floorRig }
                    local function placeFloorRig()
                        if not (floorRig and floorRig.Parent and root and root.Parent) then return end
                        local hit = workspace:Raycast(root.Position + Vector3.new(0, 1, 0), Vector3.new(0, -16, 0), floorParams)
                        local position = hit and (hit.Position + hit.Normal * 0.035)
                            or (root.Position - Vector3.new(0, 3, 0))
                        floorRig.CFrame = CFrame.new(position)
                    end
                    placeFloorRig()
                    fx.floorConn = RunService.Heartbeat:Connect(placeFloorRig)
                end
            end

            for _, node in ipairs(style.nodes) do
                if serial ~= fx.serial then return end
                if includeFloor or node.z ~= "floor" then
                    local parent = node.p ~= 0 and created[node.p]
                        or (node.z == "floor" and floorRig)
                        or resolveBody(character, node.b)
                    if parent then
                        local ok, object = pcall(Instance.new, node.c)
                        if ok and object then
                            object.Name = "InertiaVFX_" .. tostring(node.n or node.c)
                            applyProperties(object, node.x, scale, density, glow, lightsEnabled, pending)
                            if node.z == "floor" and node.p == 0 and floorRig and object:IsA("Attachment") then
                                local source = object.CFrame
                                object.CFrame = CFrame.new(source.X, 0, source.Z) * source.Rotation
                            end
                            object.Parent = parent
                            created[node.id] = keep(object)
                        end
                    end
                end
            end
            for _, link in ipairs(pending) do
                local target = created[link.reference]
                if target and link.object and link.object.Parent then
                    pcall(function() link.object[link.property] = target end)
                end
            end
            preload(style)
        end
        S._RefreshVFXWings = rebuild
        cleanup(clean)

        tc(LP.CharacterAdded:Connect(function()
            tt(function()
                task.wait(0.8)
                if not S.Destroyed and S.VFXWings then rebuild() end
            end)
        end))

        local secWings = mkSection(Pages.Visuals, "Exact VFX", 12, true)
        table.insert(S._CustomsSections, secWings)
        mkToggle(secWings, "Enable VFX", false, function(value) S.VFXWings = value; rebuild() end, 1)
        mkCycle(secWings, "VFX Style", STYLE_NAMES, "Angel Aura", function(value) S.VFXWingStyle = value; rebuild() end, 2)
        mkToggle(secWings, "Floor Effect", true, function(value) S.VFXFootAura = value; rebuild() end, 3)
        mkToggle(secWings, "Local Lights", true, function(value) S.VFXTemplateLights = value; rebuild() end, 4)
        mkSlider(secWings, "Effect Scale", 40, 180, 100, function(value) S.VFXWingScale = value; rebuild() end, 5)
        mkSlider(secWings, "Particle Density", 10, 150, 100, function(value) S.VFXTemplateDensity = value; rebuild() end, 6)
        mkSlider(secWings, "VFX Brightness", 0, 150, 100, function(value) S.VFXTemplateGlow = value; rebuild() end, 7)

        S.VFXAura, S.AuraColor, S.AuraDensity, S.AuraSize = nil, nil, nil, nil
        S.VFXWingHeight, S.VFXWingBack, S.VFXWingLight, S.VFXDensity, S.VFXGlow = nil, nil, nil, nil, nil
    end
    do
        local cursorGui = Instance.new("ImageLabel")
        cursorGui.Name = "MM2_Crosshair"
        cursorGui.Parent = SG
        cursorGui.AnchorPoint = Vector2.new(0.5, 0.5)
        cursorGui.BackgroundTransparency = 1
        cursorGui.Visible = false
        cursorGui.ZIndex = 4000
        cursorGui.ScaleType = Enum.ScaleType.Fit

        local vectorCursorGui = Instance.new("Frame")
        vectorCursorGui.Name = "MM2_VectorCursor"
        vectorCursorGui.Parent = SG
        vectorCursorGui.AnchorPoint = Vector2.new(0.5, 0.5)
        vectorCursorGui.BackgroundTransparency = 1
        vectorCursorGui.Visible = false
        vectorCursorGui.ZIndex = 4000

        local lastVectorKey = ""
        local function buildVectorCursor(style, size)
            vectorCursorGui:ClearAllChildren()
            local scale = size / 32
            local center = size / 2
            local function px(value)
                return math.max(1, math.floor(value * scale + 0.5))
            end
            local color = Color3.fromRGB(120, 240, 255)
            if style == "DiamondGrid" or style == "SquareDot" then
                color = Color3.fromRGB(255, 210, 92)
            elseif style == "StarPoint" or style == "PulseHalo" then
                color = Color3.fromRGB(206, 140, 255)
            elseif style == "Chevron" then
                color = Color3.fromRGB(255, 130, 190)
            elseif style == "FourDots" or style == "OrbitDot" then
                color = Color3.fromRGB(150, 255, 175)
            end

            local function part(width, height, x, y, rotation, fill, cornerOverride, noOutline)
                local item = Instance.new("Frame")
                item.Parent = vectorCursorGui
                item.BorderSizePixel = 0
                item.BackgroundColor3 = fill or color
                item.BackgroundTransparency = 0
                item.AnchorPoint = Vector2.new(0.5, 0.5)
                item.Size = UDim2.fromOffset(px(width), px(height))
                item.Position = UDim2.fromOffset(center + px(x), center + px(y))
                item.Rotation = rotation or 0
                item.ZIndex = 4001
                local radius = cornerOverride
                if radius == nil then
                    radius = math.max(1, math.floor(px(math.min(width, height)) / 2))
                else
                    radius = radius > 0 and math.max(1, px(radius)) or 0
                end
                if radius > 0 then Corner(item, radius) end
                if not noOutline then
                    Stroke(item, Color3.fromRGB(0, 0, 0), math.max(1, px(1)), 0.3)
                end
                return item
            end
            local function line(width, height, x, y, rotation)
                return part(width, height, x, y, rotation, color)
            end
            local function dot(diameter, x, y)
                return part(diameter, diameter, x, y, 0, color)
            end
            local function ring(diameter, thickness, transparency)
                local item = Instance.new("Frame")
                item.Parent = vectorCursorGui
                item.AnchorPoint = Vector2.new(0.5, 0.5)
                item.Position = UDim2.fromScale(0.5, 0.5)
                item.Size = UDim2.fromOffset(px(diameter), px(diameter))
                item.BackgroundTransparency = 1
                item.ZIndex = 4001
                Corner(item, 999)
                Stroke(item, color, math.max(1, px(thickness)), transparency or 0.05)
                return item
            end

            if style == "NeonRing" then
                ring(22, 2)
                dot(3, 0, 0)
            elseif style == "TargetLock" then
                ring(21, 2)
                line(2, 5, 0, -14)
                line(2, 5, 0, 14)
                line(5, 2, -14, 0)
                line(5, 2, 14, 0)
                dot(2, 0, 0)
            elseif style == "DiamondGrid" then
                local diamond = part(16, 16, 0, 0, 45, nil, 0, true)
                diamond.BackgroundTransparency = 1
                Stroke(diamond, color, math.max(1, px(2)), 0.05)
                dot(3, 0, 0)
            elseif style == "Brackets" then

                local r, arm, thick = 10, 6, 2
                local function corner(sx, sy)
                    line(arm, thick, sx * (r - arm / 2), sy * r)
                    line(thick, arm, sx * r, sy * (r - arm / 2))
                end
                corner(-1, -1)
                corner(1, -1)
                corner(-1, 1)
                corner(1, 1)
                dot(2, 0, 0)
            elseif style == "StarPoint" then
                line(2, 17, 0, 0)
                line(17, 2, 0, 0)
                line(2, 13, 0, 0, 45)
                line(13, 2, 0, 0, 45)
                dot(4, 0, 0)
            elseif style == "FourDots" then
                dot(4, -8, -8)
                dot(4, 8, -8)
                dot(4, -8, 8)
                dot(4, 8, 8)
                dot(2, 0, 0)
            elseif style == "PulseHalo" then
                ring(26, 1, 0.55)
                ring(17, 2, 0.02)
                dot(3, 0, 0)
            elseif style == "SquareDot" then
                local square = part(18, 18, 0, 0, 0, nil, 2, true)
                square.BackgroundTransparency = 1
                Stroke(square, color, math.max(1, px(2)), 0.05)
                dot(3, 0, 0)
            elseif style == "MinimalPlus" then
                line(2, 18, 0, 0)
                line(18, 2, 0, 0)
                dot(2, 0, 0)
            elseif style == "Chevron" then
                line(2, 12, -5, -2, -42)
                line(2, 12, 5, -2, 42)
                dot(3, 0, 2)
            elseif style == "OrbitDot" then
                ring(21, 1, 0.1)
                dot(4, 0, -11)
                dot(2, 0, 0)
            elseif style == "CrossDot" then
                line(2, 6, 0, -9)
                line(2, 6, 0, 9)
                line(6, 2, -9, 0)
                line(6, 2, 9, 0)
                dot(3, 0, 0)

            elseif style == "ClassicGap" then
                line(2, 7, 0, -8)
                line(2, 7, 0, 8)
                line(7, 2, -8, 0)
                line(7, 2, 8, 0)
            elseif style == "TCross" then
                line(2, 8, 0, 7)
                line(14, 2, 0, 0)
            elseif style == "DotOnly" then
                dot(5, 0, 0)
            elseif style == "MicroDot" then
                dot(2, 0, 0)
            elseif style == "ThinCross" then
                line(1, 20, 0, 0)
                line(20, 1, 0, 0)
            elseif style == "RingGap" then
                ring(20, 2, 0.05)
                line(2, 5, 0, -13)
                line(2, 5, 0, 13)
            elseif style == "ArrowUp" then
                line(2, 9, -3, -4, -38)
                line(2, 9, 3, -4, 38)
                line(2, 8, 0, 4)
            elseif style == "CornerTicks" then
                local r, arm, thick = 9, 4, 2
                local function cornerTick(sx, sy)
                    line(arm, thick, sx * (r - arm / 2), sy * r)
                    line(thick, arm, sx * r, sy * (r - arm / 2))
                end
                cornerTick(-1, -1)
                cornerTick(1, -1)
                cornerTick(-1, 1)
                cornerTick(1, 1)
            end
        end

        mkSlider(secCustoms, "Crosshair Size", 8, 128, 32, function(v) S.CrosshairSize = v end, 2.5)

        local GuiSvc = game:GetService("GuiService")
        local function cursorSpot()
            local loc = UIS:GetMouseLocation()
            local inset = GuiSvc:GetGuiInset()
            return loc.X - inset.X, loc.Y - inset.Y
        end

        S._RefreshCustomCursor = function()
            local mouse = Players.LocalPlayer:GetMouse()
            if not S.CustomCrosshair then
                cursorGui.Visible = false
                vectorCursorGui.Visible = false
                UIS.MouseIconEnabled = true
                lastVectorKey = ""

                for _, id in pairs(CustomCrosshairs) do
                    if mouse.Icon == id then mouse.Icon = "" end
                end
                if S.CrosshairAssetId and mouse.Icon == S.CrosshairAssetId then mouse.Icon = "" end
                return
            end

            local menuOpen = Main and Main.Visible
            if menuOpen then
                cursorGui.Visible = false
                vectorCursorGui.Visible = false
                UIS.MouseIconEnabled = true
                return
            end
            local size = math.clamp(tonumber(S.CrosshairSize) or 32, 8, 128)
            local entries = S._CursorEntries
            local entryCount = type(entries) == "table" and #entries or #CustomCrosshairs
            local idx = ((tonumber(S.CrosshairIndex) or 1) - 1) % math.max(1, entryCount) + 1
            local entry = type(entries) == "table" and entries[idx] or nil
            if entry and entry.Kind == "Vector" then
                cursorGui.Visible = false
                local key = tostring(entry.Style) .. ":" .. tostring(size)
                if key ~= lastVectorKey then
                    vectorCursorGui.Size = UDim2.fromOffset(size, size)
                    buildVectorCursor(entry.Style, size)
                    lastVectorKey = key
                end
                local cx, cy = cursorSpot()
                vectorCursorGui.Position = UDim2.fromOffset(cx, cy)
                vectorCursorGui.Visible = true
            else
                vectorCursorGui.Visible = false
                lastVectorKey = ""
                local selectedAsset = type(S.CrosshairAssetId) == "string" and S.CrosshairAssetId ~= "" and S.CrosshairAssetId or nil
                local img = selectedAsset or CustomCrosshairs[((idx - 1) % #CustomCrosshairs) + 1] or CustomCrosshairs[1]
                if not img or img == "" then return end
                cursorGui.Image = img
                cursorGui.AnchorPoint = (entry and entry.Hotspot) or Vector2.new(0.5, 0.5)
                cursorGui.Size = UDim2.fromOffset(size, size)
                local cx, cy = cursorSpot()
                cursorGui.Position = UDim2.fromOffset(cx, cy)
                cursorGui.Visible = true
            end
            UIS.MouseIconEnabled = false
        end
        tc(RunService.RenderStepped:Connect(S._RefreshCustomCursor))

        cleanup(function()
            pcall(function() UIS.MouseIconEnabled = true end)
        end)
    end

    local sec1 = mkSection(Pages.Visuals, "ESP", 1, true)
    mkToggle(sec1, "Role Chams", false, function(v) S.RoleChams = v end, 1)
    mkCycle(sec1, "Chams Fill", {"Solid","Transparent","Glass","Neon","Flat","Soft","Matte","Crystal","Frosted","Ghost","Pearl","Satin","Holographic","Milky","Gradient Fill","Pulse Fill","Rainbow","Metallic","X-Ray","Glow Fill"}, "Solid", function(v) S.ChamsFillStyle = v end, 2)
    mkCycle(sec1, "Chams Outline", {"Solid","Glow","Neon","Dashed","Pulse","Rainbow","Thin","Thick","Soft Glow","Double Outline"}, "Solid", function(v) S.ChamsOutlineStyle = v end, 3)
    mkToggle(sec1, "Self Chams", false, function(v) S.SelfChams = v end, 4)
    mkSlider(sec1, "Chams Opacity", 10, 100, 50, function(v) S.ChamsOpacity = v end, 5)
    mkToggle(sec1, "Name ESP", false, function(v) S.NameESP = v end, 6)
    mkCycle(sec1, "Name Style", {"Simple","Shadow","Outline","Capsule","Rounded Tag","Health Under","Weapon Under","Gradient Text"}, "Simple", function(v) S.NameStyle = v end, 7)
    mkToggle(sec1, "Distance ESP", false, function(v) S.DistanceESP = v end, 8)
    mkCycle(sec1, "Dist Style", {"Text Only","Capsule","Rounded","Shadow","Outline","Dynamic Size"}, "Text Only", function(v) S.DistStyle = v end, 9)
    mkToggle(sec1, "Role ESP", false, function(v) S.RoleESP = v end, 10)
    mkToggle(sec1, "Box ESP", false, function(v) S.BoxESP = v end, 11)
    mkCycle(sec1, "Box Style", {"Full","Corner","Rounded Corner","3D","Filled","Gradient","Health Box","Double","Animated","Pulse","Outline Only","Minimal","Wireframe"}, "Full", function(v) S.BoxStyle = v end, 12)
    mkCycle(sec1, "Box Fill", {"None","Solid","Gradient","Rainbow"}, "None", function(v) S.BoxFillStyle = v end, 13)
    mkToggle(sec1, "Health Bar", false, function(v) S.HealthBar = v end, 14)
    mkCycle(sec1, "Bar Position", {"Left","Right","Bottom","Top"}, "Right", function(v) S.HealthBarPos = v end, 15)
    mkToggle(sec1, "Tracers", false, function(v) S.TracerESP = v end, 16)
    mkCycle(sec1, "Tracer Origin", {"Bottom","Center","Top","Crosshair"}, "Bottom", function(v) S.TracerOrigin = v end, 17)
    mkCycle(sec1, "Tracer Style", {"Default","Curved","Beam","Laser","Dashed","Glow"}, "Default", function(v) S.TracerStyle = v end, 18)
    mkToggle(sec1, "Skeleton ESP", false, function(v) S.SkeletonESP = v end, 19)
    mkCycle(sec1, "Skeleton Style", {"Default","Thin","Thick","Rounded","Glow","Gradient","Animated","Pulse"}, "Default", function(v) S.SkeletonStyle = v end, 20)
    mkToggle(sec1, "Offscreen Arrows", false, function(v) S.OffscreenArrows = v end, 21)
    mkCycle(sec1, "Arrow Style", {"Triangle","Filled","Hollow","Chevron","Diamond","Arrowhead","Minimal","ImGui","Apex","Valorant","Rotating","Pulsing","Breathing","Dist Scaled","Fade Edge","Outline"}, "Triangle", function(v) S.ArrowStyle = v end, 22)
    mkCycle(sec1, "ESP Theme", {"Minimal","ImGui","Neverlose","Gamesense","Monolith","Skeet","Clean","Modern","Flat","Cyber","Frost","Glass","Material","Soft UI","Tournament"}, "Minimal", function(v) S.ESPTheme = v end, 23)
    mkSlider(sec1, "ESP Max Dist", 100, 2000, 1000, function(v) S.ESPMaxDist = v end, 24)
    mkToggle(sec1, "Head Dot", false, function(v) S.HeadDot = v end, 25)
    local sec5 = mkSection(Pages.Visuals, "Alerts", 3, true)
    mkToggle(sec5, "Gun Drop Notify", false, function(v) S.GunNotify = v end, 1)

    local secFx = mkSection(Pages.Visuals, "Color Grading", 7, true)
    mkSlider(secFx, "Saturation", -100, 100, 0, function(v) S.Saturation = v end, 1)
    mkSlider(secFx, "Contrast", -100, 100, 0, function(v) S.Contrast = v end, 2)

    local secShaders = mkSection(Pages.Visuals, "Shader Presets", 8, true)

    local SHADER_LIST = {
        "RTX Low", "RTX Medium", "RTX High", "RTX Ultra", "Night Shaders", "Pink Shaders", "Custom",
    }
    local shaderToggles = {}
    local function clearOtherToggles(exceptName)
        for nm, t in pairs(shaderToggles) do
            if nm ~= exceptName and t.state then
                t.state = false
                t.updateVisuals()
            end
        end
    end
    for i, nm in ipairs(SHADER_LIST) do
        shaderToggles[nm] = mkToggle(secShaders, nm, false, function(v)
            if v then
                clearOtherToggles(nm)
                applyShader(nm)
            elseif S.ActiveShader == nm then
                applyShader("None")
            end
        end, i)
    end
    mkAction(secShaders, "Disable Shaders", function()
        clearOtherToggles(nil)
        applyShader("None")
        Notify("Shaders", "All shaders disabled", 2)
    end, #SHADER_LIST + 1)

    local function applyLibraryProfile(name)
        local profile = S._ShaderLibrary and S._ShaderLibrary.Profiles and S._ShaderLibrary.Profiles[name]
        if not profile then
            Notify("Shader Library", "Preset missing: " .. tostring(name), 3)
            return
        end
        for k, v in pairs(profile) do
            if k ~= "category" then S[k] = v end
        end
        clearOtherToggles("Custom")
        if shaderToggles["Custom"] then
            shaderToggles["Custom"].state = true
            shaderToggles["Custom"].updateVisuals()
        end
        applyShader("Custom")
        Notify("Shader Library", "Applied: " .. name, 2)
    end
    local function libraryNames()
        local names = {}
        for nm in pairs(S._ShaderLibrary and S._ShaderLibrary.Profiles or {}) do
            local p = S._ShaderLibrary.Profiles[nm]
            names[#names + 1] = ((p and p.category) or "Other") .. "  |  " .. nm
        end
        table.sort(names)
        return names
    end
    mkAction(secShaders, "Browse Custom Presets", function()
        local names = libraryNames()
        if #names == 0 then
            Notify("Shader Library", "No presets available", 3)
            return
        end
        S._OpenOptionPicker("Browse Custom Presets", names, 0, function(pick)
            local label = names[pick]
            local _, nm = label and label:match("^(.-)  |  (.+)$")
            if nm then applyLibraryProfile(nm) end
        end)
    end, #SHADER_LIST + 2)
    mkAction(secShaders, "Editor Page", function()
        local names = libraryNames()
        if #names == 0 then
            Notify("Shader Library", "No presets available", 3)
            return
        end
        S._OpenOptionPicker("Editor Page", names, 0, function(pick)
            local label = names[pick]
            local _, nm = label and label:match("^(.-)  |  (.+)$")
            if nm then applyLibraryProfile(nm) end
        end)
    end, #SHADER_LIST + 3)

    local shaderStudioSections = {}
    do
        local function section(name, order)
            local sec = mkSection(Pages.Visuals, name, order, true)
            shaderStudioSections[#shaderStudioSections + 1] = sec
            return sec
        end
        local function reapplyCustom()
            if S.ShaderAutoApply ~= false then
                if S.ActiveShader ~= "Custom" then
                    S.ActiveShader = "Custom"
                    clearOtherToggles("Custom")
                    if shaderToggles["Custom"] then
                        shaderToggles["Custom"].state = true
                        shaderToggles["Custom"].updateVisuals()
                    end
                end
                applyShader("Custom")
            end
        end
        local function set(key, value)
            S[key] = value
            reapplyCustom()
        end
        local function rgbControls(sec, prefix, defaults)
            mkSlider(sec, "Red", 0, 255, defaults[1], function(v) set(prefix .. "R", v) end, 1)
            mkSlider(sec, "Green", 0, 255, defaults[2], function(v) set(prefix .. "G", v) end, 2)
            mkSlider(sec, "Blue", 0, 255, defaults[3], function(v) set(prefix .. "B", v) end, 3)
        end

        local secStudio = section("Shader Studio", 9)
        mkCycle(secStudio, "Quality", { "Performance", "Balanced", "Cinematic" }, "Balanced", function(v) set("ShaderQuality", v) end, 1)
        mkToggle(secStudio, "Live Preview", true, function(v) S.ShaderAutoApply = v; if v then reapplyCustom() end end, 2)
        mkAction(secStudio, "Apply Custom", function()
            clearOtherToggles("Custom")
            if shaderToggles["Custom"] then
                shaderToggles["Custom"].state = true
                shaderToggles["Custom"].updateVisuals()
            end
            applyShader("Custom")
            Notify("Shader Studio", "Custom profile applied", 2)
        end, 3)

        local secGrade = section("Color Grade", 10)
        mkToggle(secGrade, "Color Grade", true, function(v) set("ShaderCCEnabled", v) end, 1)
        mkSlider(secGrade, "Saturation", -100, 150, 18, function(v) set("ShaderSaturation", v) end, 2)
        mkSlider(secGrade, "Contrast", -50, 80, 12, function(v) set("ShaderContrast", v) end, 3)
        mkSlider(secGrade, "Brightness", -50, 50, 0, function(v) set("ShaderCCBright", v) end, 4)
        mkCycle(secGrade, "Tint", S._TINTS or { "Neutral" }, "Neutral", function(v) set("ShaderTint", v) end, 5)

        local secTint = section("Custom Tint", 11)
        rgbControls(secTint, "ShaderTint", { 255, 255, 255 })

        local secLighting = section("Lighting", 12)
        mkToggle(secLighting, "Custom Lighting", true, function(v) set("ShaderLightingEnabled", v) end, 1)
        mkSlider(secLighting, "World Light", 50, 400, 200, function(v) set("ShaderBrightness", v) end, 2)
        mkSlider(secLighting, "Exposure", -100, 100, 4, function(v) set("ShaderExposure", v) end, 3)
        mkSlider(secLighting, "Time", 0, 24, 14, function(v) set("ShaderTime", v) end, 4)
        mkToggle(secLighting, "Shadows", true, function(v) set("ShaderShadows", v) end, 5)
        mkSlider(secLighting, "Diffuse", 0, 100, 100, function(v) set("ShaderDiffuse", v) end, 6)
        mkSlider(secLighting, "Reflections", 0, 100, 100, function(v) set("ShaderSpecular", v) end, 7)
        mkSlider(secLighting, "Shadow Soft", 0, 100, 55, function(v) set("ShaderShadowSoftness", v) end, 8)

        local secAmbient = section("Ambient Color", 13)
        rgbControls(secAmbient, "ShaderAmbient", { 96, 100, 110 })
        local secOutdoor = section("Outdoor Color", 14)
        rgbControls(secOutdoor, "ShaderOutdoor", { 140, 146, 160 })

        local secBloom = section("Bloom & Rays", 15)
        mkToggle(secBloom, "Bloom", true, function(v) set("ShaderBloomEnabled", v) end, 1)
        mkSlider(secBloom, "Bloom Power", 0, 200, 40, function(v) set("ShaderBloom", v) end, 2)
        mkSlider(secBloom, "Bloom Size", 1, 56, 24, function(v) set("ShaderBloomSize", v) end, 3)
        mkSlider(secBloom, "Bloom Gate", 0, 400, 155, function(v) set("ShaderBloomThreshold", v) end, 4)
        mkToggle(secBloom, "Sun Rays", true, function(v) set("ShaderSunEnabled", v) end, 5)
        mkSlider(secBloom, "Ray Power", 0, 100, 8, function(v) set("ShaderSunRays", v) end, 6)
        mkSlider(secBloom, "Ray Spread", 0, 100, 68, function(v) set("ShaderSunSpread", v) end, 7)

        local secFocus = section("Camera Focus", 16)
        mkToggle(secFocus, "Depth Focus", false, function(v) set("ShaderDOFEnabled", v) end, 1)
        mkSlider(secFocus, "Focus Power", 0, 100, 0, function(v) set("ShaderDOF", v) end, 2)
        mkSlider(secFocus, "Focus Dist", 0, 200, 45, function(v) set("ShaderDOFFocus", v) end, 3)
        mkSlider(secFocus, "Focus Radius", 0, 200, 70, function(v) set("ShaderDOFRadius", v) end, 4)
        mkSlider(secFocus, "Near Blur", 0, 100, 10, function(v) set("ShaderDOFNear", v) end, 5)
        mkSlider(secFocus, "Far Blur", 0, 100, 8, function(v) set("ShaderDOFFar", v) end, 6)
        mkToggle(secFocus, "Screen Blur", false, function(v) set("ShaderBlurEnabled", v) end, 7)
        mkSlider(secFocus, "Blur Size", 0, 24, 0, function(v) set("ShaderBlur", v) end, 8)

        local secAtmo = section("Atmosphere", 17)
        mkToggle(secAtmo, "Atmosphere", true, function(v) set("ShaderAtmoEnabled", v) end, 1)
        mkSlider(secAtmo, "Density", 0, 75, 22, function(v) set("ShaderAtmo", v) end, 2)
        mkSlider(secAtmo, "Height Offset", -100, 100, 20, function(v) set("ShaderAtmoOffset", v) end, 3)
        mkSlider(secAtmo, "Haze", 0, 1000, 160, function(v) set("ShaderAtmoHaze", v) end, 4)
        mkSlider(secAtmo, "Glare", 0, 1000, 15, function(v) set("ShaderAtmoGlare", v) end, 5)
        local secAtmoColor = section("Atmosphere Color", 18)
        rgbControls(secAtmoColor, "ShaderAtmo", { 210, 214, 222 })
        local secDecay = section("Atmosphere Decay", 19)
        rgbControls(secDecay, "ShaderDecay", { 120, 142, 190 })

        local secLibrary = section("Shader Library", 20)
        local PACK_FILE = "MM2_Configs/_shaderpacks.json"
        local PACK_KEYS = {
            "ShaderQuality", "ShaderAutoApply", "ShaderLightingEnabled", "ShaderBrightness", "ShaderExposure",
            "ShaderTime", "ShaderShadows", "ShaderDiffuse", "ShaderSpecular", "ShaderShadowSoftness",
            "ShaderAmbientR", "ShaderAmbientG", "ShaderAmbientB", "ShaderOutdoorR", "ShaderOutdoorG", "ShaderOutdoorB",
            "ShaderCCEnabled", "ShaderSaturation", "ShaderContrast", "ShaderCCBright", "ShaderTint",
            "ShaderTintR", "ShaderTintG", "ShaderTintB", "ShaderBloomEnabled", "ShaderBloom", "ShaderBloomSize",
            "ShaderBloomThreshold", "ShaderSunEnabled", "ShaderSunRays", "ShaderSunSpread", "ShaderDOFEnabled",
            "ShaderDOF", "ShaderDOFFocus", "ShaderDOFRadius", "ShaderDOFNear", "ShaderDOFFar",
            "ShaderBlurEnabled", "ShaderBlur", "ShaderAtmoEnabled", "ShaderAtmo", "ShaderAtmoOffset",
            "ShaderAtmoHaze", "ShaderAtmoGlare", "ShaderAtmoR", "ShaderAtmoG", "ShaderAtmoB",
            "ShaderDecayR", "ShaderDecayG", "ShaderDecayB",
        }
        local function readPacks()
            local packs = {}
            pcall(function()
                if isfile and readfile and isfile(PACK_FILE) then
                    local ok, decoded = pcall(function()
                        return game:GetService("HttpService"):JSONDecode(readfile(PACK_FILE))
                    end)
                    if ok and type(decoded) == "table" then packs = decoded end
                end
            end)
            return packs
        end
        local function writePacks(packs)
            pcall(function()
                if makefolder and isfolder and not isfolder("MM2_Configs") then makefolder("MM2_Configs") end
                if writefile then
                    writefile(PACK_FILE, game:GetService("HttpService"):JSONEncode(packs))
                end
            end)
        end

        local function slotLabels(packs)
            local names = {}
            for i = 1, 6 do
                local p = packs[tostring(i)]
                if type(p) == "table" then
                    names[i] = ("Slot %d  -  %sh  B%d  Bloom%d  %s"):format(
                        i, tostring(math.floor(tonumber(p.ShaderTime) or 14)),
                        math.floor(tonumber(p.ShaderBrightness) or 200),
                        math.floor(tonumber(p.ShaderBloom) or 0), tostring(p.ShaderTint or "Neutral"))
                else
                    names[i] = ("Slot %d  -  empty"):format(i)
                end
            end
            return names
        end
        mkAction(secLibrary, "Save Profile", function()
            if type(writefile) ~= "function" then
                Notify("Shaders", "This executor cannot write files", 3)
                return
            end
            local packs = readPacks()
            S._OpenOptionPicker("Save to slot", slotLabels(packs), 0, function(pick)
                local snap = {}
                for _, k in ipairs(PACK_KEYS) do snap[k] = S[k] end
                packs[tostring(pick)] = snap
                writePacks(packs)
                Notify("Shaders", "Saved to slot " .. pick, 2)
            end)
        end, 1)
        mkAction(secLibrary, "Load Profile", function()
            local packs = readPacks()
            S._OpenOptionPicker("Load slot", slotLabels(packs), 0, function(pick)
                local p = packs[tostring(pick)]
                if type(p) ~= "table" then
                    Notify("Shaders", "Slot " .. pick .. " is empty", 2)
                    return
                end
                for _, k in ipairs(PACK_KEYS) do
                    if p[k] ~= nil then S[k] = p[k] end
                end
                clearOtherToggles("Custom")
                if shaderToggles["Custom"] then shaderToggles["Custom"].state = true; shaderToggles["Custom"].updateVisuals() end
                applyShader("Custom")
                Notify("Shaders", "Loaded slot " .. pick, 2)
            end)
        end, 2)
        mkAction(secLibrary, "Delete Profile", function()
            local packs = readPacks()
            S._OpenOptionPicker("Delete slot", slotLabels(packs), 0, function(pick)
                packs[tostring(pick)] = nil
                writePacks(packs)
                Notify("Shaders", "Cleared slot " .. pick, 2)
            end)
        end, 3)

        S.shaderStudioReady = true
        local function refreshShaderStudioControls()
            S.shaderStudioReady = true
            if S.ActiveShader == "Custom" then pcall(reapplyCustom) end
            return true
        end
        S._RefreshShaderStudioControls = refreshShaderStudioControls
    end

    local activeVisualsSubTab = "ESP"

    local extraEnvSections = {}
    S._RegisterVisualsEnvSection = function(sec)
        table.insert(extraEnvSections, sec)
        if sec and sec.Parent then sec.Parent.Visible = (activeVisualsSubTab == "Environment") end
    end

    S._RegisterVisualsCustomsSection = function(sec)
        table.insert(S._CustomsSections, sec)
        if sec and sec.Parent then sec.Parent.Visible = (activeVisualsSubTab == "Customs") end
    end
    local function updateVisualsSubTabs()
        local isESP = activeVisualsSubTab == "ESP"
        local isEnvironment = activeVisualsSubTab == "Environment"
        local isShaders = activeVisualsSubTab == "Shaders"
        local isCustoms = activeVisualsSubTab == "Customs"
        styleSubTabActive(espBtn, espStroke, isESP)
        styleSubTabActive(envBtn, envStroke, isEnvironment)
        styleSubTabActive(shaderBtn, shaderStroke, isShaders)
        styleSubTabActive(customBtn, customStroke, isCustoms)

        local function setVisible(vis, ...)
            for i = 1, select("#", ...) do
                local section = select(i, ...)
                if section and section.Parent then section.Parent.Visible = vis end
            end
        end
        setVisible(isESP, sec1, sec5)
        setVisible(isEnvironment, secFx)

        setVisible(isShaders, secShaders)
        for _, section in ipairs(shaderStudioSections) do
            if section and section.Parent then section.Parent.Visible = isShaders end
        end
        setVisible(isCustoms, secCustoms)
        for _, section in ipairs(S._CustomsSections) do
            if section and section.Parent then section.Parent.Visible = isCustoms end
        end

        for _, section in ipairs(extraEnvSections) do
            if section and section.Parent then section.Parent.Visible = isEnvironment end
        end
    end
    S._UpdateVisualsSubtabs = updateVisualsSubTabs

    espBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        activeVisualsSubTab = "ESP"
        updateVisualsSubTabs()
    end)

    envBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        activeVisualsSubTab = "Environment"
        updateVisualsSubTabs()
    end)
    shaderBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        activeVisualsSubTab = "Shaders"
        updateVisualsSubTabs()
    end)
    customBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        activeVisualsSubTab = "Customs"
        updateVisualsSubTabs()
    end)
    updateVisualsSubTabs()
end

do
    local combatSubTabBar = Instance.new("Frame")
    combatSubTabBar.Name = "SubTabBar"
    combatSubTabBar.LayoutOrder = 0
    combatSubTabBar.BackgroundTransparency = 1
    combatSubTabBar.Size = UDim2.new(1, 0, 0, 35)
    combatSubTabBar:SetAttribute("LayoutHeight", 35)
    combatSubTabBar.Parent = Pages.Combat

    local subTabGrid = Instance.new("UIGridLayout")
    subTabGrid.FillDirection = Enum.FillDirection.Horizontal
    subTabGrid.FillDirectionMaxCells = 3
    subTabGrid.SortOrder = Enum.SortOrder.LayoutOrder
    subTabGrid.HorizontalAlignment = Enum.HorizontalAlignment.Center
    subTabGrid.VerticalAlignment = Enum.VerticalAlignment.Top
    subTabGrid.CellPadding = UDim2.fromOffset(8, 6)
    subTabGrid.CellSize = UDim2.new(1 / 3, -6, 0, 29)
    subTabGrid.Parent = combatSubTabBar

    local sheriffBtn = Instance.new("TextButton")
    local murdererBtn = Instance.new("TextButton")
    local survivorsBtn = Instance.new("TextButton")

    local sheriffStroke = mkSubTabBtn(combatSubTabBar, sheriffBtn, "Sheriff", 1, 1 / 3, -6)
    local murdererStroke = mkSubTabBtn(combatSubTabBar, murdererBtn, "Murderer", 2, 1 / 3, -6)
    local survivorsStroke = mkSubTabBtn(combatSubTabBar, survivorsBtn, "Survivors", 3, 1 / 3, -6)

    local secSheriffAim = mkSection(Pages.Combat, "Sheriff Aim", 1, true)
    secSheriffAim.Parent:SetAttribute("ConfigSection", "Silent Aim")
    mkToggle(secSheriffAim, "Silent Aim", false, function(v) S.SheriffSilentAim = v end, 1, "Sheriff")
    mkToggle(secSheriffAim, "Piercing Bullet", false, function(v) S.SheriffSilentAimPiercing = v end, 2)
    mkToggle(secSheriffAim, "Wall Check", false, function(v) S.SheriffSilentAimWallCheck = v end, 3)
    mkToggle(secSheriffAim, "Anti-Desync", false, function(v) S.SheriffAntiDesync = v end, 4)

    local secGunFire = mkSection(Pages.Combat, "Gun Fire", 2, true)
    secGunFire.Parent:SetAttribute("ConfigSection", "Silent Aim")
    mkToggle(secGunFire, "Force Shoot", false, function(v) S.ForceShoot = v end, 1)
    do
        local function heldGun()
            local c = LP.Character
            local function pick(container)
                if not container then return nil end
                for _, t in ipairs(container:GetChildren()) do
                    if t:IsA("Tool") and t:FindFirstChild("Shoot") then return t end
                end
                return nil
            end

            return pick(c), pick(LP:FindFirstChildOfClass("Backpack"))
        end

        local function mouseTargetCF()
            local cam = workspace.CurrentCamera
            if not cam then return nil end
            local m = UIS:GetMouseLocation()
            local x, y = m.X, m.Y
            local lock = LP:FindFirstChild("PlayerScripts") and LP.PlayerScripts:FindFirstChild("MouseLock")
            if lock and lock:GetAttribute("Enabled") == true then
                x, y = cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2
            end
            local ray = cam:ViewportPointToRay(x, y)
            local ignore = { LP.Character }

            for _, v in ipairs(game:GetService("CollectionService"):GetTagged("WeaponPassthrough")) do
                table.insert(ignore, v)
            end
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            params.FilterDescendantsInstances = ignore
            local hit

            for _ = 1, 12 do
                hit = workspace:Raycast(ray.Origin, ray.Direction * 300, params)
                if not hit or not hit.Instance or hit.Instance.Transparency ~= 1 then break end
                table.insert(ignore, hit.Instance)
                params.FilterDescendantsInstances = ignore
            end
            return CFrame.new(hit and hit.Position or (ray.Origin + ray.Direction * 300))
        end

        task.spawn(function()
            while S.Gui and S.Gui.Parent do
                if not S.ForceShoot or S.Destroyed then
                    task.wait(0.2)
                else
                    pcall(function()
                        local held, stowed = heldGun()
                        local gun = held
                        if not gun and stowed then
                            local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
                            if hum then pcall(function() hum:EquipTool(stowed) end) end
                            local _, nowHeld = heldGun()
                            gun = nowHeld or stowed
                        end
                        if not gun then return end
                        if gun.Enabled == false then gun.Enabled = true end
                        local hrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                        local att = hrp and hrp:FindFirstChild("GunRaycastAttachment")
                        if not att then return end
                        local target = mouseTargetCF()
                        if not target then return end
                        local shoot = gun:FindFirstChild("Shoot")
                        if shoot then shoot:FireServer(att.WorldCFrame, target) end
                    end)
                end
                RunService.Heartbeat:Wait()
            end
        end)
    end

    local secKnifeAim = mkSection(Pages.Combat, "Knife Aim", 3, true)
    secKnifeAim.Parent:SetAttribute("ConfigSection", "Knife Combat & Exploits")
    mkToggle(secKnifeAim, "Silent Aim", false, function(v) S.KnifeSilentAim = v end, 1, "Knife Silent Aim")
    mkToggle(secKnifeAim, "Wall Check", false, function(v) S.KnifeSilentAimWallCheck = v end, 2)
    mkToggle(secKnifeAim, "Prioritize Sheriff/Hero", true, function(v) S.KnifeSilentAimPrioritizeSheriff = v end, 4)

    mkCycle(secKnifeAim, "Prediction", { "Off", "Standard", "Lag Comp", "Perfect", "Adaptive" },
        "Perfect", function(v) S.KnifeSilentAimPredictMode = v end, 5)
    mkSlider(secKnifeAim, "Prediction Amount (%)", 0, 200, 100, function(v) S.KnifeSilentAimPrediction = v end, 6)
    mkSlider(secKnifeAim, "Ping Offset (ms)", -100, 200, 0, function(v) S.KnifePingOffset = v end, 7)

    local secKnifeThrow = mkSection(Pages.Combat, "Knife Throw", 4, true)
    secKnifeThrow.Parent:SetAttribute("ConfigSection", "Knife Combat & Exploits")
    mkToggle(secKnifeThrow, "Fast Throw", false, function(v)
        S.FastThrow = v
        pcall(function() if S._ReapplyThrowSpeed then S._ReapplyThrowSpeed() end end)
    end, 1, "Fast Knife Throw")
    mkToggle(secKnifeThrow, "No Throw Animation", false, function(v)
        S.NoKnifeAnim = v
        pcall(function() if S._ReapplyThrowSpeed then S._ReapplyThrowSpeed() end end)
    end, 2, "No Knife Anim")
    mkSlider(secKnifeThrow, "Throw Windup Speed", 1, 10, 6, function(v)
        S.KnifeThrowSpeedControl = true
        S.KnifeThrowWindup = (10 - v) / 10
        pcall(function() if S._ReapplyThrowSpeed then S._ReapplyThrowSpeed() end end)
    end, 3)
    mkSlider(secKnifeThrow, "Knife Flight Speed", 20, 250, 100, function(v)
        S.KnifeFlightSpeedControl = true
        S.KnifeFlightSpeed = v
        pcall(function() if S._ReapplyKnifeFlightSpeed then S._ReapplyKnifeFlightSpeed() end end)
    end, 4)

    local secMurder = mkSection(Pages.Combat, "Kill Suite", 5, true)
    secMurder.Parent:SetAttribute("ConfigSection", "Murderer Kill Suite")
    mkToggle(secMurder, "Auto Kill Sheriff / Hero", false, function(v) S.AutoKillSheriff = v end, 1)
    mkToggle(secMurder, "Auto Kill Nearest", false, function(v) S.AutoKillNearest = v end, 2)
    mkToggle(secMurder, "Kill Aura", false, function(v) S.KillAura = v end, 3)
    mkSlider(secMurder, "Kill Aura Range", 5, 60, 18, function(v) S.KillAuraRange = v end, 4)
    mkToggle(secMurder, "Click to Kill", false, function(v) S.ClickKill = v end, 5)
    mkAction(secMurder, "Kill Nearest", function()
        local n = S._MurdererNearest and S._MurdererNearest()
        if n and S._MurdererKill then
            if S._MurdererKill(n) then Notify("Murderer", "Killed " .. n.Name, 2)
            else Notify("Murderer", "Hold the Knife first (be the Murderer)", 2) end
        else Notify("Murderer", "No target", 2) end
    end, 6)
    mkAction(secMurder, "Kill All", function()
        if S._MurdererKillAll then S._MurdererKillAll() else Notify("Murderer", "Not ready", 2) end
    end, 7)

    local secSurvival = mkSection(Pages.Combat, "Gun Recovery & Evade", 6, true)
    secSurvival.Parent:SetAttribute("ConfigSection", "Innocent Survival")
    mkToggle(secSurvival, "Auto Grab Gun", false, function(v)
        S.AutoGrabGun = v
        if v and S.GrabGunNow then S.GrabGunNow(true) end
    end, 1)
    mkAction(secSurvival, "Grab Gun Now", function()
        if S.GrabGunNow then S.GrabGunNow(false) end
    end, 2)
    mkToggle(secSurvival, "Gun Drop Notify", false, function(v) S.GunNotify = v end, 3)

    local activeSubTab = "Sheriff"
    local function updateSubTabs()
        local isSheriff = activeSubTab == "Sheriff"
        local isMurderer = activeSubTab == "Murderer"
        local isSurvivors = activeSubTab == "Survivors"

        styleSubTabActive(sheriffBtn, sheriffStroke, isSheriff)
        styleSubTabActive(murdererBtn, murdererStroke, isMurderer)
        styleSubTabActive(survivorsBtn, survivorsStroke, isSurvivors)

        secSheriffAim.Parent.Visible = isSheriff
        secGunFire.Parent.Visible = isSheriff
        secKnifeAim.Parent.Visible = isMurderer
        secKnifeThrow.Parent.Visible = isMurderer
        secMurder.Parent.Visible = isMurderer
        secSurvival.Parent.Visible = isSurvivors
    end
    S._UpdateCombatSubtabs = updateSubTabs

    sheriffBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        activeSubTab = "Sheriff"
        updateSubTabs()
    end)
    murdererBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        activeSubTab = "Murderer"
        updateSubTabs()
    end)
    survivorsBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        activeSubTab = "Survivors"
        updateSubTabs()
    end)

    updateSubTabs()
end
do
    silentAimTargetChar = function(mode, fovCheck, wallCheck, aimPartName)
        local cam = workspace.CurrentCamera
        if not cam then return nil end
        mode = mode or "Nearest"
        local radius = S.FOVRadius or 360
        local m = UIS:GetMouseLocation()
        local center = Vector2.new(m.X, m.Y)
        local best, bestScore = nil, math.huge
        local rp
        if wallCheck then
            rp = RaycastParams.new()
            rp.FilterType = Enum.RaycastFilterType.Exclude
            rp.FilterDescendantsInstances = { LP.Character }
        end
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character and not isWhitelisted(p) then
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if not hum or hum.Health <= 0 then continue end
                local head = p.Character:FindFirstChild("Head")
                    or p.Character:FindFirstChild("UpperTorso")
                    or p.Character:FindFirstChild("Torso")
                    or p.Character:FindFirstChild("HumanoidRootPart")
                if not head then continue end
                local r = getRole(p)
                local ok = false
                if mode == "Nearest" then ok = true
                elseif mode == "Murderer" then ok = (r == "Murderer")
                elseif mode == "Sheriff" then ok = (r == "Sheriff")
                elseif mode == "Hero" then ok = (r == "Hero")
                elseif mode == "SheriffOrHero" then ok = (r == "Sheriff" or r == "Hero")
                elseif mode == "Innocent" then ok = (r == "Innocent")
                end
                if not ok then continue end
                local isVisible = true
                if wallCheck and rp and LP.Character and LP.Character:FindFirstChild("Head") then
                    rp.FilterDescendantsInstances = { LP.Character, p.Character }
                    local startPos = LP.Character.Head.Position
                    local dir = head.Position - startPos
                    local ray = workspace:Raycast(startPos, dir, rp)
                    if ray and ray.Instance then isVisible = false end
                end
                if not isVisible then continue end
                local targetPart = head
                if aimPartName == "Closest" then
                    local closestPart, closestPartDist = head, math.huge
                    for _, part in ipairs(p.Character:GetChildren()) do
                        if part:IsA("BasePart") then
                            local sp2, on2 = cam:WorldToViewportPoint(part.Position)
                            if on2 then
                                local d = (Vector2.new(sp2.X, sp2.Y) - center).Magnitude
                                if d < closestPartDist then closestPartDist = d; closestPart = part end
                            end
                        end
                    end
                    targetPart = closestPart
                elseif aimPartName == "Random" then
                    local parts = {"Head", "UpperTorso", "Torso", "HumanoidRootPart"}
                    local chosen = parts[math.random(1, #parts)]
                    targetPart = p.Character:FindFirstChild(chosen) or head
                elseif aimPartName then
                    targetPart = p.Character:FindFirstChild(aimPartName)
                        or p.Character:FindFirstChild("Head")
                        or p.Character:FindFirstChild("UpperTorso")
                        or p.Character:FindFirstChild("Torso")
                        or p.Character:FindFirstChild("HumanoidRootPart")
                        or head
                end
                if fovCheck then
                    local sp2, on2 = cam:WorldToViewportPoint(targetPart.Position)
                    if on2 then
                        local d = (Vector2.new(sp2.X, sp2.Y) - center).Magnitude
                        if d < radius and d < bestScore then bestScore = d; best = p.Character end
                    end
                else
                    local lpPart = LP.Character and (LP.Character:FindFirstChild("HumanoidRootPart") or LP.Character:FindFirstChild("Head"))
                    if lpPart then
                        local dist = (targetPart.Position - lpPart.Position).Magnitude
                        if dist < bestScore then bestScore = dist; best = p.Character end
                    end
                end
            end
        end
        return best
    end
do
    S._HooksActive = true
    cleanup(function() S._HooksActive = false end)

    local beamHooks = {}
    local piercingVisualHookReady = false
    S._PiercingVisualHookReady = function() return piercingVisualHookReady end
    local function muzzlePosition()
        local c = LP.Character
        local hrp = c and c:FindFirstChild("HumanoidRootPart")
        local att = hrp and hrp:FindFirstChild("GunRaycastAttachment")
        return att and att.WorldPosition
    end
    local function installGunBeamHook()
        if not (getconnections and hookfunction) then return end
        local ok, event = pcall(function()
            return game:GetService("ReplicatedStorage"):FindFirstChild("ClientServices", true)
                and game:GetService("ReplicatedStorage").ClientServices:FindFirstChild("GunFired")
        end)
        if not (ok and event and event.OnClientEvent) then return end
        local okConnections, connections = pcall(function() return getconnections(event.OnClientEvent) end)
        if not (okConnections and type(connections) == "table") then return end
        for _, connection in ipairs(connections) do
            local fn = connection and connection.Function
            if fn and not beamHooks[fn] then
                local oldFn
                local wrapper = function(handle, startPos, endPos, hitPart, ...)
                    if S._HooksActive and S.SheriffSilentAimPiercing and typeof(startPos) == "Vector3" then
                        local origin = muzzlePosition()
                        if origin then return oldFn(handle, origin, endPos, hitPart, ...) end
                    end
                    return oldFn(handle, startPos, endPos, hitPart, ...)
                end
                if newcclosure then wrapper = newcclosure(wrapper) end
                local hooked = pcall(function() oldFn = hookfunction(fn, wrapper) end)
                if hooked and oldFn then
                    beamHooks[fn] = true
                    piercingVisualHookReady = true
                end
            end
        end
    end
    task.spawn(function()
        for _ = 1, 12 do
            pcall(installGunBeamHook)
            if piercingVisualHookReady then break end
            task.wait(0.5)
        end
    end)
end
do

    local function getMurdererChar()
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and p.Character and not isWhitelisted(p) and getRole(p) == "Murderer" then
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if hum and hum.Health > 0 and p.Character:FindFirstChild("HumanoidRootPart") then
                    return p.Character
                end
            end
        end
        return nil
    end
    S._GetMurdererChar = getMurdererChar

    local resolverData = {}
    local lastResolveTime = 0
    S._ResolveData = resolverData

RunService.Heartbeat:Connect(function()
    if not (S.SheriffAntiDesync or S.KnifeSilentAim or S.SheriffSilentAim or S.SheriffSilentAimPiercing) then return end

    local chars = {}
    if S._GetMurdererChar then
        local murd = S._GetMurdererChar()
        if murd then table.insert(chars, murd) end
    end
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= LP and p.Character and p.Character ~= chars[1] then
            table.insert(chars, p.Character)
        end
    end

    local now = os.clock()
    local dt = now - lastResolveTime
    lastResolveTime = now
    if dt < 0.001 then dt = 0.001 end

    for _, char in ipairs(chars) do
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if hrp then
            local rawPos = hrp.Position
            local d = resolverData[char]
            if not d then
                resolverData[char] = { lastPos = rawPos, lastValidTime = now, smoothVel = Vector3.zero, history = {}, desyncStart = 0 }
                d = resolverData[char]
            end

            local step = rawPos - d.lastPos
            local instVel = step / dt

            if instVel.Magnitude < 5 then
                -- Effectively stationary (interpolation jitter noise).
                d.smoothVel = d.smoothVel:Lerp(Vector3.zero, 0.25)
                d.lastPos = rawPos
                d.lastValidTime = now
                d.desyncStart = 0
            elseif instVel.Magnitude > 150 then
                -- Detect desync: If they move more than 150 studs/sec physically in 1 frame, they are teleporting.
                if d.desyncStart == 0 then d.desyncStart = now end
                if now - d.desyncStart > 0.5 then
                    -- Continuous desync for 0.5s -> likely a real teleport (e.g. map change or void). Reset.
                    d.lastPos = rawPos
                    d.lastValidTime = now
                    d.desyncStart = 0
                    d.history = {}
                    d.smoothVel = Vector3.zero
                end
            else
                -- Valid physical movement
                d.desyncStart = 0
                table.insert(d.history, instVel)
                if #d.history > 6 then table.remove(d.history, 1) end

                local sumVel = Vector3.zero
                for _, v in ipairs(d.history) do sumVel = sumVel + v end
                d.smoothVel = sumVel / #d.history

                d.lastPos = rawPos
                d.lastValidTime = now
            end
        end
    end
end)

S._ResolveDesynced = function(targetChar)
    local d = resolverData[targetChar]
    return d ~= nil and d.desyncStart > 0
end

S._ResolveSmoothVel = function(targetChar)
    local d = resolverData[targetChar]
    return d and d.smoothVel or nil
end

local function resolveTargetPos(targetChar, hrp)
    local raw = hrp.Position
    if not S.SheriffAntiDesync then return raw end
    
    local d = resolverData[targetChar]
    if not d then return raw end
    
    if d.desyncStart > 0 then
        -- Target is currently flagged as desyncing (teleporting erratically)
        local age = os.clock() - d.lastValidTime
        if age > 1.0 then return raw end -- fallback if they've been desyncing too long
        
        -- Fallback to alternative body parts. Desync scripts usually only break HumanoidRootPart.
        local altPart = targetChar:FindFirstChild("UpperTorso") or targetChar:FindFirstChild("Torso") or targetChar:FindFirstChild("Head")
        if altPart then
            local altPos = altPart.Position
            -- If the alternative part is within reasonable bounds of the last valid position, trust it.
            if (altPos - d.lastPos).Magnitude < 80 then
                return altPos
            end
        end
        
        -- Extreme fallback: Extrapolate from the last valid position using smoothed velocity
        local predicted = d.lastPos + (d.smoothVel * age)
        if (predicted - d.lastPos).Magnitude > 50 then
            predicted = d.lastPos + ((predicted - d.lastPos).Unit * 50)
        end
        return predicted
    end
    
    return raw
end
S._ResolveAntiDesyncPos = resolveTargetPos

    local function piercingOrigin(hitPos, targetChar)
        local hrp = targetChar:FindFirstChild("HumanoidRootPart")
        local vel = hrp and hrp.AssemblyLinearVelocity or Vector3.zero
        if S._ResolveSmoothVel then
            local sv = S._ResolveSmoothVel(targetChar)
            if sv and sv.Magnitude > 0.5 then vel = sv end
        end
        local back = (vel.Magnitude > 1.5) and (-vel.Unit * 2.5) or Vector3.new(0, 1.25, 0)
        return CFrame.lookAt(hitPos + back, hitPos)
    end

    local function handleFireServer(self, ...)
    local args = {...}

    if self.Name == "Shoot" and (S.SheriffSilentAim or S.SheriffSilentAimPiercing) then
        local targetChar = getMurdererChar()
        if not targetChar then return nil end
        local hrp = targetChar:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        local pos = resolveTargetPos(targetChar, hrp)
        if S.SheriffSilentAim and pos.Magnitude > 0.5
            and not (S._ResolveDesynced and S._ResolveDesynced(targetChar)) then
            local pred = getPredictedPosition(targetChar, "HumanoidRootPart", "Lag Comp", 100, S.KnifePingOffset or 0, 0)
            if pred and pred.Magnitude > 0.5 then pos = pred end
        end
        if S.SheriffSilentAimPiercing then
            args[1] = piercingOrigin(pos, targetChar)
        end
        args[2] = (typeof(args[2]) == "Vector3") and pos or CFrame.new(pos)
        return args
    end

    if S.AntiCoin and (self.Name:find("Coin") or self.Name:find("coin") or self.Name == "CollectCoin" or self.Name == "CoinEvent" or self.Name == "PickUp") then
        return {}
    end

    if self.Name == "KnifeThrown" and S.KnifeSilentAim then
        local targetChar = (S.KnifeSilentAimPrioritizeSheriff and silentAimTargetChar("SheriffOrHero", S.KnifeSilentAimFOVEnabled, S.KnifeSilentAimWallCheck, "Head"))
            or silentAimTargetChar("Nearest", S.KnifeSilentAimFOVEnabled, S.KnifeSilentAimWallCheck, "Head")
        if not targetChar then return nil end
        local aimPart = targetChar:FindFirstChild("Head")
            or targetChar:FindFirstChild("UpperTorso")
            or targetChar:FindFirstChild("Torso")
            or targetChar:FindFirstChild("HumanoidRootPart")
        if not aimPart then return nil end
        local mode = S.KnifeSilentAimPredictMode or "Perfect"
        local amt = (mode == "Off") and 0 or (S.KnifeSilentAimPrediction or 100)
        local flight = (S.KnifeFlightSpeedControl and tonumber(S.KnifeFlightSpeed)) or 80
        local pos = getPredictedPosition(targetChar, aimPart.Name, mode, amt, S.KnifePingOffset or 0, flight)
        if not (pos and pos.Magnitude > 0.5) then pos = aimPart.Position end
        if pos and pos.Magnitude > 0.5 and S.SheriffAntiDesync and S._ResolveDesynced and S._ResolveDesynced(targetChar) then
            local hrp2 = targetChar:FindFirstChild("HumanoidRootPart")
            if hrp2 then
                local res = resolveTargetPos(targetChar, hrp2)
                if res and res.Magnitude > 0.5 then pos = res end
            end
        end
        if typeof(args[1]) == "CFrame" then
            args[1] = CFrame.lookAt(args[1].Position, pos)
        end
        args[2] = (typeof(args[2]) == "Vector3") and pos or CFrame.new(pos)
        return args
    end

    return nil
end

if hookmetamethod then
    local oldNamecall
    oldNamecall = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
        if not S._HooksActive then return oldNamecall(self, ...) end
        local cc = checkcaller and checkcaller()
        if not cc and getnamecallmethod() == "FireServer" then
            local ok, modArgs = pcall(handleFireServer, self, ...)
            if ok and type(modArgs) == "table" then
                return self.FireServer(self, table.unpack(modArgs))
            end
            return self.FireServer(self, ...)
        end
        return oldNamecall(self, ...)
    end))
end

end

do
    local MSP = {History = {}, Latency = 0, Jitter = 0}
    S._MSP = MSP
    local function getPing()
        local ping = 0
        pcall(function() ping = LP:GetNetworkPing() * 1000 end)
        return math.clamp(ping, 50, 500)
    end

    local pingSamples, pingHead = {}, 0
    local function trackJitter(pingMs)
        pingHead = (pingHead % 40) + 1
        pingSamples[pingHead] = pingMs
        local lo, hi = math.huge, -math.huge
        for _, v in pairs(pingSamples) do
            if v < lo then lo = v end
            if v > hi then hi = v end
        end
        if lo <= hi then MSP.Jitter = math.clamp((hi - lo) / 2000, 0, 0.15) end
    end

    local knifeChamsWasOn = false
    tc(RunService.Heartbeat:Connect(function()

        if S.KnifeSilentAim or S.SheriffSilentAim or S.SheriffSilentAimPiercing then
            local pingMs = getPing()
            MSP.Latency = pingMs / 1000
            trackJitter(pingMs)
            local now = tick()
            for _, p in ipairs(Players:GetPlayers()) do
                local character = p.Character
                local hrp = character and character:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local entry = MSP.History[p.Name]
                    if not entry then
                        MSP.History[p.Name] = { Pos = hrp.Position, Time = now, Vel = Vector3.new(), Acc = Vector3.new() }
                    else
                        local dt = now - entry.Time
                        if dt > 0 then
                            local newVel = (hrp.Position - entry.Pos) / dt
                            if S._ResolveSmoothVel then
                                local sv = S._ResolveSmoothVel(character)
                                if sv and sv.Magnitude > 0.5 then newVel = newVel:Lerp(sv, 0.7) end
                            end
                            local rawAcc = (newVel - (entry.Vel or newVel)) / dt
                            entry.Acc = (entry.Acc or Vector3.new()):Lerp(rawAcc, 0.3)
                            entry.Vel = newVel
                            entry.Pos = hrp.Position
                            entry.Time = now
                        end
                    end
                end
            end
        end

        if S.KnifeChams or knifeChamsWasOn then
            knifeChamsWasOn = S.KnifeChams == true
            for _, v in ipairs(workspace:GetChildren()) do
                if v.Name == "Knife" or v.Name == "NormalKnife" or v.Name == "ThrowingKnife" then
                    local h = v:FindFirstChild("Handle") or v:FindFirstChild("KnifeVisual") or v:FindFirstChildWhichIsA("BasePart")
                    if h and not h.Anchored then
                        if S.KnifeChams then
                            createHighlight(v, Color3.fromRGB(255, 0, 0), "KnifeChamsHighlight")
                        else
                            removeCham(v, "KnifeChamsHighlight")
                        end
                    end
                end
            end
        end

    end))
    getPredictedPosition = function(targetChar, partName, mode, predAmount, customPingOffset, customBulletSpeed)
        local hrp = targetChar:FindFirstChild("HumanoidRootPart")
        local part = targetChar:FindFirstChild(partName)
            or targetChar:FindFirstChild("Head")
            or targetChar:FindFirstChild("UpperTorso")
            or targetChar:FindFirstChild("Torso")
            or hrp
        if not part or not hrp then return Vector3.new() end
        if predAmount == 0 then return part.Position end
        local hist = MSP.History[targetChar.Name]
        local vel = hist and hist.Vel or hrp.AssemblyLinearVelocity
        if S._ResolveSmoothVel then
            local sv = S._ResolveSmoothVel(targetChar)
            if sv and sv.Magnitude > 0.5 then vel = vel:Lerp(sv, 0.7) end
        end
        local ping = MSP.Latency + (customPingOffset or 0)
        local pos = part.Position

        if mode == "Standard" then
            return pos + vel * (predAmount / 100)
        elseif mode == "Lag Comp" then
            return pos + vel * ping * (predAmount / 100)
        elseif mode == "Perfect" then
            local acc = hist and hist.Acc or Vector3.new()
            local accMag = acc.Magnitude
            if accMag > 400 then acc = acc * (400 / accMag) end

            local jitter = math.clamp(tonumber(MSP.Jitter) or 0, 0, 0.15)
            local t = (ping + jitter + (1 / 60)) * (predAmount / 100)
            t = math.min(t, 1.5)
            if customBulletSpeed and customBulletSpeed > 0 then
                local shooterHrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                if shooterHrp then
                    local dist = (pos - shooterHrp.Position).Magnitude
                    t = t + (dist / customBulletSpeed)
                end
            end
            local predictedPos = pos + vel * t + 0.5 * acc * t * t

            local hum = targetChar:FindFirstChildOfClass("Humanoid")
            if hum and hum.FloorMaterial == Enum.Material.Air then
                predictedPos = predictedPos - Vector3.new(0, 0.5 * workspace.Gravity * t * t, 0)
            end
            return predictedPos
        elseif mode == "Adaptive" then

            local acc = hist and hist.Acc or Vector3.new()
            local accMag = acc.Magnitude
            if accMag > 400 then acc = acc * (400 / accMag) end
            local jitter = math.clamp(tonumber(MSP.Jitter) or 0, 0, 0.15)
            local t = (ping + jitter + (1 / 60)) * (predAmount / 100)
            t = math.min(t, 1.5)
            if customBulletSpeed and customBulletSpeed > 0 then
                local shooterHrp = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
                if shooterHrp then
                    t = t + ((pos - shooterHrp.Position).Magnitude / customBulletSpeed)
                end
            end
            local predictedPos = pos + vel * t + 0.5 * acc * t * t
            local hum = targetChar:FindFirstChildOfClass("Humanoid")
            if hum and hum.FloorMaterial == Enum.Material.Air then
                predictedPos = predictedPos - Vector3.new(0, 0.5 * workspace.Gravity * t * t, 0)
            end
            return predictedPos
        end
        return pos
    end
end

