do
    pcall(function() workspace.FallenPartsDestroyHeight = -50000 end)

    local function disableKillBricks()
        if not S.AntiKillVoid then return end
        pcall(function()
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj:IsA("BasePart") then
                    local name = string.lower(obj.Name)
                    if name:find("kill") or name:find("lava") or name:find("void") or name:find("death") or name:find("hazard") or name:find("acid") then
                        pcall(function()
                            obj.CanTouch = false
                            obj.CanCollide = false
                        end)
                    end
                end
            end
        end)
    end
    S._DisableKillBricks = disableKillBricks

    local function updateAntiCoin(state)
        pcall(function()
            for _, obj in ipairs(workspace:GetDescendants()) do
                if obj:IsA("BasePart") and (obj.Name:find("Coin") or obj.Name:find("coin") or (obj.Parent and tostring(obj.Parent.Name):find("Coin"))) then
                    pcall(function()
                        obj.CanTouch = not state
                        if state then obj.CanCollide = false end
                    end)
                end
            end
        end)
    end
    S._UpdateAntiCoin = updateAntiCoin

    workspace.DescendantAdded:Connect(function(obj)
        if S.AntiKillVoid and obj:IsA("BasePart") then
            local name = string.lower(obj.Name)
            if name:find("kill") or name:find("lava") or name:find("void") or name:find("death") or name:find("hazard") or name:find("acid") then
                pcall(function()
                    obj.CanTouch = false
                    obj.CanCollide = false
                end)
            end
        end
        if S.AntiCoin and obj:IsA("BasePart") then
            if obj.Name:find("Coin") or obj.Name:find("coin") or (obj.Parent and tostring(obj.Parent.Name):find("Coin")) then
                pcall(function()
                    obj.CanTouch = false
                    obj.CanCollide = false
                end)
            end
        end
    end)

    task.spawn(function()
        while S.Gui and S.Gui.Parent do
            task.wait(1.5)
            if S.Destroyed then break end
            if S.AntiKillVoid then disableKillBricks() end
            if S.AntiCoin then updateAntiCoin(true) end
        end
    end)
end

    local _knifeRef = nil
    local function isKnifeTool(t)
        if not t or not t:IsA("Tool") then return false end
        if t.Name == "Knife" then return true end
        if t:FindFirstChild("KnifeServer") or t:FindFirstChild("KnifeLocal") or t:FindFirstChild("KnifeClient") then return true end
        if t:FindFirstChild("Events") and (t.Events:FindFirstChild("KnifeThrown") or t.Events:FindFirstChild("Slash") or t.Events:FindFirstChild("Stab")) then return true end
        if t:GetAttribute("IsKnife") or t:GetAttribute("WeaponType") == "Knife" then return true end
        return false
    end

    local function findKnife()
        if _knifeRef and _knifeRef.Parent and isKnifeTool(_knifeRef) then return _knifeRef end
        _knifeRef = nil
        local c = LP.Character
        if c then
            for _, item in ipairs(c:GetChildren()) do
                if isKnifeTool(item) then _knifeRef = item; return item end
            end
        end
        if LP.Backpack then
            for _, item in ipairs(LP.Backpack:GetChildren()) do
                if isKnifeTool(item) then _knifeRef = item; return item end
            end
        end
        return nil
    end
    S.findKnife = findKnife

    S._MurdererNearest = function()
        local c = LP.Character
        local me = c and c:FindFirstChild("HumanoidRootPart")
        if not me then return nil end
        local best, bestD = nil, math.huge
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and not isWhitelisted(p) and p.Character then
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                if hrp and hum and hum.Health > 0 then
                    local d = (hrp.Position - me.Position).Magnitude
                    if d < bestD then best, bestD = p.Character, d end
                end
            end
        end
        return best
    end

    local function knifeTargetPos(targetChar)
        local hrp = targetChar:FindFirstChild("HumanoidRootPart")
        if not hrp then return nil end
        local pos = hrp.Position
        if S.SheriffAntiDesync and S._ResolveDesynced and S._ResolveDesynced(targetChar) and S._ResolveAntiDesyncPos then
            local res = S._ResolveAntiDesyncPos(targetChar, hrp)
            if res and res.Magnitude > 0.5 then return res end
        end
        local flight = (S.KnifeFlightSpeedControl and tonumber(S.KnifeFlightSpeed)) or 80
        local pred = getPredictedPosition(targetChar, "HumanoidRootPart", "Perfect", 100, S.KnifePingOffset or 0, flight)
        if pred and pred.Magnitude > 0.5 then return pred end
        return pos
    end

    local function touchKillTarget(knife, targetChar)
        if not knife or not targetChar then return false end
        local knifeHandle = knife:FindFirstChild("Handle") or knife:FindFirstChildWhichIsA("BasePart")
        if not knifeHandle then return false end
        local touchInterestFunc = firetouchinterest or (syn and syn.firetouchinterest)
        if touchInterestFunc then
            local parts = {
                targetChar:FindFirstChild("HumanoidRootPart"),
                targetChar:FindFirstChild("Torso") or targetChar:FindFirstChild("UpperTorso"),
                targetChar:FindFirstChild("Head"),
            }
            for _, part in ipairs(parts) do
                if part and part:IsA("BasePart") then
                    pcall(function()
                        touchInterestFunc(part, knifeHandle, 0)
                        task.wait(0.01)
                        touchInterestFunc(part, knifeHandle, 1)
                    end)
                end
            end
            return true
        end
        return false
    end

    S._MurdererKill = function(targetChar)
        if not targetChar or not targetChar.Parent then return false end
        local knife = findKnife()
        if not knife then return false end
        local pos = knifeTargetPos(targetChar)
        if not pos then return false end
        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
        if hum and knife.Parent ~= LP.Character then
            pcall(function() hum:EquipTool(knife) end)
            task.wait(0.05)
            knife = findKnife()
        end
        if not knife then return false end

        touchKillTarget(knife, targetChar)

        local evs = knife:FindFirstChild("Events")
        local handle = knife:FindFirstChild("Handle") or (LP.Character and LP.Character:FindFirstChild("HumanoidRootPart"))
        local originPos = handle and handle.Position or (LP.Character and LP.Character.HumanoidRootPart.Position) or pos
        local originCFrame = CFrame.lookAt(originPos, pos)

        if evs then
            local slashEv = evs:FindFirstChild("Slash") or evs:FindFirstChild("Stab")
            if slashEv then pcall(function() slashEv:FireServer(pos) end) end
            local throwEv = evs:FindFirstChild("KnifeThrown")
            if throwEv then pcall(function() throwEv:FireServer(originCFrame, CFrame.new(pos)) end) end
        end

        pcall(function() knife:Activate() end)
        return true
    end

    S._MurdererKillAll = function()
        local killed = 0
        local knife = findKnife()
        local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
        if hum and knife and knife.Parent ~= LP.Character then
            pcall(function() hum:EquipTool(knife) end)
            task.wait(0.05)
        end
        for _, p in ipairs(Players:GetPlayers()) do
            if p ~= LP and not isWhitelisted(p) and p.Character then
                local h = p.Character:FindFirstChildOfClass("Humanoid")
                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                if h and h.Health > 0 and hrp then
                    if S._MurdererKill(p.Character) then killed = killed + 1 end
                    task.wait(0.06)
                end
            end
        end
        return killed
    end

    S._ReapplyThrowSpeed = function()
        local knife = findKnife()
        if not knife then return end
        local ts = 1
        if S.KnifeThrowSpeedControl and S.KnifeThrowWindup then
            ts = math.max(S.KnifeThrowWindup, 0.05)
        elseif S.FastThrow then
            ts = 0.08
        elseif S.NoKnifeAnim then
            ts = 0.2
        end
        pcall(function() knife:SetAttribute("ThrowSpeed", ts) end)
    end

    S._ReapplyKnifeFlightSpeed = function()
        local knife = findKnife()
        if knife and S.KnifeFlightSpeedControl then
            pcall(function() knife:SetAttribute("FlightSpeed", tonumber(S.KnifeFlightSpeed) or 100) end)
        end
    end

    local function hookCharacterAnim(char)
        if not char then return end
        local hum = char:WaitForChild("Humanoid", 3)
        if not hum then return end
        hum.AnimationPlayed:Connect(function(track)
            if (S.FastThrow or S.NoKnifeAnim or S.KnifeThrowSpeedControl) and track and track.Animation then
                local animName = tostring(track.Animation.Name):lower()
                local animId = tostring(track.Animation.AnimationId):lower()
                if animName:find("throw") or animName:find("knife") or animId:find("throw") or animId:find("slash") then
                    if S.NoKnifeAnim then
                        pcall(function() track:Stop(0) end)
                    elseif S.FastThrow then
                        pcall(function() track:AdjustSpeed(25) end)
                    elseif S.KnifeThrowSpeedControl and S.KnifeThrowWindup then
                        local speedMult = math.clamp(1 / math.max(S.KnifeThrowWindup, 0.05), 1, 30)
                        pcall(function() track:AdjustSpeed(speedMult) end)
                    end
                end
            end
        end)
    end
    if LP.Character then hookCharacterAnim(LP.Character) end
    LP.CharacterAdded:Connect(hookCharacterAnim)

    UIS.InputBegan:Connect(function(input, gp)
        if gp then return end
        if input.KeyCode == Enum.KeyCode.E and S.FastThrow then
            local knife = findKnife()
            if knife and knife.Parent == LP.Character then
                local throwEv = knife:FindFirstChild("Events") and knife.Events:FindFirstChild("KnifeThrown")
                if throwEv then
                    local cam = workspace.CurrentCamera
                    local mouse = LP:GetMouse()
                    local targetPos = (mouse and mouse.Hit and mouse.Hit.Position) or (cam and cam.CFrame.Position + cam.CFrame.LookVector * 100)
                    local handle = knife:FindFirstChild("Handle") or (LP.Character and LP.Character:FindFirstChild("HumanoidRootPart"))
                    local origin = handle and handle.CFrame or (cam and cam.CFrame) or CFrame.new()
                    pcall(function()
                        throwEv:FireServer(CFrame.lookAt(origin.Position, targetPos), CFrame.new(targetPos))
                    end)
                end
            end
        end
    end)

    task.spawn(function()
        local lastAutoKill, lastClickKill = 0, 0
        while S.Gui and S.Gui.Parent do
            task.wait(0.1)
            if S.Destroyed then break end
            pcall(function()
                local role = S.getRole and S.getRole(LP)
                local isMurderer = role == "Murderer"
                local knife = isMurderer and findKnife()
                local c = LP.Character
                local me = c and c:FindFirstChild("HumanoidRootPart")
                if isMurderer and knife and me then
                    if S.KillAura then
                        local range = S.KillAuraRange or 18
                        for _, p in ipairs(Players:GetPlayers()) do
                            if p ~= LP and not isWhitelisted(p) and p.Character then
                                local hrp = p.Character:FindFirstChild("HumanoidRootPart")
                                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                                if hrp and hum and hum.Health > 0 and (hrp.Position - me.Position).Magnitude <= range then
                                    S._MurdererKill(p.Character)
                                    task.wait(0.05)
                                end
                            end
                        end
                    end
                    local autoTarget = nil
                    if S.AutoKillSheriff then
                        for _, p in ipairs(Players:GetPlayers()) do
                            if p ~= LP and not isWhitelisted(p) and p.Character then
                                local r = S.getRole and S.getRole(p)
                                local hum = p.Character:FindFirstChildOfClass("Humanoid")
                                if (r == "Sheriff" or r == "Hero") and hum and hum.Health > 0 then
                                    autoTarget = p.Character
                                    break
                                end
                            end
                        end
                    elseif S.AutoKillNearest then
                        autoTarget = S._MurdererNearest()
                    end
                    if autoTarget and tick() - lastAutoKill >= 1.1 then
                        if S._MurdererKill(autoTarget) then lastAutoKill = tick() end
                    end
                    if S.ClickKill and UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) and tick() - lastClickKill >= 0.35 then
                        local n = S._MurdererNearest()
                        if n then S._MurdererKill(n); lastClickKill = tick() end
                    end
                end
            end)
        end
    end)
end
