    local fakeLagTicks = 0
    task.spawn(function()
        tc(RunService.Heartbeat:Connect(function()
            if S.FakeLag then
                local c = LP.Character
                local hrp = c and c:FindFirstChild("HumanoidRootPart")
                if hrp then
                    fakeLagTicks = fakeLagTicks + 1
                    local limit = S.FakeLagLimit or 15
                    if fakeLagTicks >= limit then
                        S._SetOwnedAnchored(hrp, false)
                        fakeLagTicks = 0
                    else
                        S._SetOwnedAnchored(hrp, true)
                    end
                end
            else
                fakeLagTicks = 0
                local c = LP.Character
                local hrp = c and c:FindFirstChild("HumanoidRootPart")
                if hrp then S._RestoreOwnedAnchored(hrp) end
            end
        end))
    end)

