local pinnedEmotesGrid = Instance.new("UIGridLayout")
pinnedEmotesGrid.CellSize = UDim2.fromOffset(58, 66)
pinnedEmotesGrid.CellPadding = UDim2.fromOffset(6, 6)
pinnedEmotesGrid.HorizontalAlignment = Enum.HorizontalAlignment.Center
pinnedEmotesGrid.VerticalAlignment = Enum.VerticalAlignment.Top
pinnedEmotesGrid.SortOrder = Enum.SortOrder.LayoutOrder
pinnedEmotesGrid.Parent = HUD.hPinnedEmotes.content
local function fitPinnedEmotesHUD()
    local count = 0
    for _, child in ipairs(HUD.hPinnedEmotes.content:GetChildren()) do
        if child:IsA("ImageButton") and child:GetAttribute("Removing") ~= true then count = count + 1 end
    end
    local columns = math.clamp(count, 1, 4)
    local rows = math.max(1, math.ceil(math.max(count, 1) / columns))
    pinnedEmotesGrid.FillDirectionMaxCells = columns
    local gridWidth = columns * 58 + math.max(0, columns - 1) * 6
    local gridHeight = rows * 66 + math.max(0, rows - 1) * 6
    local frameWidth = math.max(130, gridWidth + 20)
    local targetPosition = UDim2.new(0.5, -gridWidth / 2, 0, 37)
    local targetContentSize = UDim2.fromOffset(gridWidth, gridHeight)
    local targetFrameSize = UDim2.fromOffset(frameWidth, gridHeight + 47)
    HUD.pinnedCount.Text = tostring(count)
    HUD.hPinnedEmotes.content.AutomaticSize = Enum.AutomaticSize.None
    HUD.hPinnedEmotes.frame.AutomaticSize = Enum.AutomaticSize.None
    if HUD.hPinnedEmotes.frame.Visible then
        if S._PinnedSizeTween then pcall(function() S._PinnedSizeTween:Cancel() end) end
        S._PinnedSizeTween = TweenService:Create(HUD.hPinnedEmotes.frame, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { Size = targetFrameSize })
        S._PinnedSizeTween:Play()
        TweenService:Create(HUD.hPinnedEmotes.content, TweenInfo.new(0.22, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
            Position = targetPosition,
            Size = targetContentSize
        }):Play()
    else
        HUD.hPinnedEmotes.content.Position = targetPosition
        HUD.hPinnedEmotes.content.Size = targetContentSize
        HUD.hPinnedEmotes.frame.Size = targetFrameSize
    end
end
tc(pinnedEmotesGrid:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(fitPinnedEmotesHUD))
task.defer(fitPinnedEmotesHUD)

do
    local mgFrame = Instance.new("Frame")
    mgFrame.Name = "HUD_Motion Graph"
    mgFrame.Parent = SG
    mgFrame.Active = true
    mgFrame.Position = UDim2.new(0, 10, 0, 590)
    mgFrame.Size = UDim2.fromOffset(MOBILE and 300 or 340, 20)
    mgFrame.BackgroundTransparency = 1
    mgFrame.BorderSizePixel = 0
    mgFrame.Visible = false
    mgFrame.ZIndex = 858
    attachHUDDrag(mgFrame, mgFrame)

    local line = Instance.new("TextLabel")
    line.Name = "Line"
    line.Parent = mgFrame
    line.BackgroundTransparency = 1
    line.Size = UDim2.new(1, 0, 1, 0)
    line.Font = FB
    line.TextSize = MOBILE and 11 or 13
    line.TextColor3 = T.Tx
    line.TextXAlignment = Enum.TextXAlignment.Left
    line.Text = "SPD 0.0 \194\183 AVG 0.0 \194\183 PEAK 0.0"
    line.ZIndex = 859
    line.RichText = true
    pcall(function() line:SetAttribute("ThemeColorRole_TextColor3", "Tx") end)
    pcall(function() line:SetAttribute("MinReadableTextSize", MOBILE and 9 or 10) end)

    HUDEls["Motion Graph"] = { frame = mgFrame, content = mgFrame }

    local smoothed, peakSpeed, elapsed = 0, 0, 0
    local maxSpeed = 40
    local samples = MOBILE and 30 or 45
    local history = table.create(samples, 0)

    tc(RunService.Heartbeat:Connect(function(dt)
        local el = HUDEls["Motion Graph"]
        if not el or not el.frame.Visible then return end
        elapsed = elapsed + dt
        local refresh = math.clamp(tonumber(S.MGRefresh) or 30, 10, MOBILE and 30 or 60)
        local interval = 1 / refresh
        if elapsed < interval then return end
        local sampleDt = math.clamp(elapsed, interval, 0.25)
        elapsed = 0

        local char = LP.Character
        local root = char and char:FindFirstChild("HumanoidRootPart")
        local raw = 0
        if root then
            local velocity = root.AssemblyLinearVelocity
            raw = Vector2.new(velocity.X, velocity.Z).Magnitude
        end
        local smooth = math.clamp(tonumber(S.MGSmoothing) or 62, 0, 95) / 100
        local response = 1 - math.pow(smooth, sampleDt * 30)
        smoothed = smoothed + (raw - smoothed) * math.clamp(response, 0.001, 1)
        table.remove(history, 1)
        history[samples] = smoothed
        peakSpeed = math.max(peakSpeed * math.pow(0.997, sampleDt * 30), smoothed)
        maxSpeed = math.max(20, maxSpeed * math.pow(0.982, sampleDt * 30), smoothed * 1.22)

        local total = 0
        for i = 1, samples do total = total + history[i] end
        local average = total / samples
        line.Text = string.format(
            '<font color="#ffffff">SPD %.1f</font>  <font color="#71717a">\194\183</font>  <font color="#a1a1aa">AVG %.1f</font>  <font color="#71717a">\194\183</font>  <font color="#a1a1aa">PEAK %.1f</font>',
            smoothed, average, peakSpeed
        )
    end))

    local secMG = mkSection(Pages.Visuals, "Motion Graph", 13, true)
    if S._RegisterVisualsCustomsSection then pcall(S._RegisterVisualsCustomsSection, secMG) end
    mkToggle(secMG, "Motion Graph Line", false, function(v)
        S.HUD_MotionGraph = v
        S._SetHUDVisible(HUDEls["Motion Graph"], v)
    end, 1)
    mkSlider(secMG, "Smoothing", 0, 95, 62, function(v) S.MGSmoothing = v end, 2)
    mkSlider(secMG, "Refresh Rate", 10, MOBILE and 30 or 60, 30, function(v) S.MGRefresh = v end, 3)
end
end

