local Lighting = game:GetService("Lighting")
local savedLighting = {}
local function saveLighting()
    if savedLighting.done then return end
    savedLighting.Brightness = Lighting.Brightness
    savedLighting.ClockTime = Lighting.ClockTime
    savedLighting.FogColor = Lighting.FogColor
    savedLighting.FogStart = Lighting.FogStart
    savedLighting.FogEnd = Lighting.FogEnd
    savedLighting.GlobalShadows = Lighting.GlobalShadows
    savedLighting.Ambient = Lighting.Ambient
    savedLighting.OutdoorAmbient = Lighting.OutdoorAmbient

    pcall(function()
        savedLighting.ExposureCompensation = Lighting.ExposureCompensation
        savedLighting.EnvironmentDiffuseScale = Lighting.EnvironmentDiffuseScale
        savedLighting.EnvironmentSpecularScale = Lighting.EnvironmentSpecularScale
        savedLighting.ShadowSoftness = Lighting.ShadowSoftness
    end)
    savedLighting.done = true
end

local function restoreLighting()
    if not savedLighting.done then return end
    Lighting.Brightness = savedLighting.Brightness
    Lighting.ClockTime = savedLighting.ClockTime
    Lighting.FogColor = savedLighting.FogColor
    Lighting.FogStart = savedLighting.FogStart
    Lighting.FogEnd = savedLighting.FogEnd
    Lighting.GlobalShadows = savedLighting.GlobalShadows
    Lighting.Ambient = savedLighting.Ambient
    Lighting.OutdoorAmbient = savedLighting.OutdoorAmbient
    pcall(function()
        Lighting.ExposureCompensation = savedLighting.ExposureCompensation
        Lighting.EnvironmentDiffuseScale = savedLighting.EnvironmentDiffuseScale
        Lighting.EnvironmentSpecularScale = savedLighting.EnvironmentSpecularScale
        Lighting.ShadowSoftness = savedLighting.ShadowSoftness
    end)
end

saveLighting()

local shaderEffects = {}
local function clearShaderEffects()
    for _, eff in ipairs(shaderEffects) do
        pcall(function() eff:Destroy() end)
    end
    shaderEffects = {}
    S._ultraFX = nil
end

local applyAtmo

S._ApplySimpleShader = function(name)
    if name ~= "Custom" then return false end
    local quality = S.ShaderQuality or "Balanced"
    local qualityScale = quality == "Performance" and 0.7 or quality == "Cinematic" and 1.25 or 1
    if MOBILE then qualityScale = math.min(qualityScale, 0.85) end

    local function n(key, default, lo, hi)
        return math.clamp((tonumber(S[key]) or default) / 100, lo, hi)
    end
    local function rgb(prefix, fallback)
        return Color3.fromRGB(
            math.clamp(tonumber(S[prefix .. "R"]) or fallback[1], 0, 255),
            math.clamp(tonumber(S[prefix .. "G"]) or fallback[2], 0, 255),
            math.clamp(tonumber(S[prefix .. "B"]) or fallback[3], 0, 255)
        )
    end

    -- 1. Lighting properties
    if S.ShaderLightingEnabled ~= false then
        Lighting.ClockTime = math.clamp(tonumber(S.ShaderTime) or 14, 0, 24)
        Lighting.Brightness = math.clamp((tonumber(S.ShaderBrightness) or 200) / 100, 0.1, 8.0)
        Lighting.Ambient = rgb("ShaderAmbient", { 96, 100, 110 })
        Lighting.OutdoorAmbient = rgb("ShaderOutdoor", { 140, 146, 160 })
        Lighting.GlobalShadows = S.ShaderShadows ~= false
        pcall(function()
            Lighting.ExposureCompensation = math.clamp((tonumber(S.ShaderExposure) or 4) / 100, -2.5, 2.5)
            Lighting.EnvironmentDiffuseScale = math.clamp((tonumber(S.ShaderDiffuse) or 100) / 100, 0, 1)
            Lighting.EnvironmentSpecularScale = math.clamp((tonumber(S.ShaderSpecular) or 100) / 100, 0, 1)
            Lighting.ShadowSoftness = math.clamp((tonumber(S.ShaderShadowSoftness) or 55) / 100, 0, 1)
        end)
    elseif savedLighting.done then
        Lighting.ClockTime = savedLighting.ClockTime
        Lighting.Brightness = savedLighting.Brightness
        Lighting.Ambient = savedLighting.Ambient
        Lighting.OutdoorAmbient = savedLighting.OutdoorAmbient
        Lighting.GlobalShadows = savedLighting.GlobalShadows
        pcall(function()
            Lighting.ExposureCompensation = savedLighting.ExposureCompensation or 0
            Lighting.EnvironmentDiffuseScale = savedLighting.EnvironmentDiffuseScale or 1
            Lighting.EnvironmentSpecularScale = savedLighting.EnvironmentSpecularScale or 1
            Lighting.ShadowSoftness = savedLighting.ShadowSoftness or 0.5
        end)
    end

    -- 2. Bloom effect
    local bloomPower = tonumber(S.ShaderBloom) or 40
    if S.ShaderBloomEnabled ~= false and bloomPower > 0 then
        local bloom = Instance.new("BloomEffect")
        bloom.Name = "InertiaCustomBloom"
        bloom.Intensity = math.clamp((bloomPower / 100) * 1.5 * qualityScale, 0.05, 5.0)
        bloom.Size = math.clamp((tonumber(S.ShaderBloomSize) or 24) * qualityScale, 1, 56)
        bloom.Threshold = math.clamp((tonumber(S.ShaderBloomThreshold) or 155) / 100, 0, 4.0)
        bloom.Parent = Lighting
        table.insert(shaderEffects, bloom)
    end

    -- 3. SunRays effect
    local sunPower = tonumber(S.ShaderSunRays) or 8
    if S.ShaderSunEnabled ~= false and sunPower > 0 then
        local sun = Instance.new("SunRaysEffect")
        sun.Name = "InertiaCustomSunRays"
        sun.Intensity = math.clamp((sunPower / 100) * 0.45 * qualityScale, 0.01, 1.0)
        sun.Spread = math.clamp((tonumber(S.ShaderSunSpread) or 68) / 100, 0.05, 1.0)
        sun.Parent = Lighting
        table.insert(shaderEffects, sun)
    end

    -- 4. DepthOfField effect
    if S.ShaderDOFEnabled == true and quality ~= "Performance" then
        local dofPower = tonumber(S.ShaderDOF) or 0
        local powerMul = dofPower > 0 and (dofPower / 100) or 0.75
        local nearVal = tonumber(S.ShaderDOFNear) or 10
        local farVal = tonumber(S.ShaderDOFFar) or 8
        local nearIntensity = (nearVal > 0 and (nearVal / 100) or 0.4) * powerMul * qualityScale
        local farIntensity = (farVal > 0 and (farVal / 100) or 0.35) * powerMul * qualityScale

        local dof = Instance.new("DepthOfFieldEffect")
        dof.Name = "InertiaCustomDepth"
        dof.FarIntensity = math.clamp(farIntensity, 0.02, 1.0)
        dof.NearIntensity = math.clamp(nearIntensity, 0.02, 1.0)
        dof.FocusDistance = math.clamp(tonumber(S.ShaderDOFFocus) or 45, 0, 500)
        dof.InFocusRadius = math.clamp(tonumber(S.ShaderDOFRadius) or 70, 0, 500)
        dof.Parent = Lighting
        table.insert(shaderEffects, dof)
    end

    -- 5. BlurEffect
    if S.ShaderBlurEnabled == true and quality ~= "Performance" then
        local blurVal = tonumber(S.ShaderBlur) or 0
        local blurSize = blurVal > 0 and blurVal or 6
        local blur = Instance.new("BlurEffect")
        blur.Name = "InertiaCustomBlur"
        blur.Size = math.clamp(blurSize * qualityScale, 1, 56)
        blur.Parent = Lighting
        table.insert(shaderEffects, blur)
    end

    -- 6. ColorCorrection (Color Grading)
    if S.ShaderCCEnabled ~= false then
        local tintName = S.ShaderTint or "Neutral"
        local cc = Instance.new("ColorCorrectionEffect")
        cc.Name = "InertiaCustomColor"
        cc.Brightness = math.clamp((tonumber(S.ShaderCCBright) or 0) / 100, -1.0, 1.0)
        cc.Contrast = math.clamp((tonumber(S.ShaderContrast) or 12) / 100, -1.0, 1.0)
        cc.Saturation = tintName == "Mono" and -1 or math.clamp((tonumber(S.ShaderSaturation) or 18) / 100, -1.0, 3.0)
        cc.TintColor = tintName == "Custom"
            and rgb("ShaderTint", { 255, 255, 255 })
            or (S._TINT_RGB and S._TINT_RGB[tintName] or (S._TINT_RGB and S._TINT_RGB.Neutral or Color3.new(1, 1, 1)))
        cc.Parent = Lighting
        table.insert(shaderEffects, cc)
    end

    return true
end

S._LiveShaders = {
    ["RTX Low"] = true, ["RTX Medium"] = true, ["RTX High"] = true, ["RTX Ultra"] = true,
    ["Night Shaders"] = true, ["Pink Shaders"] = true, ["Custom"] = true,
}
applyShader = function(name)
    saveLighting()
    clearShaderEffects()
    if name ~= "None" and not S._LiveShaders[name] then name = "None" end

    if name == "None" then
        S.ActiveShader = "None"
        restoreLighting()
        if applyAtmo then pcall(applyAtmo) end
        return
    end

    S.ActiveShader = name
    pcall(function() Lighting.ExposureCompensation = 0 end)
    if S._ApplySimpleShader and S._ApplySimpleShader(name) then
        if applyAtmo then pcall(applyAtmo) end
        return
    end

    if name == "RTX Low" then

        Lighting.ClockTime = 14
        Lighting.Brightness = 2.0
        Lighting.GlobalShadows = true
        Lighting.Ambient = Color3.fromRGB(84, 88, 98)
        Lighting.OutdoorAmbient = Color3.fromRGB(126, 132, 144)
        pcall(function() Lighting.ExposureCompensation = 0.04 end)
        pcall(function()
            Lighting.EnvironmentDiffuseScale = 0.6
            Lighting.EnvironmentSpecularScale = 0.5
            Lighting.ShadowSoftness = 0.3
        end)

        local bloom = Instance.new("BloomEffect")
        bloom.Intensity = 0.4
        bloom.Size = 20
        bloom.Threshold = 1.75
        bloom.Parent = Lighting
        table.insert(shaderEffects, bloom)

