        })
        add("Blue Hour", "Cinematic", {
            ShaderTime = 18.4, ShaderBrightness = 120, ShaderSaturation = 10, ShaderContrast = 18,
            ShaderTint = "Cool",
        })
    end

    local SKY_PRESETS = {
        Day    = {clock=14.0, atmColor=Color3.fromRGB(190,210,235), decay=Color3.fromRGB(90,140,220),  glare=0.20, haze=1.4, density=0.30, ambient=Color3.fromRGB(120,128,140), outdoor=Color3.fromRGB(150,160,175)},
        Sunset = {clock=17.6, atmColor=Color3.fromRGB(255,150,90),  decay=Color3.fromRGB(255,110,70),  glare=0.55, haze=2.4, density=0.36, ambient=Color3.fromRGB(150,100,80),  outdoor=Color3.fromRGB(230,150,110)},
        Night  = {clock=0.0,  atmColor=Color3.fromRGB(40,55,110),   decay=Color3.fromRGB(14,20,55),    glare=0.00, haze=2.0, density=0.40, ambient=Color3.fromRGB(30,38,70),    outdoor=Color3.fromRGB(45,55,95)},
        Aurora = {clock=1.0,  atmColor=Color3.fromRGB(60,200,170),  decay=Color3.fromRGB(80,60,205),   glare=0.35, haze=2.6, density=0.44, ambient=Color3.fromRGB(50,90,90),    outdoor=Color3.fromRGB(80,140,140)},
        Space  = {clock=0.0,  atmColor=Color3.fromRGB(30,15,55),    decay=Color3.fromRGB(60,25,95),    glare=0.00, haze=0.6, density=0.18, ambient=Color3.fromRGB(30,25,50),    outdoor=Color3.fromRGB(45,40,75)},
        Blood  = {clock=17.2, atmColor=Color3.fromRGB(180,40,40),   decay=Color3.fromRGB(90,12,16),    glare=0.45, haze=2.8, density=0.44, ambient=Color3.fromRGB(90,35,35),    outdoor=Color3.fromRGB(150,60,55)},
        Toxic  = {clock=9.0,  atmColor=Color3.fromRGB(150,220,70),  decay=Color3.fromRGB(70,150,35),   glare=0.35, haze=2.8, density=0.44, ambient=Color3.fromRGB(80,110,45),   outdoor=Color3.fromRGB(120,170,70)},
        Ocean  = {clock=12.0, atmColor=Color3.fromRGB(90,180,220),  decay=Color3.fromRGB(30,95,155),   glare=0.30, haze=2.0, density=0.40, ambient=Color3.fromRGB(60,100,120),  outdoor=Color3.fromRGB(90,150,180)},
        Sakura = {clock=15.5, atmColor=Color3.fromRGB(255,185,210), decay=Color3.fromRGB(235,120,170), glare=0.30, haze=2.2, density=0.36, ambient=Color3.fromRGB(150,110,125), outdoor=Color3.fromRGB(230,170,190)},
        Midnight={clock=0.0, atmColor=Color3.fromRGB(70,40,130),    decay=Color3.fromRGB(30,12,70),    glare=0.00, haze=2.2, density=0.42, ambient=Color3.fromRGB(45,32,75),    outdoor=Color3.fromRGB(70,50,110)},
        Storm  = {clock=11.0, atmColor=Color3.fromRGB(105,112,125), decay=Color3.fromRGB(55,60,75),    glare=0.00, haze=3.0, density=0.48, ambient=Color3.fromRGB(75,80,90),    outdoor=Color3.fromRGB(105,112,125)},
        Desert = {clock=13.5, atmColor=Color3.fromRGB(235,200,140), decay=Color3.fromRGB(200,150,90),  glare=0.45, haze=2.6, density=0.38, ambient=Color3.fromRGB(140,120,90),  outdoor=Color3.fromRGB(210,180,130)},
    }

    local SKY_TINTS = {
        Blue   = Color3.fromRGB(60,120,235), Purple = Color3.fromRGB(150,80,225),
        Pink   = Color3.fromRGB(240,110,190), Cyan   = Color3.fromRGB(60,205,220),
        Orange = Color3.fromRGB(240,140,55),  Green  = Color3.fromRGB(70,190,80),
        Red    = Color3.fromRGB(220,55,55),   White  = Color3.fromRGB(220,224,235),
    }
    local FOG_COLORS = {
        Gray  = Color3.fromRGB(150,150,158), White = Color3.fromRGB(236,236,242), Black = Color3.fromRGB(14,14,20),
        Blue  = Color3.fromRGB(70,120,200),  Purple= Color3.fromRGB(140,80,200),  Pink  = Color3.fromRGB(235,120,185),
        Cyan  = Color3.fromRGB(90,200,215),  Orange= Color3.fromRGB(235,150,70),  Green = Color3.fromRGB(90,190,90),
        Red   = Color3.fromRGB(210,70,65),
    }

    local ATMO_NAME = "MM2_Atmo"
    local atmoRef
    local mapAtmoParked
    local removedSky
    local savedFog

    local function getAtmo()
        if atmoRef and atmoRef.Parent then return atmoRef end
        atmoRef = Lighting:FindFirstChild(ATMO_NAME)
        if not atmoRef then
            atmoRef = Instance.new("Atmosphere")
            atmoRef.Name = ATMO_NAME
        end
        atmoRef.Parent = Lighting
        return atmoRef
    end
    local function clearAtmo()
        if atmoRef then pcall(function() atmoRef:Destroy() end); atmoRef = nil end
    end

    local function parkMapAtmo(on)
        if on then
            if not mapAtmoParked then
                local a = Lighting:FindFirstChildOfClass("Atmosphere")
                if a and a.Name ~= ATMO_NAME then mapAtmoParked = a; a.Parent = nil end
            end
        elseif mapAtmoParked then
            pcall(function() mapAtmoParked.Parent = Lighting end)
            mapAtmoParked = nil
        end
    end

    local function removeSky(on)
        if on then
            if not removedSky then
                local sk = Lighting:FindFirstChildOfClass("Sky")
                if sk then removedSky = sk; sk.Parent = nil end
            end
        elseif removedSky then
            pcall(function() removedSky.Parent = Lighting end)
            removedSky = nil
        end
    end
    local function saveFog()
        if not savedFog then savedFog = {c = Lighting.FogColor, s = Lighting.FogStart, e = Lighting.FogEnd} end
    end
    local function restoreFog()
        if savedFog then
            pcall(function()
                Lighting.FogColor = savedFog.c
                Lighting.FogStart = savedFog.s
                Lighting.FogEnd   = savedFog.e
            end)
            savedFog = nil
        end
    end

    local skyHue, fogHue = 0, 0

    applyAtmo = function()
        pcall(function()
            skyHue = (skyHue + 0.006) % 1
            fogHue = (fogHue + 0.004 * math.clamp((tonumber(S.FogRainbowSpeed) or 100) / 100, 0.05, 5)) % 1
            local shaderBase = SHADER_ATMO[S.ActiveShader]

            local libraryProfile = S._ShaderLibrary and S._ShaderLibrary.Profiles
                and S._ShaderLibrary.Profiles[S.ActiveShader]
            local forceProfile = (S.ActiveShader == "ForceDay" or S.ActiveShader == "ForceNight")
                and libraryProfile or nil
            if S.ActiveShader == "Custom" or libraryProfile then
                if S.ShaderAtmoEnabled == false then
                    shaderBase = nil
                else
                    local density = math.clamp((tonumber(S.ShaderAtmo) or 22) / 100, 0, MOBILE and 0.48 or 0.75)
                    local haze = math.clamp((tonumber(S.ShaderAtmoHaze) or 160) / 100, 0, MOBILE and 4.5 or 10)
                    shaderBase = {
                        density = density,
                        offset = math.clamp((tonumber(S.ShaderAtmoOffset) or 20) / 100, -1, 1),
                        color = Color3.fromRGB(
                            math.clamp(tonumber(S.ShaderAtmoR) or 210, 0, 255),
                            math.clamp(tonumber(S.ShaderAtmoG) or 214, 0, 255),
                            math.clamp(tonumber(S.ShaderAtmoB) or 222, 0, 255)),
                        decay = Color3.fromRGB(
                            math.clamp(tonumber(S.ShaderDecayR) or 120, 0, 255),
                            math.clamp(tonumber(S.ShaderDecayG) or 142, 0, 255),
                            math.clamp(tonumber(S.ShaderDecayB) or 190, 0, 255)),
                        glare = math.clamp((tonumber(S.ShaderAtmoGlare) or 15) / 100, 0, 10),
                        haze = haze,
                    }
                end
            end

            local classicFog = S.FogEnabled and S.FogMode ~= "Atmosphere"
            local atmoFog    = S.FogEnabled and S.FogMode == "Atmosphere"

            local fogColor
            if S.FogColorName == "Custom" then
                fogColor = Color3.fromRGB(
                    math.clamp(tonumber(S.FogR) or 150, 0, 255),
                    math.clamp(tonumber(S.FogG) or 150, 0, 255),
                    math.clamp(tonumber(S.FogB) or 158, 0, 255))
            else
                fogColor = FOG_COLORS[S.FogColorName] or FOG_COLORS.Gray
            end
            if S.FogRainbow and S.FogEnabled then
                fogColor = Color3.fromHSV(fogHue,
                    math.clamp((tonumber(S.FogRainbowSat) or 55) / 100, 0, 1), 0.85)
            end

            local needOwnAtmo = atmoFog or ((not classicFog) and (S.SkyEnabled or shaderBase ~= nil))

            parkMapAtmo(needOwnAtmo or classicFog)

            if classicFog then
                saveFog()
                clearAtmo()
                local fs = S.FogStart or 0
                Lighting.FogColor = fogColor
                Lighting.FogStart = fs
                Lighting.FogEnd   = math.max(fs + 1, S.FogEnd or 500)
            else
                restoreFog()
            end

            if S.SkyEnabled then
                local p = SKY_PRESETS[S.SkyPreset] or SKY_PRESETS.Day
                removeSky(true)
                Lighting.ClockTime = p.clock
                Lighting.Ambient = p.ambient
                Lighting.OutdoorAmbient = p.outdoor
            else
                removeSky(false)
            end
            if forceProfile then
                Lighting.ClockTime = math.clamp(tonumber(S.ShaderTime) or forceProfile.ShaderTime or 14, 0, 24)
                if S.ShaderLightingEnabled ~= false then
                    Lighting.Ambient = Color3.fromRGB(
                        math.clamp(tonumber(S.ShaderAmbientR) or 96, 0, 255),
                        math.clamp(tonumber(S.ShaderAmbientG) or 100, 0, 255),
                        math.clamp(tonumber(S.ShaderAmbientB) or 110, 0, 255))
                    Lighting.OutdoorAmbient = Color3.fromRGB(
                        math.clamp(tonumber(S.ShaderOutdoorR) or 140, 0, 255),
                        math.clamp(tonumber(S.ShaderOutdoorG) or 146, 0, 255),
                        math.clamp(tonumber(S.ShaderOutdoorB) or 160, 0, 255))
                end
            end

            if needOwnAtmo then
                local a = getAtmo()
                if atmoFog then

                    local d = math.clamp((S.FogDensity or 40) / 100, 0.02, 0.95)
                    local h, sat, val = fogColor:ToHSV()
                    a.Density = d
                    a.Color   = fogColor
                    if S.FogAuto == false then
                        a.Offset = math.clamp((tonumber(S.FogOffset) or 20) / 100, 0, 1)
                        a.Glare  = math.clamp((tonumber(S.FogGlare) or 24) / 100, 0, 1) * 10
                        a.Haze   = math.clamp((tonumber(S.FogHaze) or 40) / 100, 0, 1) * 10
                        local depth = math.clamp((tonumber(S.FogDepth) or 35) / 100, 0, 1)
                        a.Decay = Color3.fromHSV(h, math.max(0, sat - depth * 0.5), math.max(0, val - depth))
                    else
                        a.Offset = 0.2
                        a.Glare  = d * 0.6
                        a.Haze   = 1.2 + d * 2.0
                        a.Decay  = Color3.fromHSV(h, math.max(0, sat - 0.15), math.max(0, val - 0.35))
                    end
                elseif S.SkyEnabled and (not forceProfile or shaderBase == nil) then
                    local p = SKY_PRESETS[S.SkyPreset] or SKY_PRESETS.Day
                    a.Density = p.density
                    a.Offset  = 0.25
                    a.Glare   = p.glare
                    a.Haze    = p.haze
                    a.Color   = p.atmColor
                    local decay = p.decay
                    if S.SkyRainbow then decay = Color3.fromHSV(skyHue, 0.7, 0.85)
                    elseif SKY_TINTS[S.SkyTint] then decay = SKY_TINTS[S.SkyTint] end
                    a.Decay = decay
                else
                    a.Density = shaderBase.density
                    a.Offset  = shaderBase.offset
                    a.Color   = shaderBase.color
                    a.Decay   = shaderBase.decay
                    a.Glare   = shaderBase.glare
                    a.Haze    = shaderBase.haze
                end
            elseif not classicFog then
                clearAtmo()
            end
        end)
    end

    S._ApplyEnvironment = applyAtmo

    tt(function()
        while S.Gui and S.Gui.Parent do
            applyAtmo()
            task.wait(0.1)
        end
    end)

    cleanup(function()
        pcall(function() parkMapAtmo(false) end)
        pcall(function() removeSky(false) end)
        pcall(clearAtmo)
        pcall(restoreFog)
    end)
end


do
    local RS = game:GetService("ReplicatedStorage")
    local catalogContainer, catalogCount = nil, 0
    local appliedEffectObjects, appliedEffectId = {}, nil

    local function clearLegacyAura(char)
        if not char then return end
        for _, obj in ipairs(char:GetDescendants()) do
            if string.sub(obj.Name or "", 1, 7) == "MM2_FX_" then
                pcall(function() obj:Destroy() end)
            end
        end
    end

    local function clearAppliedKnifeEffect()
        for _, obj in ipairs(appliedEffectObjects) do
            if obj and obj.Parent then pcall(function() obj:Destroy() end) end
        end
        table.clear(appliedEffectObjects)
        appliedEffectId = nil
        clearLegacyAura(LP.Character)
        local bp = LP:FindFirstChildOfClass("Backpack")
        if bp then clearLegacyAura(bp) end
    end

    local function ownEffect(obj)
        if obj then table.insert(appliedEffectObjects, obj) end
        return obj
    end

    local KNIFE_HINTS = { "knife", "blade", "dagger", "sword", "melee", "stab" }
    local GUN_HINTS = { "gun", "revolver", "pistol", "firearm", "blaster" }
    local function hasHint(value, hints)
        value = tostring(value or ""):lower()
        for _, hint in ipairs(hints) do if value:find(hint, 1, true) then return true end end
        return false
    end
    local function attributeText(instance)
        if not instance then return "" end
        local values = { instance.Name }
        if instance:IsA("Tool") then values[#values + 1] = instance.ToolTip end
        for _, key in ipairs({ "ItemType", "WeaponType", "Type", "Category", "ItemName" }) do
            local ok, value = pcall(instance.GetAttribute, instance, key)
            if ok and value ~= nil then values[#values + 1] = tostring(value) end
        end
        return table.concat(values, " ")
    end
    local function looksLikeKnife(instance)
        if not instance then return false end
        local descriptor = attributeText(instance)
        if hasHint(descriptor, GUN_HINTS) then return false end
        if hasHint(descriptor, KNIFE_HINTS) then return true end
        if instance:IsA("Tool") then
            for _, descendant in ipairs(instance:GetDescendants()) do
                if hasHint(descendant.Name, KNIFE_HINTS) then return true end
            end
        end
        return false
    end
    local function currentKnifeTargets()
        local targets, seenHandles, seenContainers = {}, {}, {}
        local function preferredHandle(container)
            if container:IsA("BasePart") then return container end
            local named = container:FindFirstChild("KnifeVisual", true)
                or container:FindFirstChild("Blade", true)
                or container:FindFirstChild("Handle", true)
            if named and named:IsA("BasePart") and named.Transparency < 0.98 then return named end
            local fallback = named and named:IsA("BasePart") and named or nil
            for _, descendant in ipairs(container:GetDescendants()) do
                if descendant:IsA("BasePart") then
                    if descendant.Transparency < 0.98 then return descendant end
                    fallback = fallback or descendant
                end
            end
            return fallback
        end
        local function add(container)
            if not container or seenContainers[container] then return end
            local handle = preferredHandle(container)
            if not handle or seenHandles[handle] then return end
            seenContainers[container], seenHandles[handle] = true, true
            targets[#targets + 1] = {
                container = container:IsA("BasePart") and (container.Parent or LP.Character) or container,
                handle = handle,
            }
        end
        local function scan(root)
            if not root then return end
            for _, child in ipairs(root:GetChildren()) do
                if looksLikeKnife(child) then add(child) end
            end
            for _, descendant in ipairs(root:GetDescendants()) do
                if (descendant:IsA("Tool") or descendant:IsA("Accessory") or descendant:IsA("Model"))
                    and looksLikeKnife(descendant) then
                    add(descendant)
                elseif descendant:IsA("BasePart") and looksLikeKnife(descendant) then
                    local container = descendant:FindFirstAncestorWhichIsA("Tool")
                        or descendant:FindFirstAncestorWhichIsA("Accessory")
                        or descendant.Parent
                    add(container or descendant)
                end
            end
        end
        scan(LP.Character)
        scan(LP:FindFirstChildOfClass("Backpack"))
        if #targets == 0 then
            local gear = GearCache[LP.Name]
            local equippedKey = tostring(type(gear) == "table" and gear.Knife or ""):lower():gsub("[^%w]", "")
            local function scanFallback(root, held)
                if not root then return end
                for _, child in ipairs(root:GetChildren()) do
                    if child:IsA("Tool") or child:IsA("Accessory") or child:IsA("Model") then
                        local descriptor = attributeText(child)
                        local childKey = tostring(child.Name):lower():gsub("[^%w]", "")
                        local matchesEquipped = equippedKey ~= "" and (childKey:find(equippedKey, 1, true)
                            or equippedKey:find(childKey, 1, true))
                        if not hasHint(descriptor, GUN_HINTS) and (matchesEquipped or (held and child:IsA("Tool"))) then
                            add(child)
                        end
                    end
                end
            end
            scanFallback(LP.Character, true)
            if #targets == 0 then scanFallback(LP:FindFirstChildOfClass("Backpack"), false) end
        end
        S._KnifeEffectTargetCount = #targets
        return targets
    end

    local function sanitizeVisual(obj)
        local function sanitizeOne(d)
            if d:IsA("BaseScript") or d:IsA("ModuleScript") or d:IsA("Camera") then
                pcall(function() d:Destroy() end)
            elseif d:IsA("BasePart") then
                d.Anchored = false
                d.CanCollide = false
                d.CanTouch = false
                d.CanQuery = false
                d.Massless = true
            elseif d:IsA("ParticleEmitter") then
                pcall(function()
                    if d.Rate <= 0 then d.Rate = MOBILE and 10 or 18 end
                    d.Rate = math.min(d.Rate, MOBILE and 28 or 55)
                    d.LightInfluence = 0
                    d.LockedToPart = true
                    d.Enabled = true
                end)
            elseif d:IsA("Trail") or d:IsA("Beam") then
                pcall(function() d.Enabled = true end)
            elseif d:IsA("Fire") or d:IsA("Smoke") or d:IsA("Sparkles") then
                pcall(function() d.Enabled = true end)
            elseif d:IsA("Light") then
                pcall(function() d.Enabled = true end)
            end
        end
        sanitizeOne(obj)
        for _, d in ipairs(obj:GetDescendants()) do
            sanitizeOne(d)
        end
    end

    local function ensureTrailAttachments(obj, handle)
        local visualObjects = { obj }
        for _, descendant in ipairs(obj:GetDescendants()) do visualObjects[#visualObjects + 1] = descendant end
        for _, d in ipairs(visualObjects) do
            if d:IsA("Trail") or d:IsA("Beam") then
                local a0 = d.Attachment0
                local a1 = d.Attachment1
                if not a0 or not a0.Parent then
                    a0 = Instance.new("Attachment")
                    a0.Name = "MM2_FX_A0"
                    a0.Position = Vector3.new(0, -0.55, 0)
                    a0.Parent = handle
                    ownEffect(a0)
                    d.Attachment0 = a0
                end
                if not a1 or not a1.Parent then
                    a1 = Instance.new("Attachment")
                    a1.Name = "MM2_FX_A1"
                    a1.Position = Vector3.new(0, 0.85, 0)
                    a1.Parent = handle
                    ownEffect(a1)
                    d.Attachment1 = a1
                end
            end
        end
    end

    local function mountVisual(obj, tool, handle)
        local clone = obj:Clone()
        clone.Name = "MM2_FX_" .. tostring(obj.Name)
        sanitizeVisual(clone)
        if clone:IsA("ParticleEmitter") or clone:IsA("Fire") or clone:IsA("Smoke")
            or clone:IsA("Sparkles") or clone:IsA("Light") then
            clone.Parent = handle
        elseif clone:IsA("Trail") or clone:IsA("Beam") then
            clone.Parent = handle
            ensureTrailAttachments(clone, handle)
        elseif clone:IsA("Attachment") then
            clone.Parent = handle
        elseif clone:IsA("BasePart") then
            clone.CFrame = handle.CFrame
            clone.Parent = tool
            local weld = Instance.new("WeldConstraint")
            weld.Name = "MM2_FX_Weld"
            weld.Part0 = handle
            weld.Part1 = clone
            weld.Parent = clone
        elseif clone:IsA("Model") then
            clone.Parent = tool
            pcall(function() clone:PivotTo(handle.CFrame) end)
            for _, part in ipairs(clone:GetDescendants()) do
                if part:IsA("BasePart") then
                    local weld = Instance.new("WeldConstraint")
                    weld.Name = "MM2_FX_Weld"
                    weld.Part0 = handle
                    weld.Part1 = part
                    weld.Parent = part
                end
            end
        else
            clone.Parent = handle
        end
        ensureTrailAttachments(clone, handle)
        ownEffect(clone)
        return true
    end

    local function getCatalogContainer()
        local playerGui = LP:FindFirstChildOfClass("PlayerGui")
        local mainGui = playerGui and playerGui:FindFirstChild("MainGUI")
        local gameGui = mainGui and mainGui:FindFirstChild("Game")
        local inventory = gameGui and gameGui:FindFirstChild("Inventory")
        local main = inventory and inventory:FindFirstChild("Main")
        local effects = main and main:FindFirstChild("Effects")
        local items = effects and effects:FindFirstChild("Items")
        local holder = items and items:FindFirstChild("Container")
        local current = holder and holder:FindFirstChild("Current")
        return current and current:FindFirstChild("Container")
    end

    local function clearCatalogIn(container)
        if not container then return end
        for _, card in ipairs(container:GetChildren()) do
            if card:GetAttribute("MM2LocalVisualEffect") == true then
                pcall(function() card:Destroy() end)
            end
        end
    end

    local function clearCatalog(container)
        clearCatalogIn(catalogContainer)
        if container ~= catalogContainer then clearCatalogIn(container) end
        catalogContainer, catalogCount = nil, 0
    end

    local function getKnifeEffects()
        local ok, sync = pcall(function()
            local database = RS:FindFirstChild("Database") or RS:WaitForChild("Database", 8)
            local syncModule = database and (database:FindFirstChild("Sync") or database:WaitForChild("Sync", 8))
            if not syncModule then return nil end
            return require(syncModule)
        end)
        local effects = ok and sync and sync.Effects
        if type(effects) ~= "table" then return {} end

        local result = {}
        for id, data in pairs(effects) do
            if type(data) == "table" and (data.KnifeModule ~= nil or data.Effect ~= nil
                or data.EffectModule ~= nil or data.Visual ~= nil or data.Asset ~= nil or data.Model ~= nil) then
                local item = {}
                for key, value in pairs(data) do item[key] = value end
                item.ItemName = item.ItemName or item.Name or tostring(id)
                item.Name = item.Name or item.ItemName
                item.Rarity = item.Rarity or "Common"
                item.Image = item.Image or ""
                table.insert(result, {Id = tostring(id), Data = item})
            end
        end
        table.sort(result, function(a, b)
            return string.lower(tostring(a.Data.ItemName)) < string.lower(tostring(b.Data.ItemName))
        end)
        return result
    end

    local effectSourceIndex = nil
    local function normalizeEffectKey(value)
        return tostring(value or ""):lower():gsub("[^%w]", "")
    end
    local function visualSourceScore(instance)
        if instance:IsA("ModuleScript") then return 0 end
        if instance:IsA("Attachment") or instance:IsA("ParticleEmitter") or instance:IsA("Trail")
            or instance:IsA("Beam") or instance:IsA("Fire") or instance:IsA("Smoke")
            or instance:IsA("Sparkles") or instance:IsA("Light") then return 8 end
        if instance:IsA("Model") or instance:IsA("Folder") then return 3 end
        if instance:IsA("BasePart") then return #instance:GetChildren() > 0 and 2 or 1 end
        if #instance:GetChildren() > 0 then return 2 end
        return 1
    end
    local function buildEffectSourceIndex()
        local index, scores = {}, {}
        for _, root in ipairs({ RS }) do
            if root then
                local objects = { root }
                for _, descendant in ipairs(root:GetDescendants()) do objects[#objects + 1] = descendant end
                for _, object in ipairs(objects) do
                    local key = normalizeEffectKey(object.Name)
                    if key ~= "" then
                        local score = visualSourceScore(object)
                        if scores[key] == nil or score > scores[key] then
                            scores[key], index[key] = score, object
                        end
                    end
                end
            end
        end
        effectSourceIndex = index
        return index
    end
    local function findEffectSource(effect)
        local data = effect and effect.Data
        local keys = {}
        local function addKey(value)
            if typeof(value) == "Instance" then
                if not value:IsA("ModuleScript") or #value:GetChildren() > 0 then return value end
                value = value.Name
            end
            local key = normalizeEffectKey(value)
            if key ~= "" and not table.find(keys, key) then keys[#keys + 1] = key end
            return nil
        end
        if type(data) == "table" then
            for _, field in ipairs({ "KnifeModule", "Effect", "EffectModule", "Visual", "Asset", "Model" }) do
                local value = data[field]
                local direct = addKey(value)
                if direct then return direct end
            end
            addKey(data.ItemName)
            addKey(data.Name)
        end
        addKey(effect and effect.Id)
        if #keys == 0 then return nil end
        local index = effectSourceIndex or buildEffectSourceIndex()
        for _, key in ipairs(keys) do
            local source = index[key] or index[key .. "effect"] or index[key .. "knifeeffect"]
            if source then return source end
        end
        local best, bestDelta = nil, math.huge
        for indexedKey, candidate in pairs(index) do
            for _, key in ipairs(keys) do
                if #key >= 4 and #indexedKey >= 4
                    and (indexedKey:find(key, 1, true) or key:find(indexedKey, 1, true)) then
                    local delta = math.abs(#indexedKey - #key)
                    if delta < bestDelta then
                        best, bestDelta = candidate, delta
                    end
                end
            end
        end
        return best
    end

    local function cloneVisualsFrom(source, tool, handle)
        local made = 0
        local function visit(node)
            local mountable = node:IsA("ParticleEmitter") or node:IsA("Trail") or node:IsA("Beam")
                or node:IsA("Fire") or node:IsA("Smoke") or node:IsA("Sparkles") or node:IsA("Light")
                or node:IsA("Attachment") or node:IsA("BasePart") or node:IsA("Model")
            if mountable then
                if mountVisual(node, tool, handle) then made += 1 end
                return
            end
            for _, child in ipairs(node:GetChildren()) do visit(child) end
        end
        visit(source)
        return made
    end

    local function fallbackEffect(effect, tool, handle)
        local seed = 0
        for i = 1, #effect.Id do seed += string.byte(effect.Id, i) end
        local color = Color3.fromHSV((seed % 360) / 360, 0.82, 1)
        local a0 = Instance.new("Attachment")
        a0.Name = "MM2_FX_A0"
        a0.Position = Vector3.new(0, -0.55, 0)
        a0.Parent = handle
        ownEffect(a0)
        local a1 = Instance.new("Attachment")
        a1.Name = "MM2_FX_A1"
        a1.Position = Vector3.new(0, 0.85, 0)
        a1.Parent = handle
        ownEffect(a1)
        local pe = Instance.new("ParticleEmitter")
        pe.Name = "MM2_FX_LocalEmitter"
        pe.Texture = "rbxasset://textures/particles/sparkles_main.dds"
        pe.Color = ColorSequence.new(color, color:Lerp(Color3.new(1, 1, 1), 0.35))
        pe.Size = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.22, 0), NumberSequenceKeypoint.new(0.7, 0.55, 0), NumberSequenceKeypoint.new(1, 0, 0)})
        pe.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.1, 0), NumberSequenceKeypoint.new(0.8, 0.35, 0), NumberSequenceKeypoint.new(1, 1, 0)})
        pe.Lifetime = NumberRange.new(0.28, 0.55)
        pe.Rate = MOBILE and 18 or 34
        pe.Speed = NumberRange.new(0.2, 0.8)
        pe.SpreadAngle = Vector2.new(80, 80)
        pe.LightEmission = 0.7
        pe.LightInfluence = 0
        pe.LockedToPart = true
        pe.Parent = handle
        ownEffect(pe)
        local tr = Instance.new("Trail")
        tr.Name = "MM2_FX_LocalTrail"
        tr.Attachment0 = a0
        tr.Attachment1 = a1
        tr.Color = ColorSequence.new(color, color:Lerp(Color3.new(0, 0, 0), 0.45))
        tr.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.15, 0), NumberSequenceKeypoint.new(1, 1, 0)})
        tr.Lifetime = 0.22
        tr.LightEmission = 0.45
        tr.Parent = handle
        ownEffect(tr)
        return true
    end

    local function hasRenderableKnifeEffect(container, handle)
        for _, root in ipairs({ handle, container }) do
            if root then
                local objects = { root }
                for _, descendant in ipairs(root:GetDescendants()) do objects[#objects + 1] = descendant end
                for _, object in ipairs(objects) do
                    if string.sub(object.Name or "", 1, 7) == "MM2_FX_"
                        and (object:IsA("ParticleEmitter") or object:IsA("Trail") or object:IsA("Beam")
                            or object:IsA("Fire") or object:IsA("Smoke") or object:IsA("Sparkles")
                            or object:IsA("Light") or object:IsA("BasePart")) then
                        return true
                    end
                end
            end
        end
        return false
    end
    local function applyKnifeEffect(effectId, effectData, silent, force)
        if not (S.UnlockAllKnifeEffects and effectId) then return false end
        local targets = currentKnifeTargets()
        if #targets == 0 then
            if not silent then Notify("Knife Effect", "Equip/hold Knife first; saved for next Knife.", 3) end
            return false
        end
        effectId = tostring(effectId)
        if force or appliedEffectId ~= effectId then clearAppliedKnifeEffect() end
        local effect = { Id = tostring(effectId), Data = effectData or {} }
        local source = findEffectSource(effect)
        local applied = 0
        for _, target in ipairs(targets) do
            local container, handle = target.container, target.handle
            local marker = handle and handle:FindFirstChild("MM2_FX_Applied")
            if marker and not hasRenderableKnifeEffect(container, handle) then
                pcall(function() marker:Destroy() end)
                marker = nil
            end
            if container and handle and handle.Parent and not handle:FindFirstChild("MM2_FX_Applied") then
                marker = Instance.new("BoolValue")
                marker.Name = "MM2_FX_Applied"
                marker.Parent = handle
                ownEffect(marker)
                local made = 0
                if source then
                    local ok, count = pcall(cloneVisualsFrom, source, container, handle)
                    if ok then made = tonumber(count) or 0 end
                end
                if made <= 0 then pcall(fallbackEffect, effect, container, handle) end
            end
            if handle and handle:FindFirstChild("MM2_FX_Applied") and hasRenderableKnifeEffect(container, handle) then applied += 1 end
        end
        appliedEffectId = effectId
        if not silent then Notify("Knife Effect", "Applied: " .. tostring((effectData and (effectData.Name or effectData.ItemName)) or effectId), 2) end
        return applied > 0
    end

    S._ApplySelectedKnifeEffect = function(silent, force)
        if not S.UnlockAllKnifeEffects or tostring(S.ActiveVisualEffect or "") == "" then return false end
        for _, effect in ipairs(getKnifeEffects()) do
            if effect.Id == tostring(S.ActiveVisualEffect) then
                return applyKnifeEffect(effect.Id, effect.Data, silent, force)
            end
        end
        return false
    end

    local function visualCardCount(container)
        local count = 0
        if container then
            for _, card in ipairs(container:GetChildren()) do
                if card:GetAttribute("MM2LocalVisualEffect") == true then count += 1 end
            end
        end
        return count
    end

    local function populateCatalog()
        local container = getCatalogContainer()
        if not container then return end

        local effects = getKnifeEffects()
        if #effects == 0 then return end
        if container == catalogContainer and catalogCount == #effects and visualCardCount(container) == #effects then return end

        clearCatalog(container)
        local modules = RS:FindFirstChild("Modules")
        local inventoryModule = modules and modules:FindFirstChild("InventoryModule")
        local template = inventoryModule and inventoryModule:FindFirstChild("NewItem")
        local ok, itemModule = pcall(function()
            local module = modules and (modules:FindFirstChild("ItemModule") or modules:WaitForChild("ItemModule", 8))
            return module and require(module) or nil
        end)
        if not template or not ok or type(itemModule) ~= "table" then return end

        for index, effect in ipairs(effects) do
            pcall(function()
                local card = template:Clone()
                card.Name = "MM2_LocalKnifeEffect_" .. effect.Id
                card.LayoutOrder = 5000 + index
                card:SetAttribute("MM2LocalVisualEffect", true)
                card:SetAttribute("MM2LocalEffectId", effect.Id)
                itemModule.DisplayItem(card, effect.Data, 1, true)

                local actionButton = card:FindFirstChild("ActionButton", true)
                if actionButton and actionButton:IsA("GuiButton") then
                    actionButton.Active = true
                    actionButton.Selectable = true
                    actionButton.AutoButtonColor = true
                    actionButton.Activated:Connect(function()
                        if SFX and SFX.Click then pcall(SFX.Click) end
                        S.ActiveVisualEffect = effect.Id
                        local ok = applyKnifeEffect(effect.Id, effect.Data, true, true)
                        pcall(function() if S.SaveConfig then S.SaveConfig("_autoload") end end)
                        if S._MarkSelectedEffect then pcall(S._MarkSelectedEffect) end

                        local label = tostring((effect.Data and (effect.Data.Name or effect.Data.ItemName)) or effect.Id)
                        if ok then
                            Notify("Knife Effect", "Applied: " .. label, 2)
                        else
                            Notify("Knife Effect", "Selected: " .. label ..
                                " - applies as soon as you hold a knife.", 4)
                        end
                    end)
                end
                local amount = card:FindFirstChild("Amount", true)
                if amount and amount:IsA("TextLabel") then amount.Text = "" end
                card.Parent = container
            end)
        end
        catalogContainer, catalogCount = container, #effects
        if S._MarkSelectedEffect then pcall(S._MarkSelectedEffect) end
    end

    S._MarkSelectedEffect = function()
        local container = getCatalogContainer()
        if not container then return end
        for _, card in ipairs(container:GetChildren()) do
            if card:GetAttribute("MM2LocalVisualEffect") == true then
                local chosen = tostring(card:GetAttribute("MM2LocalEffectId")) == tostring(S.ActiveVisualEffect)
                local mark = card:FindFirstChild("MM2_FX_Selected")
                if chosen and not mark then
                    mark = Instance.new("UIStroke")
                    mark.Name = "MM2_FX_Selected"
                    mark.Color = Color3.fromRGB(120, 240, 255)
                    mark.Thickness = 2
                    mark.Parent = card
                elseif not chosen and mark then
                    mark:Destroy()
                end
            end
        end
    end

    local function refreshCatalog()
        if S.UnlockAllKnifeEffects then
            populateCatalog()
            if tostring(S.ActiveVisualEffect or "") ~= "" then pcall(S._ApplySelectedKnifeEffect, true) end
        else
            clearCatalog(getCatalogContainer())
            clearAppliedKnifeEffect()
        end
    end

    S._RefreshKnifeEffectCatalog = refreshCatalog
    clearLegacyAura(LP.Character)
    tt(function()
        local wasEnabled = false
        while S.Gui and S.Gui.Parent do
            if S.UnlockAllKnifeEffects or wasEnabled then pcall(refreshCatalog) end
            wasEnabled = S.UnlockAllKnifeEffects == true
            task.wait(1.25)
        end
        clearCatalog(getCatalogContainer())
    end)
    local function scheduleKnifeEffect(delaySeconds)
        S._KnifeEffectRequest = (S._KnifeEffectRequest or 0) + 1
        local requestId = S._KnifeEffectRequest
        tt(function()
            task.wait(delaySeconds)
            if S.Destroyed or requestId ~= S._KnifeEffectRequest then return end
            pcall(S._ApplySelectedKnifeEffect, true)
        end)
    end
    tc(LP.CharacterAdded:Connect(clearLegacyAura))
    tc(LP.CharacterAdded:Connect(function()
        scheduleKnifeEffect(0.8)
    end))
    local function watchKnifeContainer(container)
        if not container then return end
        tc(container.ChildAdded:Connect(function(child)
            if looksLikeKnife(child) then scheduleKnifeEffect(0.15) end
        end))
        tc(container.DescendantAdded:Connect(function(descendant)
            if hasHint(descendant.Name, KNIFE_HINTS) then scheduleKnifeEffect(0.12) end
        end))
    end
    local bp = LP:FindFirstChildOfClass("Backpack")
    watchKnifeContainer(bp)
    watchKnifeContainer(LP.Character)
    tc(LP.CharacterAdded:Connect(watchKnifeContainer))
    tc(LP.ChildAdded:Connect(function(child)
        if child:IsA("Backpack") then watchKnifeContainer(child) end
    end))
    cleanup(function()
        S._KnifeEffectRequest = (S._KnifeEffectRequest or 0) + 1
        clearCatalog(getCatalogContainer())
        clearAppliedKnifeEffect()
        if S._RefreshKnifeEffectCatalog == refreshCatalog then S._RefreshKnifeEffectCatalog = nil end
        S._ApplySelectedKnifeEffect = nil
    end)
end

do
    local dualModel, trackedHandle = nil, nil

    local function clearDual()
        if dualModel then pcall(function() dualModel:Destroy() end) end
        dualModel, trackedHandle = nil, nil
    end

    local function mirrorGrip(cf)
        local rx, ry, rz = cf:ToOrientation()
        local pos = cf.Position
        return CFrame.new(-pos.X, pos.Y, pos.Z) * CFrame.fromOrientation(rx, -ry, -rz)
    end

    local function mirrorTransform(cf)
        local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = cf:GetComponents()
        return CFrame.new(-x, y, z, r00, -r01, -r02, -r10, r11, r12, -r20, r21, r22)
    end

    local function buildDual(handle, rightHand, leftHand)
        clearDual()
        local grip
        for _, j in ipairs(rightHand:GetChildren()) do
            if (j:IsA("Motor6D") or j:IsA("Weld")) and j.Part1 == handle then grip = j; break end
        end

        local gripC0 = (grip and grip.C0) or CFrame.new(0, -1, 0)
        local gripC1 = (grip and grip.C1) or CFrame.new()

        local ok, clone = pcall(function() return handle:Clone() end)
        if not (ok and clone) then return end
        clone.Name = "DualWieldHandle"
        pcall(function() clone.CanCollide = false end)
        pcall(function() clone.Massless = true end)
        for _, d in ipairs(clone:GetDescendants()) do
            if d:IsA("Script") or d:IsA("LocalScript") or d:IsA("RemoteEvent") or d:IsA("RemoteFunction") or d:IsA("BindableEvent") then
                pcall(function() d:Destroy() end)
            end
        end
        local c = LP.Character
        if not c then pcall(function() clone:Destroy() end); return end
        clone.Parent = c

        local weld = Instance.new("Motor6D")
        weld.Name = "DualWieldGrip"
        weld.Part0 = leftHand
        weld.Part1 = clone
        weld.C0 = mirrorGrip(gripC0)
        weld.C1 = gripC1
        weld.Parent = leftHand

        dualModel, trackedHandle = clone, handle
    end

    tc(RunService.Heartbeat:Connect(function()
        if not S.DualWield then
            if dualModel then clearDual() end
            return
        end
        local c = LP.Character
        local tool = c and c:FindFirstChildWhichIsA("Tool")
        local handle = tool and tool:FindFirstChild("Handle")
        local rightHand = c and c:FindFirstChild("RightHand")
        local leftHand = c and c:FindFirstChild("LeftHand")
        if not (handle and rightHand and leftHand) then
            if dualModel then clearDual() end
            return
        end
        if handle ~= trackedHandle or not dualModel or not dualModel.Parent then
            pcall(buildDual, handle, rightHand, leftHand)
        end

        pcall(function()
            local rShoulder, lShoulder
            if c:FindFirstChild("RightUpperArm") and c.RightUpperArm:FindFirstChild("RightShoulder") then
                rShoulder = c.RightUpperArm.RightShoulder
                lShoulder = c.LeftUpperArm and c.LeftUpperArm:FindFirstChild("LeftShoulder")
            elseif c:FindFirstChild("Torso") then
                rShoulder = c.Torso:FindFirstChild("Right Shoulder")
                lShoulder = c.Torso:FindFirstChild("Left Shoulder")
            end
            if rShoulder and lShoulder then
                lShoulder.Transform = mirrorTransform(rShoulder.Transform)
            end
        end)
    end))
    tc(LP.CharacterAdded:Connect(function() clearDual() end))
end

S._RoleDataRoundActive = workspace:FindFirstChild("Normal") ~= nil
isRoundActive = function()
    return workspace:FindFirstChild("Normal") ~= nil or S._RoleDataRoundActive == true
end

do

    local coinContainer, coinCache, coinCacheAt = nil, {}, 0
    local function eachCoin(fn)
        if not (coinContainer and coinContainer.Parent) then
            coinContainer = workspace:FindFirstChild("CoinContainer", true)
        end
        if tick() - coinCacheAt > 1 or #coinCache == 0 then
            coinCache = {}
            local root = coinContainer or workspace:FindFirstChild("Normal")
            if root then
                for _, v in ipairs(root:GetDescendants()) do
                    if v:IsA("BasePart") then
                        local par = v.Parent
                        if string.find(string.lower(v.Name), "coin") or (par and string.find(string.lower(par.Name), "coin")) then
                            table.insert(coinCache, v)
                        end
                    end
                end
            end
            coinCacheAt = tick()
        end
        for _, v in ipairs(coinCache) do
            if v.Parent then fn(v) end
        end
    end

    local function moveTo(targetCF, speed, checkFn)
    local spd = math.max(speed or S.FastAutofarmSpeed or 40, 1)

    if S.AutofarmSync and targetCF then
        local c = LP.Character
        local hrp = c and c:FindFirstChild("HumanoidRootPart")
        if hrp then
            hrp.CFrame = CFrame.new(targetCF.Position)
            if checkFn then pcall(checkFn) end
            return true
        end
    end
        local deadline = tick() + 12
        local arrived = false
        while tick() < deadline do
            if not S.FastAutofarm then break end
            if checkFn and not checkFn() then break end
            local c = LP.Character
            local hrp = c and c:FindFirstChild("HumanoidRootPart")
            local hum = c and c:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 then break end
            for _, track in ipairs(hum:GetPlayingAnimationTracks()) do
                pcall(function() track:Stop() end)
            end
            S._SetOwnedAnchored(hrp, true)
            hrp.AssemblyLinearVelocity = Vector3.zero
            hrp.AssemblyAngularVelocity = Vector3.zero
            local dt = task.wait()
            c = LP.Character
            hrp = c and c:FindFirstChild("HumanoidRootPart")
            if not hrp then break end
            local delta = targetCF.Position - hrp.Position
            local dist = delta.Magnitude

            local step = math.min(spd * dt, S.AutofarmSafe and 10 or 40)
            if dist <= math.max(4.0, step) then
                hrp.CFrame = CFrame.new(targetCF.Position)
                arrived = true
                break
            end
            local dir = delta / dist
            local newPos = hrp.Position + dir * step
            local flat = Vector3.new(dir.X, 0, dir.Z)
            local stepCF = (flat.Magnitude > 0.05) and CFrame.new(newPos, newPos + flat) or CFrame.new(newPos)
            hrp.CFrame = stepCF
        end

        local c = LP.Character
        local hrp = c and c:FindFirstChild("HumanoidRootPart")
        if hrp then
            if not S.FastAutofarm then
                S._RestoreOwnedAnchored(hrp)
            end
            hrp.AssemblyLinearVelocity = Vector3.zero
        end
        return arrived
    end

    local secAuto = mkSection(Pages.Teleport, "Automated", 5, true)
    if S._RegisterAutofarmSection then S._RegisterAutofarmSection(secAuto) end
    mkToggle(secAuto, "Fast Autofarm", false, function(v) S.FastAutofarm = v end, 1)
    mkSlider(secAuto, "Autofarm Speed", 16, 40, 40, function(v) S.FastAutofarmSpeed = v end, 2)
    mkToggle(secAuto, "Sync Mode (Instant)", false, function(v) S.AutofarmSync = v end, 3)

    local syncDesc = Instance.new("TextLabel")
    syncDesc.Name = "SyncDesc"
    syncDesc.Parent = secAuto
    syncDesc.LayoutOrder = 5
    syncDesc.BackgroundTransparency = 1
    syncDesc.Size = UDim2.new(1, -10, 0, 45)
    syncDesc.Position = UDim2.new(0, 5, 0, 0)
    syncDesc.TextWrapped = true
