        PlayerTabs.animStroke = mkSubTabBtn(bar, PlayerTabs.animBtn, "Animations", 2, 1 / 2, -6)
    end

    local function registerPlayerSubTabSection(section, tabName)
        S._RegisterPlayerSubTabSection = registerPlayerSubTabSection
        local card = section and section.Parent or section
        local entry = { section = section, card = card }
        if tabName == "Animations" then
            table.insert(PlayerTabs.animSections, entry)
        elseif tabName == "Emotes" then
            table.insert(PlayerTabs.emoteSections, entry)
        end
        section:SetAttribute("PlayerSubTab", tabName)
        section:SetAttribute("ForceFullWidth", true)
        if card and card ~= section then
            card:SetAttribute("PlayerSubTab", tabName)
            card:SetAttribute("ForceFullWidth", true)
        end
        return section
    end

    local function updatePlayerSubTabs()
        local isAnim = PlayerTabs.active == "Animations"
        local isEmotes = not isAnim
        styleSubTabActive(PlayerTabs.animBtn, PlayerTabs.animStroke, isAnim)
        styleSubTabActive(PlayerTabs.emotesBtn, PlayerTabs.emotesStroke, isEmotes)
        local function setGroup(list, on)
            for _, entry in ipairs(list) do
                local sec = entry.section
                local card = entry.card or (sec and sec.Parent)
                if card then card.Visible = on end
                if sec then sec.Visible = on end
            end
        end
        setGroup(PlayerTabs.animSections, isAnim)
        setGroup(PlayerTabs.emoteSections, isEmotes)
        if S._RefreshPageLayout then pcall(S._RefreshPageLayout, false) end
        tt(function()
            if S._RefreshPageLayout then pcall(S._RefreshPageLayout, false) end
        end)
    end

    S._UpdatePlayerSubtabs = updatePlayerSubTabs
    PlayerTabs.animBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        PlayerTabs.active = "Animations"
        updatePlayerSubTabs()
    end)
    PlayerTabs.emotesBtn.MouseButton1Click:Connect(function()
        SFX.Click()
        PlayerTabs.active = "Emotes"
        updatePlayerSubTabs()
    end)

    S._mkThumbRow = function(parent, order, imgId, titleText, onClick)
        local row = Instance.new("TextButton")
        row.Name = "Row"
        row.LayoutOrder = order
        row.AutoButtonColor = false
        row.BorderSizePixel = 0
        row.Text = ""
        row.BackgroundColor3 = T.Elev; pcall(function() row:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
        row.Size = UDim2.new(1, 0, 0, 56)
        row.Parent = parent
        Corner(row, 6)
        row.MouseEnter:Connect(function() TweenService.Create(TweenService, row, TweenInfo.new(0.1), { BackgroundColor3 = T.Hover }):Play() end)
        row.MouseLeave:Connect(function() TweenService.Create(TweenService, row, TweenInfo.new(0.1), { BackgroundColor3 = T.Elev }):Play() end)

        local img = Instance.new("ImageLabel")
        img.Name = "Thumb"
        img.Parent = row
        img.BackgroundTransparency = 1
        img.AnchorPoint = Vector2.new(0, 0.5)
        img.Position = UDim2.new(0, 4, 0.5, 0)
        img.Size = UDim2.new(0, 48, 0, 48)
        img.ScaleType = Enum.ScaleType.Crop

        local thumbUrl = ""
        if imgId and imgId ~= "" then
            local bId = tostring(imgId):match("^bundle:(%d+)$")
            thumbUrl = bId and ("rbxthumb://type=BundleThumbnail&id=" .. bId .. "&w=420&h=420")
                or ("rbxthumb://type=Asset&id=" .. imgId .. "&w=420&h=420")
        end
        img.Image = thumbUrl ~= "" and thumbUrl or S._AvatarThumbnail
        if thumbUrl ~= "" then
            tt(function()
                task.wait(5)
                if not (img and img.Parent) then return end
                local ok, loaded = pcall(function() return img.IsLoaded end)
                if not ok or not loaded then img.Image = S._AvatarThumbnail end
            end)
        end
        Corner(img, 6)

        local lbl = Instance.new("TextLabel")
        lbl.Name = "Title"
        lbl.Parent = row
        lbl.BackgroundTransparency = 1
        lbl.Position = UDim2.new(0, 60, 0, 0)
        lbl.Size = UDim2.new(1, -68, 1, 0)
        lbl.Font = F
        lbl.TextSize = 13
        lbl.TextColor3 = T.Tx; pcall(function() lbl:SetAttribute("ThemeColorRole_TextColor3", "Tx") end)
        lbl.TextXAlignment = Enum.TextXAlignment.Left
        lbl.TextWrapped = true
        lbl.Text = titleText

        row.MouseButton1Click:Connect(function() SFX.Click(); onClick() end)
        return row
    end
    S._mkSearchBox = function(parent, order, placeholder)
        local box = Instance.new("TextBox")
        box.Parent = parent
        box.LayoutOrder = order
        box.Size = UDim2.new(1, 0, 0, 30)
        box.BackgroundColor3 = T.Elev; pcall(function() box:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
        box.BorderSizePixel = 0
        box.Font = F
        box.TextSize = 13
        box.TextColor3 = T.Tx; pcall(function() box:SetAttribute("ThemeColorRole_TextColor3", "Tx") end)
        box.PlaceholderText = placeholder
        box.PlaceholderColor3 = T.Tx4
        box.Text = ""
        box.ClearTextOnFocus = false
        box.TextXAlignment = Enum.TextXAlignment.Left
        Corner(box, 6)
        Stroke(box, T.Bd2, 1, 0.4)
        Pad(box, 0, 0, 8, 8)
        return box
    end
    S._mkListScroll = function(parent, order, height)
        local scroll = Instance.new("ScrollingFrame")
        scroll.Parent = parent
        scroll.LayoutOrder = order
        scroll.BackgroundColor3 = T.Card; pcall(function() scroll:SetAttribute("ThemeColorRole_BackgroundColor3", "Card") end)
        scroll.BorderSizePixel = 0
        scroll.Size = UDim2.new(1, 0, 0, height)
        scroll.CanvasSize = UDim2.new(0, 0, 0, 0)
        scroll.Active = true
        scroll.ScrollingEnabled = true
        scroll.ScrollingDirection = Enum.ScrollingDirection.Y
        scroll.ScrollBarThickness = MOBILE and 6 or 4
        scroll.ScrollBarImageColor3 = T.Tx3; pcall(function() scroll:SetAttribute("ThemeColorRole_ScrollBarImageColor3", "Tx3") end)
        scroll.AutomaticCanvasSize = Enum.AutomaticSize.Y
        Corner(scroll, 8)
        Stroke(scroll, T.Bd, 1, 0.4)
        local layout = Instance.new("UIListLayout")
        layout.Parent = scroll
        layout.SortOrder = Enum.SortOrder.LayoutOrder
        layout.Padding = UDim.new(0, 4)
        Pad(scroll, 6, 6, 6, 6)
        return scroll
    end

    do
end

