local function stopEmbeddedEmote()
    if currentEmoteTrack then pcall(function() currentEmoteTrack:Stop(0.15) end); currentEmoteTrack = nil end
    if currentEmoteAnim then pcall(function() currentEmoteAnim:Destroy() end); currentEmoteAnim = nil end
end
local function playEmbeddedEmote(item)
    local id = tonumber(item and item.id)
    if not id then emoteStatus.Text = "Invalid emote id."; return end
    local char = LP.Character
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hum then emoteStatus.Text = "Character is not ready."; return end
    local animator = hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 1)
    if not animator then
        animator = Instance.new("Animator")
        animator.Parent = hum
    end
    stopEmbeddedEmote()

    local before = {}
    for _, t in ipairs(hum:GetPlayingAnimationTracks()) do before[t] = true end
    local ok, firstResult, secondResult = pcall(function()
        return hum:PlayEmoteAndGetAnimTrackById(id)
    end)
    if not ok then emoteStatus.Text = "This emote cannot play in this place."; return end
    local track = typeof(firstResult) == "Instance" and firstResult:IsA("AnimationTrack") and firstResult
        or (typeof(secondResult) == "Instance" and secondResult:IsA("AnimationTrack") and secondResult)
    if firstResult == false and not track then
        emoteStatus.Text = "Blocked in this place: " .. tostring(item.name or id)
        return
    end
    for _ = 1, 14 do
        for _, t in ipairs(hum:GetPlayingAnimationTracks()) do
            if not before[t] then track = t; break end
        end
        if track then break end
        task.wait(0.05)
    end
    if not track then
        emoteStatus.Text = "Blocked in this place: " .. tostring(item.name or id)
        return
    end
    currentEmoteTrack = track
    pcall(function() track:AdjustSpeed(tonumber(S.EmoteSpeed) or 1) end)
    if S.LoopEmote then

        local resolved = track.Animation and track.Animation.AnimationId
        if resolved and resolved ~= "" then
            local a = Instance.new("Animation")
            a.Name = "InertiaEmbeddedEmote"
            a.AnimationId = resolved
            a.Parent = SG
            local ok2, loopTrack = pcall(function() return animator:LoadAnimation(a) end)
            if ok2 and loopTrack then
                pcall(function() track:Stop(0.1) end)
                loopTrack.Priority = Enum.AnimationPriority.Idle
                loopTrack.Looped = true
                pcall(function() loopTrack:Play(0.12, 1, tonumber(S.EmoteSpeed) or 1) end)
                currentEmoteAnim = a
                currentEmoteTrack = loopTrack
            else
                a:Destroy()
            end
        end
    end
    emoteStatus.Text = "Playing: " .. tostring(item.name or id)
end

