            pin.Size = UDim2.fromOffset(28, 28)
            pin.BackgroundColor3 = T.Card
            pin.BackgroundTransparency = 0.1
            pin.BorderSizePixel = 0
            pin.Font = FB
            pin.TextSize = 16
            pin.TextColor3 = T.Tx
            pin.Text = pinnedById[tostring(item.id)] and "ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã¢â‚¬Â¹Ãƒâ€¦Ã¢â‚¬Å“ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â¦" or "+"
            Corner(pin, 7)
