    local secMusic = mkSection(Pages.Misc, "Music", 9, true)
    S._RegisterMiscSection(secMusic, "Music")

    local CATS = { "All", "Favourites" }
    for cat in pairs(MUSIC) do table.insert(CATS, cat) end
    table.sort(CATS, function(a, b)
        local ra = (a == "All" and 0) or (a == "Favourites" and 1) or 2
        local rb = (b == "All" and 0) or (b == "Favourites" and 1) or 2
        if ra ~= rb then return ra < rb end
        return a < b
    end)

    local sound
    local function ensureSound()
        if not sound or not sound.Parent then
            sound = Instance.new("Sound")
            sound.Name = "InertiaMusic"
            sound.Parent = SG
        end
        return sound
    end
    local function playId(id, label)
        id = tonumber(tostring(id):match("%d+"))
        if not id then Notify("Music", "Enter an audio ID", 2); return end
        local s = ensureSound()
        s:Stop()
        s.SoundId = "rbxassetid://" .. id
        s.Volume = math.clamp((tonumber(S.MusicVolume) or 50) / 100, 0, 1)
        s.Looped = S.MusicLoop == true
        s:Play()
        Notify("Music", "Playing " .. tostring(label or id), 2)
    end
    S._MusicPlay = playId

    local function isFav(id)
        S.MusicFavs = S.MusicFavs or {}
        return S.MusicFavs[tostring(id)] == true
    end
    local function toggleFav(id)
        S.MusicFavs = S.MusicFavs or {}
        local key = tostring(id)
        S.MusicFavs[key] = (not S.MusicFavs[key]) or nil
        pcall(function() if S.SaveConfig then S.SaveConfig("_autoload") end end)
        return S.MusicFavs[key] == true
    end

    local ALL = {}
    for cat, list in pairs(MUSIC) do
        for _, entry in ipairs(list) do
            table.insert(ALL, { id = entry[1], name = entry[2], cat = cat })
        end
    end
    table.sort(ALL, function(a, b) return string.lower(a.name) < string.lower(b.name) end)

    local query = ""
    local matches = {}
    local rowPool = {}
    local ROW_H = 30

    local scroll = S._mkListScroll(secMusic, 5, MOBILE and 300 or 260)
    scroll.AutomaticCanvasSize = Enum.AutomaticSize.None

    for _, child in ipairs(scroll:GetChildren()) do
        if child:IsA("UIListLayout") then child:Destroy() end
    end

    local function rebuildMatches()
        table.clear(matches)
        local cat = S.MusicCategory or "All"
        local q = string.lower(query)
        for _, e in ipairs(ALL) do
            local catOk = (cat == "All") or (cat == "Favourites" and isFav(e.id)) or (e.cat == cat)
            if catOk and (q == "" or string.find(string.lower(e.name), q, 1, true)
                or string.find(tostring(e.id), q, 1, true)) then
                matches[#matches + 1] = e
            end
        end
    end

    local function render()
        local total = #matches
        scroll.CanvasSize = UDim2.new(0, 0, 0, math.max(0, total * ROW_H + 8))
        local viewH = math.clamp(scroll.AbsoluteWindowSize.Y > 0 and scroll.AbsoluteWindowSize.Y
            or scroll.AbsoluteSize.Y, 100, 900)
        local first = math.max(1, math.floor(scroll.CanvasPosition.Y / ROW_H) + 1)
        local last = math.min(total, first + math.ceil(viewH / ROW_H) + 4)
        for i, row in pairs(rowPool) do
            if i < first or i > last then row:Destroy(); rowPool[i] = nil end
        end
        for i = first, last do
            local e = matches[i]
            if e and not rowPool[i] then
                local row = Instance.new("Frame")
                row.Name = "Row"
                row.Parent = scroll
                row.BackgroundTransparency = 1
                row.Position = UDim2.fromOffset(0, (i - 1) * ROW_H)
                row.Size = UDim2.new(1, -10, 0, ROW_H - 4)

                local play = Instance.new("TextButton")
                play.Parent = row
                play.Size = UDim2.new(1, -108, 1, 0)
                play.BackgroundColor3 = T.Elev
                pcall(function() play:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
                play.BorderSizePixel = 0
                play.AutoButtonColor = false
                play.Font = F
                play.TextSize = 12
                play.TextXAlignment = Enum.TextXAlignment.Left
                play.TextTruncate = Enum.TextTruncate.AtEnd
                play.TextColor3 = T.Tx
                pcall(function() play:SetAttribute("ThemeColorRole_TextColor3", "Tx") end)
                play.Text = "  " .. e.name
                Corner(play, 6)
                play.MouseButton1Click:Connect(function() SFX.Click(); playId(e.id, e.name) end)

                local fav = Instance.new("TextButton")
                fav.Parent = row
                fav.AnchorPoint = Vector2.new(1, 0)
                fav.Position = UDim2.new(1, -54, 0, 0)
                fav.Size = UDim2.fromOffset(48, ROW_H - 4)
                fav.BackgroundColor3 = T.Elev
                pcall(function() fav:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
                fav.BorderSizePixel = 0
                fav.AutoButtonColor = false
                fav.Font = FB
                fav.TextSize = 12
                fav.TextColor3 = isFav(e.id) and T.Accent or T.Tx3
                fav.Text = isFav(e.id) and "FAV" or "+"
                Corner(fav, 6)
                fav.MouseButton1Click:Connect(function()
                    SFX.Click()
                    local on = toggleFav(e.id)
                    fav.Text = on and "FAV" or "+"
                    fav.TextColor3 = on and T.Accent or T.Tx3
                    if S.MusicCategory == "Favourites" and S._MusicRefresh then S._MusicRefresh() end
                end)

                local copy = Instance.new("TextButton")
                copy.Parent = row
                copy.AnchorPoint = Vector2.new(1, 0)
                copy.Position = UDim2.new(1, 0, 0, 0)
                copy.Size = UDim2.fromOffset(50, ROW_H - 4)
                copy.BackgroundColor3 = T.Elev
                pcall(function() copy:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
                copy.BorderSizePixel = 0
                copy.AutoButtonColor = false
                copy.Font = F
                copy.TextSize = 11
                copy.TextColor3 = T.Tx3
                copy.Text = "COPY"
                Corner(copy, 6)
                copy.MouseButton1Click:Connect(function()
                    SFX.Click()
                    local clip = setclipboard or toclipboard or writeclipboard or (syn and syn.write_clipboard)
                    if clip then
                        pcall(clip, tostring(e.id))
                        Notify("Music", "Copied " .. tostring(e.id), 2)
                    else
                        Notify("Music", "ID: " .. tostring(e.id), 4)
                    end
                end)

                rowPool[i] = row
            end
        end
    end

    local function refresh()
        rebuildMatches()
        for k, r in pairs(rowPool) do r:Destroy(); rowPool[k] = nil end
        scroll.CanvasPosition = Vector2.zero
        render()
    end
    S._MusicRefresh = refresh

    S._mkCycle(secMusic, "Category", CATS, "All", function(v)
        S.MusicCategory = v
        refresh()
    end, 1)

    local function mkBox(name, order, placeholder)
        local box = Instance.new("TextBox")
        box.Name = name
        box.Parent = secMusic
        box.LayoutOrder = order
        box.Size = UDim2.new(1, 0, 0, MOBILE and 34 or 28)
        box.BackgroundColor3 = T.Elev
        pcall(function() box:SetAttribute("ThemeColorRole_BackgroundColor3", "Elev") end)
        box.BorderSizePixel = 0
        box.Font = F
        box.TextSize = 13
        box.TextColor3 = T.Tx
        pcall(function() box:SetAttribute("ThemeColorRole_TextColor3", "Tx") end)
        box.PlaceholderText = placeholder
        box.Text = ""
        box.ClearTextOnFocus = false
        Corner(box, 6)
        Stroke(box, T.Bd, 1, 0.4)
        return box
    end

    local searchBox = mkBox("MusicSearch", 2, "Search by name or ID...")
    searchBox:GetPropertyChangedSignal("Text"):Connect(function()
        query = searchBox.Text or ""
        refresh()
    end)

    local idBox = mkBox("MusicIdBox", 3, "Paste any audio ID, press Enter")
    idBox.FocusLost:Connect(function(enter)
        if enter and idBox.Text ~= "" then playId(idBox.Text) end
    end)

    S._mkAction(secMusic, "Stop", function()
        if sound then pcall(function() sound:Stop() end) end
    end, 6)
    mkSlider(secMusic, "Volume", 0, 100, 50, function(v)
        S.MusicVolume = v
        if sound then sound.Volume = math.clamp(v / 100, 0, 1) end
    end, 7)
    mkToggle(secMusic, "Loop", false, function(v)
        S.MusicLoop = v
        if sound then sound.Looped = v end
    end, 8)

    scroll:GetPropertyChangedSignal("CanvasPosition"):Connect(render)
    scroll:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(render)
    refresh()
end


do
    local secDesync = mkSection(Pages.Motion, "Desync", 5, true)

    if S._RegisterMotionMovementSection then pcall(S._RegisterMotionMovementSection, secDesync) end
    local lastCF, lastVel, lastAng, applied = nil, nil, nil, false

    local DESYNC_SPAN = 7777
    local function offsetCFrame()
        local rnd = math.random
        return Vector3.new(
            (rnd() * 2 - 1) * DESYNC_SPAN,
            rnd() * DESYNC_SPAN,
            (rnd() * 2 - 1) * DESYNC_SPAN
        ), CFrame.Angles(rnd() * 6.2832, rnd() * 6.2832, rnd() * 6.2832)
    end

    tc(RunService.Heartbeat:Connect(function()
        if not S.Desync then return end
        local char = LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        local hum = char and char:FindFirstChildOfClass("Humanoid")
        if not hrp or not hum or hum.Health <= 0 then return end

        if S.DesyncAlways == false and hum.MoveDirection.Magnitude < 0.1 then return end

        local pos, rot = offsetCFrame()
        lastCF = hrp.CFrame
        lastVel = hrp.AssemblyLinearVelocity
        lastAng = hrp.AssemblyAngularVelocity
        applied = true
        hrp.CFrame = (lastCF + pos) * rot
    end))

    local restoreName = "InertiaDesyncRestore_" .. tostring(math.random(1, 1e9))
    RunService:BindToRenderStep(restoreName, Enum.RenderPriority.First.Value - 1, function()
        if not applied then return end
        applied = false
        local char = LP.Character
        local hrp = char and char:FindFirstChild("HumanoidRootPart")
        if hrp and lastCF then
            hrp.CFrame = lastCF

            if lastVel then hrp.AssemblyLinearVelocity = lastVel end
            if lastAng then hrp.AssemblyAngularVelocity = lastAng end
        end
        lastCF, lastVel, lastAng = nil, nil, nil
    end)
    SG.Destroying:Connect(function()
        pcall(function() RunService:UnbindFromRenderStep(restoreName) end)
    end)

    mkToggle(secDesync, "Desync (Fake Position)", false, function(v)
        S.Desync = v
        if not v then

            local char = LP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp and applied and lastCF then hrp.CFrame = lastCF end
            lastCF, lastVel, lastAng, applied = nil, nil, nil, false
        end
    end, 1)

    do
        local vLast, vCF, vApplied = nil, nil, false
        local VEL_SPAN = 7777

        tc(RunService.Heartbeat:Connect(function()
            if not S.VelDesync then return end
            local char = LP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hrp or not hum or hum.Health <= 0 then return end
            if S.VelDesyncAlways == false and hum.MoveDirection.Magnitude < 0.1 then return end
            local rnd = math.random

            vCF = hrp.CFrame
            vLast = hrp.AssemblyLinearVelocity
            vApplied = true
            hrp.AssemblyLinearVelocity = Vector3.new(
                (rnd() * 2 - 1) * VEL_SPAN,
                rnd() * VEL_SPAN,
                (rnd() * 2 - 1) * VEL_SPAN
            )
        end))

        local vName = "InertiaVelDesyncRestore_" .. tostring(math.random(1, 1e9))
        RunService:BindToRenderStep(vName, Enum.RenderPriority.First.Value - 1, function()
            if not vApplied then return end
            vApplied = false
            local char = LP.Character
            local hrp = char and char:FindFirstChild("HumanoidRootPart")
            if hrp then
                if vCF then hrp.CFrame = vCF end
                if vLast then hrp.AssemblyLinearVelocity = vLast end
            end
            vLast, vCF = nil, nil
        end)
        SG.Destroying:Connect(function()
            pcall(function() RunService:UnbindFromRenderStep(vName) end)
        end)

        mkToggle(secDesync, "Velocity Desync", false, function(v)
            S.VelDesync = v
            if not v then
                local char = LP.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp and vApplied then
                    if vCF then hrp.CFrame = vCF end
                    if vLast then hrp.AssemblyLinearVelocity = vLast end
                end
                vLast, vCF, vApplied = nil, nil, false
            end
        end, 2)

    local aaEnabled, aaConn, hadKnifeLastFrame = false, nil, false
    local function hasKnifeAA()
        local c = LP.Character
        if c and c:FindFirstChild("Knife") then return true end
        local bp = LP:FindFirstChild("Backpack")
        return bp and bp:FindFirstChild("Knife") ~= nil
    end
    mkToggle(secDesync, "Anti Aim", false, function(v)
        aaEnabled = v
        if v then
            if not aaConn then
                aaConn = tc(RunService.Heartbeat:Connect(function()
                    if not aaEnabled then return end
                    local char = LP.Character
                    local hrp = char and char:FindFirstChild("HumanoidRootPart")
                    local hum = char and char:FindFirstChildOfClass("Humanoid")
                    if not hrp or not hum or hum.Health <= 0 then return end
                    local nowKnife = hasKnifeAA()
                    if nowKnife and not hadKnifeLastFrame then
                        local d = math.random() > 0.5 and 1 or -1
                        task.spawn(function()
                            local t0 = tick()
                            while tick() - t0 < 0.15 do
                                if hum and hum.Parent then hum:Move(Vector3.new(d, 0, d).Unit, false) end
                                RunService.RenderStepped:Wait()
                            end
                        end)
                    end
                    hadKnifeLastFrame = nowKnife
                    if not nowKnife or hum.MoveDirection.Magnitude < 0.1 then return end
                    local mult = math.random(1, 2) == 1 and 320 or -320
                    local oldVel = hrp.AssemblyLinearVelocity
                    hrp.AssemblyLinearVelocity = Vector3.new(mult, 0, mult)
                    RunService.RenderStepped:Wait()
                    pcall(function() hrp.AssemblyLinearVelocity = oldVel end)
                end))
            end
        else
            if aaConn then aaConn:Disconnect(); aaConn = nil end
        end
    end, 3)
    end
end

do

    local secView = mkSection(Pages.Visuals, "View", 4, true)
    if S._RegisterVisualsEnvSection then pcall(S._RegisterVisualsEnvSection, secView) end

    local fovOriginals = setmetatable({}, { __mode = "k" })
    local function restoreFOV()
        for camera, original in pairs(fovOriginals) do
            pcall(function() camera.FieldOfView = original end)
            fovOriginals[camera] = nil
        end
    end
    tc(RunService.RenderStepped:Connect(function()
        local cam = workspace.CurrentCamera
        if not cam then return end
        if not S.CustomFOV then
            if next(fovOriginals) ~= nil then restoreFOV() end
            return
        end
        if fovOriginals[cam] == nil then fovOriginals[cam] = cam.FieldOfView end
        local want = math.clamp(tonumber(S.FOVValue) or 70, 20, 120)
        if math.abs(cam.FieldOfView - want) > 0.05 then cam.FieldOfView = want end
    end))
    cleanup(restoreFOV)

    mkToggle(secView, "Custom FOV", false, function(v) S.CustomFOV = v end, 1)
    mkSlider(secView, "FOV", 20, 120, 70, function(v) S.FOVValue = v end, 2)



    do
        local a = game:GetService("Lighting"):FindFirstChild("InertiaAtmosphere")
        if a then a:Destroy() end
        local terrain = workspace:FindFirstChildOfClass("Terrain")
        local c = terrain and terrain:FindFirstChild("InertiaClouds")
        if c then c:Destroy() end
    end
end

do
    local Lighting2 = game:GetService("Lighting")
    local SPARK = "rbxasset://textures/particles/sparkles_main.dds"
    local SMOKE = "rbxasset://textures/particles/smoke_main.dds"

    local function ns2(...)
        local pts, a = {}, { ... }
        for i = 1, #a, 2 do pts[#pts + 1] = NumberSequenceKeypoint.new(a[i], a[i + 1]) end
        return NumberSequence.new(pts)
    end

    local WEATHER = {
        Rain = {
        tex = SPARK, color = Color3.fromRGB(180, 205, 235), rate = 1200,
        size = ns2(0, 0.35, 1, 0.35), tr = ns2(0, 0.1, 0.9, 0.2, 1, 1),
        life = { 0.85, 1.05 }, speed = { 100, 120 }, accel = Vector3.new(0, -150, 0),
        spread = 2, squash = ns2(0, -2, 1, -2), le = 0.2, drag = 0.5, slab = 160, height = 60,
    },
        Snow = {
            tex = SPARK, color = Color3.fromRGB(248, 250, 255), rate = 260,
            size = ns2(0, 0.3, 1, 0.28), tr = ns2(0, 0.15, 0.85, 0.2, 1, 1),
            life = { 5.5, 7 }, speed = { 7, 13 }, accel = Vector3.new(0, -11, 0),
            spread = 24, rotsp = { -45, 45 }, le = 0.4, drag = 1.6, slab = 130, height = 50,
        },
        Storm = {
        tex = SPARK, color = Color3.fromRGB(150, 172, 205), rate = 1800,
        size = ns2(0, 0.4, 1, 0.4), tr = ns2(0, 0.05, 0.9, 0.1, 1, 1),
        life = { 0.7, 0.9 }, speed = { 130, 160 }, accel = Vector3.new(0, -200, 0),
        spread = 4, squash = ns2(0, -3, 1, -3), le = 0.3, drag = 0, slab = 160, height = 65,
        thunder = true,
    },
        Ash = {
            tex = SMOKE, color = Color3.fromRGB(96, 92, 90), rate = 150,
            size = ns2(0, 0.45, 1, 0.2), tr = ns2(0, 0.5, 0.7, 0.6, 1, 1),
            life = { 6, 9 }, speed = { 3, 7 }, accel = Vector3.new(0, -3.5, 0),
            spread = 40, rotsp = { -25, 25 }, le = 0, drag = 1.2, slab = 120, height = 45,
        },
        Embers = {
            tex = SPARK, color = Color3.fromRGB(255, 150, 60), rate = 90,
            size = ns2(0, 0.16, 1, 0.04), tr = ns2(0, 0.1, 0.6, 0.35, 1, 1),
            life = { 4, 7 }, speed = { 2, 6 }, accel = Vector3.new(0, 3.5, 0),
            spread = 55, rotsp = { -80, 80 }, le = 1, drag = 1.4, slab = 100, height = 12,
        },
        Blossom = {
            tex = SPARK, color = Color3.fromRGB(255, 178, 210), rate = 120,
            size = ns2(0, 0.34, 1, 0.3), tr = ns2(0, 0.12, 0.85, 0.25, 1, 1),
            life = { 6, 9 }, speed = { 4, 9 }, accel = Vector3.new(0, -7, 0),
            spread = 32, rotsp = { -110, 110 }, le = 0.25, drag = 1.8, slab = 130, height = 50,
        },
        Fireflies = {
            tex = SPARK, color = Color3.fromRGB(190, 255, 120), rate = 55,
            size = ns2(0, 0.14, 0.5, 0.2, 1, 0.14), tr = ns2(0, 1, 0.25, 0.15, 0.75, 0.15, 1, 1),
            life = { 5, 8 }, speed = { 1, 3 }, accel = Vector3.new(0, 0.4, 0),
            spread = 180, rotsp = { -30, 30 }, le = 1, drag = 2.2, slab = 90, height = 14,
        },
        Sandstorm = {
            tex = SMOKE, color = Color3.fromRGB(214, 184, 128), rate = 400,
            size = ns2(0, 1.6, 1, 3.2), tr = ns2(0, 0.72, 0.6, 0.78, 1, 1),
            life = { 2.2, 3.4 }, speed = { 55, 85 }, accel = Vector3.new(0, -6, 0),
            spread = 22, rotsp = { -40, 40 }, le = 0, drag = 0.6, slab = 150, height = 26,
            sideways = true,
        },
    }
    local WEATHER_NAMES = { "Off", "Rain", "Snow", "Storm", "Ash", "Embers", "Blossom", "Fireflies", "Sandstorm" }

    local SOUNDS = {
        Rain      = 9112854440,
        Downpour  = 5410086218,
        Storm     = 1848354536,
        Wind      = 1836160504,
        Gale      = 1837879082,
        Forest    = 9046863579,
    }
    local SOUND_NAMES = { "Rain", "Downpour", "Storm", "Wind", "Gale", "Forest" }
    local THUNDER_ID = 5801257793

    local rig, emitter, conn
    local wSound, aSound

    local function teardownParticles()
        if conn then pcall(function() conn:Disconnect() end); conn = nil end
        if rig then pcall(function() rig:Destroy() end); rig = nil end
        emitter = nil
    end

    local function buildParticles()
        teardownParticles()
        local def = WEATHER[S.Weather]
        if not def then return end
        local cam = workspace.CurrentCamera
        if not cam then return end

        rig = Instance.new("Part")
        rig.Name = "InertiaWeather"
        rig.Anchored = true
        rig.CanCollide = false
        rig.CanQuery = false
        rig.CanTouch = false
        rig.CastShadow = false
        rig.Transparency = 1
        local slab = MOBILE and math.min(def.slab, 100) or def.slab
        rig.Size = Vector3.new(slab, 1, slab)
        rig.CFrame = CFrame.new(cam.CFrame.Position + Vector3.new(0, def.height, 0))
        rig.Parent = workspace

        local intensity = math.clamp(tonumber(S.WeatherIntensity) or 60, 1, 100) / 100
        emitter = Instance.new("ParticleEmitter")
        emitter.Name = "InertiaWeather"
        emitter.Texture = def.tex
        emitter.Color = ColorSequence.new(def.color)
        emitter.Size = def.size
        emitter.Transparency = def.tr
        emitter.Lifetime = NumberRange.new(def.life[1], def.life[2])
        emitter.Speed = NumberRange.new(def.speed[1], def.speed[2])
        emitter.SpreadAngle = Vector2.new(def.spread, def.spread)
        emitter.Rate = math.clamp(def.rate * intensity, 1, MOBILE and 180 or 720)
        emitter.Drag = def.drag or 0
        emitter.LightEmission = def.le or 0
        emitter.LightInfluence = 0
        emitter.LockedToPart = false
        emitter.EmissionDirection = def.sideways and Enum.NormalId.Front or Enum.NormalId.Bottom
        if def.rotsp then emitter.RotSpeed = NumberRange.new(def.rotsp[1], def.rotsp[2]) end

        if def.squash then pcall(function() emitter.Squash = def.squash end) end
        if def.squash then emitter.Orientation = Enum.ParticleOrientation.VelocityParallel end
        emitter.Parent = rig

        local wind = math.clamp(tonumber(S.WeatherWind) or 30, 0, 100) / 100
        conn = RunService.Heartbeat:Connect(function()
            if not rig or not rig.Parent then return end
            local c = workspace.CurrentCamera
            if not c then return end
            local pos = c.CFrame.Position + Vector3.new(0, def.height, 0)
            rig.CFrame = CFrame.new(pos)
            if wind > 0.01 and emitter then
                local right = c.CFrame.RightVector
                emitter.Acceleration = def.accel + right * (wind * 55)
            elseif emitter then
                emitter.Acceleration = def.accel
            end
        end)
    end

    local function stopSound(s)
        if s then pcall(function() s:Stop(); s:Destroy() end) end
        return nil
    end

    local function makeLoop(id, volume)
        local s = Instance.new("Sound")
        s.Name = "InertiaEnvSound"
        s.SoundId = "rbxassetid://" .. id
        s.Looped = true
        s.Volume = math.clamp((tonumber(volume) or 40) / 100, 0, 1)

        s.Parent = game:GetService("SoundService")

        pcall(function() s:SetAttribute("InertiaOwned", true) end)
        S._PlaySoundSafe(s)
        return s
    end

    local function refreshWeatherSound()
        wSound = stopSound(wSound)
        if not S.WeatherSound then return end
        local id = SOUNDS[S.WeatherSoundName] or SOUNDS.Rain
        wSound = makeLoop(id, tonumber(S.WeatherSoundVolume) or 40)
    end

    local function refreshAmbientSound()
        aSound = stopSound(aSound)
        if not S.AmbientSound then return end
        local id = SOUNDS[S.AmbientSoundName] or SOUNDS.Forest
        aSound = makeLoop(id, tonumber(S.AmbientSoundVolume) or 30)
    end

    local function refreshAll()
        buildParticles()
        refreshWeatherSound()
        refreshAmbientSound()
    end
    S._RefreshWeather = refreshAll

    tt(function()
        while S.Gui and S.Gui.Parent do
            if S.WeatherThunder and (S.Weather == "Storm" or S.Weather == "Rain") then
                task.wait(math.random(70, 220) / 10)
                if S.WeatherThunder and (S.Weather == "Storm" or S.Weather == "Rain") and not S.Destroyed then
                    pcall(function()
                        local s = Instance.new("Sound")
                        s.Name = "InertiaEnvSound"
                        s.SoundId = "rbxassetid://" .. THUNDER_ID
                        s.Volume = math.clamp((tonumber(S.WeatherSoundVolume) or 40) / 100, 0, 1)
                        s.Parent = game:GetService("SoundService")
                        pcall(function() s:SetAttribute("InertiaOwned", true) end)
                        S._PlaySoundSafe(s)
                        game:GetService("Debris"):AddItem(s, 6)
                        local flash = Instance.new("ColorCorrectionEffect")
                        flash.Name = "InertiaLightningFlash"
                        flash.Brightness = 0.45
                        flash.Contrast = 0.08
                        flash.TintColor = Color3.fromRGB(220, 232, 255)
                        flash.Parent = Lighting2
                        game:GetService("Debris"):AddItem(flash, 1)
                        task.wait(0.08)
                        if flash.Parent then flash.Brightness = 0 end
                        task.wait(0.06)
                        if flash.Parent then flash.Brightness = 0.22 end
                        task.wait(0.07)
                        if flash.Parent then flash:Destroy() end
                    end)
                end
            else
                task.wait(1)
            end
        end
    end)

    local secWeather = mkSection(Pages.Visuals, "Environment", 5, true)
    if S._RegisterVisualsEnvSection then pcall(S._RegisterVisualsEnvSection, secWeather) end
    mkCycle(secWeather, "Weather", WEATHER_NAMES, "Off", function(v)
        S.Weather = v
        buildParticles()
    end, 1)
    mkSlider(secWeather, "Intensity (%)", 1, 100, 60, function(v)
        S.WeatherIntensity = v
        buildParticles()
    end, 2)
    mkSlider(secWeather, "Wind (%)", 0, 100, 30, function(v)
        S.WeatherWind = v
        buildParticles()
    end, 3)

    mkToggle(secWeather, "Weather Sound", false, function(v) S.WeatherSound = v; refreshWeatherSound() end, 4)
    mkCycle(secWeather, "Weather Sound Track", SOUND_NAMES, "Rain", function(v)
        S.WeatherSoundName = v
        refreshWeatherSound()
    end, 5)
    mkSlider(secWeather, "Weather Volume (%)", 0, 100, 40, function(v)
        S.WeatherSoundVolume = v
        if wSound then wSound.Volume = math.clamp(v / 100, 0, 1) end
    end, 6)
    mkToggle(secWeather, "Thunder", false, function(v) S.WeatherThunder = v end, 7)

    mkToggle(secWeather, "Ambient Sound", false, function(v) S.AmbientSound = v; refreshAmbientSound() end, 8)
    mkCycle(secWeather, "Ambient Track", SOUND_NAMES, "Forest", function(v)
        S.AmbientSoundName = v
        refreshAmbientSound()
    end, 9)
    mkSlider(secWeather, "Ambient Volume (%)", 0, 100, 30, function(v)
        S.AmbientSoundVolume = v
        if aSound then aSound.Volume = math.clamp(v / 100, 0, 1) end
    end, 10)

    cleanup(function()
        teardownParticles()
        wSound = stopSound(wSound)
        aSound = stopSound(aSound)
        local flash = Lighting2:FindFirstChild("InertiaLightningFlash")
        if flash then pcall(function() flash:Destroy() end) end
        S._RefreshWeather = nil
    end)

    tt(function()
        task.wait(3)
        if not S.Destroyed then pcall(refreshAll) end
    end)
end
task.delay(3, function() pcall(refreshAll) end)

